/// spell_color (spells1.cc:1059): the TERM_* palette index used to draw a
/// bolt/ball of the given damage type, including the original randint
/// branches and the multi-hued picks.  The port's tile renderer never
/// draws projections, but the table is kept faithful for effect overlays.
#[allow(dead_code)]
pub fn spell_color(gf: &str, rng: &mut impl Rng) -> u8 {
    match gf {
        "MISSILE" => 2,                                       // TERM_SLATE
        "ACID" => if crate::rng::randint(5, rng) < 3 { 11 } else { 13 },
        "ELEC" => {
            if crate::rng::randint(7, rng) < 6 {
                1
            } else if crate::rng::randint(4, rng) == 1 {
                6
            } else {
                14
            }
        }
        "FIRE" => {
            if crate::rng::randint(6, rng) < 4 {
                11
            } else if crate::rng::randint(4, rng) == 1 {
                4
            } else {
                12
            }
        }
        "COLD" => if crate::rng::randint(6, rng) < 4 { 1 } else { 9 },
        "POIS" => if crate::rng::randint(5, rng) < 3 { 13 } else { 5 },
        "UNBREATH" => if crate::rng::randint(7, rng) < 3 { 13 } else { 5 },
        "HOLY_FIRE" => if crate::rng::randint(5, rng) == 1 { 3 } else { 1 },
        "HELL_FIRE" => if crate::rng::randint(6, rng) == 1 { 4 } else { 8 },
        "MANA" => if crate::rng::randint(5, rng) != 1 { 10 } else { 14 },
        "ARROW" => 15,                                        // TERM_L_UMBER
        "WATER" | "WAVE" => if crate::rng::randint(4, rng) == 1 { 14 } else { 6 },
        "NETHER" => if crate::rng::randint(4, rng) == 1 { 2 } else { 8 },
        "CHAOS" => crate::colors::mh_attr(15, rng),
        "DISENCHANT" | "DISEN" => {
            if crate::rng::randint(5, rng) != 1 { 14 } else { 10 }
        }
        "NEXUS" => if crate::rng::randint(5, rng) < 3 { 12 } else { 10 },
        "CONFUSION" | "CONF" => crate::colors::mh_attr(4, rng),
        "SOUND" => if crate::rng::randint(4, rng) == 1 { 10 } else { 1 },
        "SHARDS" => if crate::rng::randint(5, rng) < 3 { 7 } else { 2 },
        "FORCE" => if crate::rng::randint(5, rng) < 3 { 9 } else { 3 },
        "INERTIA" => if crate::rng::randint(5, rng) < 3 { 2 } else { 9 },
        "GRAVITY" => if crate::rng::randint(3, rng) == 1 { 15 } else { 7 },
        "TIME" => if crate::rng::randint(2, rng) == 1 { 1 } else { 8 },
        "LITE_WEAK" => if crate::rng::randint(3, rng) == 1 { 3 } else { 11 },
        "LITE" => if crate::rng::randint(4, rng) == 1 { 3 } else { 11 },
        "DARK_WEAK" => if crate::rng::randint(3, rng) == 1 { 0 } else { 8 },
        "DARK" => if crate::rng::randint(4, rng) == 1 { 0 } else { 8 },
        "PLASMA" => if crate::rng::randint(5, rng) == 1 { 4 } else { 12 },
        "METEOR" => if crate::rng::randint(3, rng) == 1 { 4 } else { 7 },
        "ICE" => if crate::rng::randint(4, rng) == 1 { 14 } else { 1 },
        "ROCKET" => {
            if crate::rng::randint(6, rng) < 4 {
                12
            } else if crate::rng::randint(4, rng) == 1 {
                4
            } else {
                15
            }
        }
        "DEATH" | "DEATH_RAY" => 8,                          // TERM_L_DARK
        "NUKE" => crate::colors::mh_attr(2, rng),
        "DISINTEGRATE" => {
            if crate::rng::randint(3, rng) != 1 {
                8
            } else if crate::rng::randint(2, rng) == 1 {
                3
            } else {
                15
            }
        }
        "PSI" | "PSI_DRAIN" | "TELEKINESIS" | "DOMINATION" => {
            if crate::rng::randint(3, rng) != 1 { 14 } else { 1 }
        }
        "INSTA_DEATH" => 0,                                  // TERM_DARK
        "ELEMENTAL_WALL" | "ELEMENTAL_GROWTH" => 5,          // TERM_GREEN
        _ => 1,                                              // TERM_WHITE
    }
}

/// bolt_pict (spells1.cc:1161): the (attr, char) pair a spell effect
/// moving from (x, y) to (nx, nx) draws with.  The original indexes the
/// misc_to_attr/char flavour table; the shipped default font pref
/// (lib/pref/font-xxx.prf S: lines) defines base 0x30 '*' / 0x40 '|' /
/// 0x50 '-' / 0x60 '/' / 0x70 '\' with the spell colour as the attribute,
/// so the port derives the pair directly.  The tile renderer never draws
/// projections; the helper is kept faithful for effect overlays.
#[allow(dead_code)]
pub fn bolt_pict(y: i32, x: i32, ny: i32, nx: i32, gf: &str, rng: &mut impl Rng) -> (u8, char) {
    let base = if ny == y && nx == x {
        0x30
    } else if nx == x {
        0x40
    } else if ny == y {
        0x50
    } else if (ny - y) == (x - nx) {
        0x60
    } else if (ny - y) == (nx - x) {
        0x70
    } else {
        0x30
    };
    let attr = spell_color(gf, rng);
    let ch = match base {
        0x40 => '|',
        0x50 => '-',
        0x60 => '/',
        0x70 => '\\',
        _ => '*',
    };
    (attr, ch)
}

/// One damage-type hit on a monster (spells1.cc project_m): final damage
/// plus the status side effects. `player_level` drives GF_GRAVITY's stun.
#[derive(Default)]
pub struct GfMonsterEffect {
    pub dam: i32,
    pub conf: i32,
    pub stun: i32,
    pub cut: i32,
    pub poison: i32,
    pub slow: bool,
    pub teleport: bool,
    /// Polymorph the victim (GF_CHAOS / GF_NUKE / GF_OLD_POLY).
    pub poly: bool,
    /// Cells to push the victim away from the caster (player-cast
    /// GF_FORCE / GF_WAVE, spells1.cc project_m who==0).
    pub push: i32,
    /// Hit points healed by GF_RAISE (spells1.cc project_m).
    pub heal: i32,
    /// GF_PSI backlash: a powerful demon/undead turns the attack on the
    /// player (the caller must resolve the mental damage).
    pub psi_backlash: bool,
    /// Fear granted by GF_PSI (the caller applies it to the monster).
    pub fear: i32,
    /// GF_ATTACK: perform a weapon blow instead of damage (the caller
    /// owns the attack; no central representation exists here).
    pub attack: bool,
    /// The projection enrages a friendly/pet victim (spells1.cc:4201
    /// get_angry); the caller calls `change_side`.
    pub angry: bool,
}

/// change_side (monster3.cc:94): a friend or pet joins the monsters.
/// The port maps MSTATUS_FRIEND/MSTATUS_PET onto `friendly` and
/// MSTATUS_COMPANION onto `companion`; companions never change side.
/// An animal friend (and not EVIL) angering costs Yavanna -4*level
/// piety.  Neutral monsters flip their stance.  Returns true if the
/// side changed (the caller prints "%s gets angry!").
pub fn change_side(
    gd: &GameData,
    m: &mut Monster,
    ps: &mut PlayerState,
    _log: &mut MessageLog,
) -> bool {
    let def = &gd.monsters[m.def];
    if m.companion && !m.friendly {
        // MSTATUS_COMPANION: loyal; controlled monsters likewise.
        return false;
    }
    if m.neutral {
        // MSTATUS_NEUTRAL_P <-> MSTATUS_NEUTRAL_M: the port keeps a single
        // neutral flag, so provoking it is the observable change.
        m.neutral = false;
        m.awake = true;
        return true;
    }
    if !m.friendly {
        return false;
    }
    m.friendly = false;
    m.awake = true;
    if def.has("ANIMAL") && !def.has("EVIL") && ps.god == 5 {
        let lvl = monster_level(gd, m);
        ps.grace = (ps.grace - lvl * 4).max(-300000);
    }
    true
}

/// can_create_companion (monster3.cc:323): the companion cap is
/// 1 + skill_scale(SKILL_LORE, 6).
pub fn companion_cap(ps: &PlayerState) -> i32 {
    1 + ps.skill_scale(crate::skill::SK_LORE, 6)
}

/// do_cmd_companion (monster3.cc:662): promote a targeted MSTATUS_PET to
/// a faithful companion.  `companions` is the live MSTATUS_COMPANION
/// count.  Returns the pet's name on success, or the original refusal
/// message.  The targeting itself stays with the caller (modal.rs).
pub fn promote_companion(
    gd: &GameData,
    ps: &PlayerState,
    companions: i32,
    m: &mut Monster,
) -> Result<String, String> {
    if companions >= companion_cap(ps) {
        return Err("You cannot have any more companions.".to_string());
    }
    if !m.pet {
        return Err(format!("{} is not your pet!", gd.monsters[m.def].name));
    }
    m.pet = false;
    m.companion = true;
    m.awake = true;
    Ok(gd.monsters[m.def].name.clone())
}

/// do_melkor_curse (spells3.cc:1920): the L35 max-HP cut, the L25 speed
/// cut, the L15 AC cut and the per-blow dice reduction.  The instance
/// results live on the Monster (`max_hp`/`mspeed_mod`/`ac_mod`/
/// `blow_penalty`); modal.rs's spell application calls this.
pub fn melkor_curse_monster(
    gd: &GameData,
    ps: &PlayerState,
    inv: &Inventory,
    m: &mut Monster,
    log: &mut MessageLog,
) {
    let Some(sp) = gd.spell_by_name("Curse") else {
        return;
    };
    let hside = Dice::parse(&gd.monsters[m.def].hp)
        .map(|d| d.sides)
        .unwrap_or(1);
    let l50 = crate::spell::get_level_s(ps, inv, gd, sp, 50);
    if l50 >= 35 {
        m.max_hp = (m.max_hp - hside).max(1);
        m.hp = m.hp.min(m.max_hp);
    }
    if l50 >= 25 {
        let pow = crate::spell::get_level_s(ps, inv, gd, sp, 7);
        m.mspeed_mod -= pow;
    }
    if l50 >= 15 {
        m.ac_mod = (m.ac_mod - l50).max(-70);
    }
    // Reduce melee too: get_level_s(CURSE, 2) is clamped to the smallest
    // dice count/sides among the first four blows, then every blow loses
    // that many dice (spells3.cc:1969-1992).
    let mut pow = crate::spell::get_level_s(ps, inv, gd, sp, 2);
    for blow in gd.monsters[m.def].blows.iter().take(4) {
        let Some(d) = Dice::parse(&blow.dice) else {
            break;
        };
        if d.count <= 0 {
            break;
        }
        if d.count < pow {
            pow = d.count;
        }
        if d.sides < pow {
            pow = d.sides;
        }
    }
    m.blow_penalty = pow.max(0);
    m.awake = true;
    log.add(format!("The {} looks weaker.", gd.monsters[m.def].name));
}

/// A monster blow's damage dice, less the instance melkor-curse penalty
/// and plus the monster_check_experience dice gains.
pub fn roll_blow_dice(
    blow: &crate::data::BlowDef,
    penalty: i32,
    bonus: i32,
    rng: &mut impl Rng,
) -> i32 {
    let mut dice = Dice::parse(&blow.dice).unwrap_or(Dice {
        count: 0,
        sides: 1,
        bonus: 0,
    });
    if penalty > 0 {
        dice.count = (dice.count - penalty).max(0);
    }
    dice.count += bonus.max(0);
    dice.roll(rng)
}

/// The per-instance blow-dice bonus for blow index `i`
/// (monster_check_experience level gains; the attacker's MonsterExtra).
fn blow_dice_bonus(extra: Option<&MonsterExtra>, i: usize) -> i32 {
    extra.and_then(|x| x.blow_bonus.get(i).copied()).unwrap_or(0)
}

/// do_poly_monster (spells1.cc poly_r_idx): replace the monster with a
/// random non-unique race of similar level. Returns the new race name.
pub fn poly_monster(gd: &GameData, m: &mut Monster, rng: &mut impl Rng) -> Option<String> {
    let level = monster_level(gd, m);
    poly_monster_at(gd, m, level, rng)
}

/// poly_r_idx at an explicit dungeon level: `get_mon_num((dun_level +
/// level)/2 + 5)` weighting, non-unique races only.  The original
/// returns the same race for a unique caster (no polymorph); the port's
/// caller treats `None` as "nothing changed".
pub fn poly_monster_at(
    gd: &GameData,
    m: &mut Monster,
    dun_level: i32,
    rng: &mut impl Rng,
) -> Option<String> {
    let def = &gd.monsters[m.def];
    // Hack -- Uniques never polymorph (poly_r_idx).
    if def.unique {
        return None;
    }
    let level = ((dun_level + monster_level(gd, m)) / 2 + 5).max(1) as u32;
    let candidates: Vec<usize> = (0..gd.monster_base_count)
        .filter(|&i| {
            let d = &gd.monsters[i];
            !d.unique
                && d.depth >= 1
                && !d.has("JOKEANGBAND")
                && !d.has("WILD_ONLY")
                && !d.has("SPECIAL_GENE")
                && !d.has("NEVER_GENE")
        })
        .collect();
    let new_def = get_mon_num_from(gd, level, &candidates, rng)?;
    let new_name = gd.monsters[new_def].name.clone();
    let new_hp = roll_monster_hp(&gd.monsters[new_def], rng);
    m.def = new_def;
    m.max_hp = new_hp.max(1);
    m.hp = m.hp.min(m.max_hp);
    m.mimic = 0;
    Some(new_name)
}

/// The high-resistance roll shared by the GF table: 3/(1d6+6).
pub fn gf_resist(dam: i32, rng: &mut impl Rng) -> i32 {
    dam * 3 / (rng.gen_range(1..=6) + 6)
}

/// Rune ids and the inscription table (defines.hpp INSCRIP_*,
/// tables.cc inscription_info): (text, trigger flags, mana cost).
pub const INSCRIP_LIGHT: u8 = 1;
pub const INSCRIP_DARK: u8 = 2;
pub const INSCRIP_STORM: u8 = 3;
pub const INSCRIP_PROTECTION: u8 = 4;
pub const INSCRIP_DWARF_SUMMON: u8 = 5;
pub const INSCRIP_CHASM: u8 = 6;
pub const INSCRIP_BLACK_FIRE: u8 = 7;

pub const INSCRIP_EXEC_ENGRAVE: u8 = 1;
pub const INSCRIP_EXEC_WALK: u8 = 2;
pub const INSCRIP_EXEC_MONST_WALK: u8 = 4;

pub const INSCRIPTIONS: [(&str, u8, u8); 8] = [
    ("", 0, 0),
    ("ure nimir", 7, 30),
    ("lomi gimli", 7, 10),
    ("dulgi bawiba", 7, 40),
    ("pedo mellon a minno", 4, 8),
    ("Baruk Khazad! Khazad aimenu!", 1, 100),
    ("dunna hrassa", 4, 50),
    ("burz ghash ronk", 7, 60),
];

/// Whether the player has learned rune `id` (rune parchments,
/// cmd6.cc:3220).
pub fn rune_known(ps: &PlayerState, id: u8) -> bool {
    ps.inscriptions.get(id as usize).copied().unwrap_or(false)
}

/// Learn a rune from a parchment (cmd6.cc:3220).
pub fn rune_learn(ps: &mut PlayerState, id: u8) {
    if ps.inscriptions.len() < INSCRIPTIONS.len() {
        ps.inscriptions.resize(INSCRIPTIONS.len(), false);
    }
    if !ps.inscriptions[id as usize] {
        ps.inscriptions[id as usize] = true;
    }
}

/// What a fired rune leaves for the caller to resolve (the monster
/// queries differ between input.rs and monster_turns).
pub enum InscriptionBlast {
    /// Nothing more (light/dark/summon/chasm handled inside).
    None,
    /// PROTECTION bars the monster's step (mana already spent).
    Blocked,
    /// An elemental blast radius 3 around the rune: (gf, damage).
    Blast(&'static str, i32),
}

/// execute_inscription (cmd1.cc:4381): fire rune `id` at cell (x, y).
/// `victim` is the monster standing on it for MONST_WALK triggers.
/// Grid mana is spent before the effect and never restored; an
/// underfed rune fizzles silently (returns None and does not block).
#[allow(clippy::too_many_arguments)]
pub fn execute_inscription(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &mut Map,
    stacks: &mut Query<
        (Entity, &GridPos, &mut item::FloorItem),
        impl bevy::ecs::query::QueryFilter,
    >,
    x: i32,
    y: i32,
    id: u8,
    victim: Option<(Entity, usize)>,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) -> InscriptionBlast {
    let ci = Map::idx(x, y);
    let (_, _, cost) = INSCRIPTIONS[id as usize];
    let mana = map.mana.get(ci).copied().unwrap_or(0);
    if (mana as i32) < cost as i32 {
        return InscriptionBlast::None;
    }
    if let Some(cell) = map.mana.get_mut(ci) {
        *cell = (*cell as i32 - cost as i32).max(0) as u8;
    }
    match id {
        INSCRIP_LIGHT => {
            log.add("The inscription shines in a bright light!");
            map::light_area(map, x, y, 4);
        }
        INSCRIP_DARK => {
            log.add("The inscription is enveloped in a dark aura!");
            for dy in -1..=1 {
                for dx in -1..=1 {
                    let (cx, cy) = (x + dx, y + dy);
                    if Map::in_bounds(cx, cy) {
                        map.lit[Map::idx(cx, cy)] = false;
                    }
                }
            }
        }
        INSCRIP_STORM => {
            log.add("The inscription releases a powerful storm!");
            let dam = Dice {
                count: 10,
                sides: 10,
                bonus: 0,
            }
            .roll(rng);
            return InscriptionBlast::Blast("ELEC", dam);
        }
        INSCRIP_BLACK_FIRE => {
            log.add("The inscription releases a blast of hellfire!");
            return InscriptionBlast::Blast("HELL_FIRE", 200);
        }
        INSCRIP_PROTECTION => {
            return InscriptionBlast::Blocked;
        }
        INSCRIP_DWARF_SUMMON => {
            if let Some(def) = gd.monster_by_name("Dwarven Warrior") {
                for _ in 0..20 {
                    let (nx, ny) = (x + rng.gen_range(-3..=3), y + rng.gen_range(-3..=3));
                    if map.walkable(gd, nx, ny) {
                        spawn_single(commands, gd, tiles, def, nx, ny, true, false, rng);
                        log.add("A Dwarven Warrior answers the call!");
                        break;
                    }
                }
            }
        }
        INSCRIP_CHASM => {
            map.set_terrain(x, y, map::T_DARK_PIT);
            log.add("A chasm appears in the floor!");
            if let Some((e, def_idx)) = victim {
                let def = &gd.monsters[def_idx];
                if def.has("CAN_FLY") {
                    log.add("The monster simply flies over the chasm.");
                } else if !def.unique {
                    log.add("The monster falls in the chasm!");
                    commands.entity(e).despawn();
                }
            }
            // Non-artifact items on the grid fall in (cmd1.cc).
            let mut gone: Vec<Entity> = Vec::new();
            for (se, sp, stack) in stacks.iter() {
                if sp.x == x && sp.y == y && !stack.stack.iter().any(|it| it.artifact != 0) {
                    gone.push(se);
                }
            }
            for se in gone {
                commands.entity(se).despawn();
            }
        }
        _ => {}
    }
    InscriptionBlast::None
}

/// Apply a rune blast (radius 3) to the monsters and the player; the
/// rune is player-engraved, so kills grant experience (project who=0,
/// cmd1.cc:4381).
#[allow(clippy::too_many_arguments)]
pub fn rune_blast(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &mut Map,
    ps: &mut PlayerState,
    inv: &mut Inventory,
    plot: &mut PlotQuest,
    created: &mut HashSet<u32>,
    monsters: &mut Query<(Entity, &mut Monster, &GridPos), Without<Player>>,
    stacks: &mut Query<
        (Entity, &GridPos, &mut item::FloorItem),
        impl bevy::ecs::query::QueryFilter,
    >,
    x: i32,
    y: i32,
    gf: &str,
    dam: i32,
    player_pos: (i32, i32),
    next: &mut NextState<AppState>,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    let mut dead: Vec<(Entity, usize, (i32, i32))> = Vec::new();
    for (e, mut m, mp) in monsters.iter_mut() {
        if map::chebyshev(mp.x, mp.y, x, y) > 3 {
            continue;
        }
        let eff = gf_monster_effect(&gd.monsters[m.def], gf, dam, ps.level as i32, true, rng);
        m.hp -= eff.dam.max(1);
        if eff.angry {
            change_side(gd, &mut m, ps, log);
        }
        if m.hp <= 0 {
            dead.push((e, m.def, (mp.x, mp.y)));
        }
    }
    for (e, def_idx, pos) in dead {
        let (ha, ho, hi, hg, lo) = {
            let (_, m, _) = monsters.get(e).expect("monster");
            (
                m.held_artifact,
                m.held_object,
                m.items.clone(),
                m.gold,
                m.looted,
            )
        };
        let enemy_left = monsters
            .iter()
            .filter(|(qe, m, _)| {
                *qe != e && !m.friendly && !m.companion && !m.neutral
            })
            .count() as i32;
        kill_monster(
            commands, gd, tiles, stacks, e, def_idx, pos, ha, ho, hi, hg, lo, ps, plot, map,
            -1, enemy_left, created, inv, log, rng, false,
        );
    }
    // The player may stand in the blast.
    if map::chebyshev(player_pos.0, player_pos.1, x, y) <= 3 {
        let totals = inv.totals_for(gd, ps);
        let d = apply_gf(gd, ps, inv, &totals, gf, dam, log, rng);
        player_hurt(ps, d, log, rng);
        if ps.hp <= 0 && player_death_check(ps, gd, log) {
            log.add("You die.");
            next.set(AppState::Dead);
        }
    }
}

/// Resolve one damage type against a monster (spells1.cc project_m; the
/// types the Power Mage and Geomancy can produce). `from_player` is the
/// original who==0 distinction (GF_FORCE/WAVE push instead of stun).
pub fn gf_monster_effect(
    def: &crate::data::MonsterDef,
    gf: &str,
    dam: i32,
    player_level: i32,
    from_player: bool,
    rng: &mut impl Rng,
) -> GfMonsterEffect {
    let br = |s: &str| def.spells.iter().any(|x| x == s);
    let level = def.depth.max(1) as i32;
    let unique = def.unique;
    let mut e = GfMonsterEffect {
        dam,
        ..Default::default()
    };
    match gf {
        "UNBREATH" => {
            // GF_UNBREATH: thick poison, but the undead and unliving are
            // immune (spells1.cc:4448).
            if rng.gen_range(0..100) < 15 {
                e.poison = (10 + rng.gen_range(1..=11) + player_level) / (player_level + 1);
            }
            if def.has("UNDEAD") || def.has("NONLIVING") {
                e.dam = 0;
                e.poison = 0;
            }
        }
        "FIRE" | "ELEC" | "COLD" | "ACID" => {
            if def.has(&format!("SUSCEP_{}", gf)) {
                e.dam *= 3;
            }
            if def.has(&format!("IM_{}", gf)) {
                e.dam /= 9;
            }
        }
        "POIS" => {
            if rng.gen_bool(0.25) {
                e.poison = (10 + rng.gen_range(1..=11) + player_level) / (player_level + 1);
            }
            if def.has("SUSCEP_POIS") {
                e.dam *= 3;
                e.poison *= 2;
            }
            if def.has("IM_POIS") {
                e.dam /= 9;
                e.poison = 0;
            }
        }
        "ICE" => {
            e.stun = rng.gen_range(1..=15);
            if rng.gen_bool(1.0 / 3.0) {
                e.cut = 10 + rng.gen_range(1..=15);
            }
            if def.has("SUSCEP_COLD") {
                e.dam *= 3;
                e.cut *= 2;
            }
            if def.has("IM_COLD") {
                e.dam /= 9;
                e.cut = 0;
            }
        }
        "PLASMA" => {
            if def.has("RES_PLAS") {
                e.dam = gf_resist(e.dam, rng);
            }
        }
        "NETHER" => {
            if def.has("UNDEAD") {
                e.dam = 0;
            } else if def.has("RES_NETH") {
                e.dam = gf_resist(e.dam, rng);
            } else if def.has("EVIL") {
                e.dam /= 2;
            }
        }
        "WATER" | "WAVE" => {
            if def.has("RES_WATE") {
                e.dam = gf_resist(e.dam, rng);
            }
            // Player-cast waves shove like force (spells1.cc:4575).
            if gf == "WAVE" && from_player {
                e.push = 2;
            }
        }
        "NEXUS" => {
            if def.has("RES_NEXU") {
                e.dam = gf_resist(e.dam, rng);
            }
        }
        "DISENCHANT" => {
            if def.has("RES_DISE") {
                e.dam = gf_resist(e.dam, rng);
            }
        }
        "CHAOS" => {
            // GF_CHAOS: confusion plus polymorph (spells1.cc:4668).
            e.conf = 5 + rng.gen_range(1..=11);
            e.poly = true;
            if br("BR_CHAO") || (def.has("DEMON") && rng.gen_bool(1.0 / 3.0)) {
                e.dam = gf_resist(e.dam, rng);
                e.conf = 0;
                e.poly = false;
            }
        }
        "NUKE" => {
            // GF_NUKE: poison-immune monsters resist; otherwise one in
            // three victims mutates (spells1.cc:4462).
            if def.has("IM_POIS") {
                e.dam = gf_resist(e.dam, rng);
            } else if rng.gen_range(1..=3) == 1 {
                e.poly = true;
            }
        }
        "DISINTEGRATE" => {
            // GF_DISINTEGRATE: rock-creation monsters take double;
            // uniques may shrug off most of it (spells1.cc:4990).
            if def.has("HURT_ROCK") {
                e.dam *= 2;
            }
            if unique
                && rng.gen_range(0..(level + 10).max(1)) > rng.gen_range(0..player_level.max(1))
            {
                e.dam >>= 3;
            }
        }
        "SHARDS" => {
            if rng.gen_bool(1.0 / 3.0) {
                e.cut = 10 + rng.gen_range(1..=15);
            }
            if br("BR_SHAR") {
                e.dam = gf_resist(e.dam, rng);
                e.cut = 0;
            }
        }
        "SOUND" => {
            e.stun = 10 + rng.gen_range(1..=15);
            if br("BR_SOUN") {
                e.dam = e.dam * 2 / (rng.gen_range(1..=6) + 6);
            }
        }
        "CONF" => {
            e.conf = 10 + rng.gen_range(1..=15);
            if br("BR_CONF") {
                e.dam = e.dam * 2 / (rng.gen_range(1..=6) + 6);
                e.conf = 0;
            } else if def.has("NO_CONF") {
                e.dam /= 2;
                e.conf = 0;
            }
        }
        "INERTIA" => {
            if br("BR_INER") {
                e.dam = gf_resist(e.dam, rng);
            } else if !unique && level <= rng.gen_range(1..=(e.dam - 10).max(1)) + 10 {
                // Monsters below 60 speed cannot be slowed any further
                // (spells1.cc:4918; base speed stands in for mspeed).
                if def.speed > 60 {
                    e.slow = true;
                }
            }
        }
        "GRAVITY" => {
            // Teleport save: RES_TELE monsters resist on randint(100),
            // uniques always (spells1.cc:4918).
            let tele_resist = def.has("RES_TELE") && (unique || level > rng.gen_range(1..=100));
            e.teleport = !tele_resist;
            if br("BR_GRAV") {
                e.dam = gf_resist(e.dam, rng);
                e.teleport = false;
            } else {
                let saved = unique || level > rng.gen_range(1..=(e.dam - 10).max(1)) + 10;
                if !saved {
                    if def.speed > 60 {
                        e.slow = true;
                    }
                    // do_stun = damroll(lev/10 + 3, dam) + 1 (spells1.cc).
                    let mut stun = 1;
                    for _ in 0..(player_level / 10 + 3).max(1) {
                        stun += rng.gen_range(1..=e.dam.max(1));
                    }
                    e.stun = stun;
                }
            }
        }
        "TIME" => {
            if br("BR_TIME") {
                e.dam = gf_resist(e.dam, rng);
            }
        }
        "FORCE" => {
            if br("BR_WALL") {
                e.dam = gf_resist(e.dam, rng);
            } else if from_player {
                // Player-cast force shoves the victim two cells
                // (spells1.cc:4781 who==0).
                e.push = 2;
            } else {
                e.stun = rng.gen_range(1..=15);
            }
        }
        "LITE" => {
            if br("BR_LITE") {
                e.dam = e.dam * 2 / (rng.gen_range(1..=6) + 6);
            } else if def.has("HURT_LITE") {
                e.dam *= 2;
            }
        }
        "DARK" => {
            if br("BR_DARK") || def.has("ORC") || def.has("HURT_LITE") {
                e.dam = e.dam * 2 / (rng.gen_range(1..=6) + 6);
            }
        }
        "KILL_WALL" => {
            if !def.has("HURT_ROCK") {
                e.dam = 0;
            }
        }
        "HOLY_FIRE" => {
            if def.has("GOOD") {
                e.dam = 0;
            } else if def.has("EVIL") {
                e.dam *= 2;
            } else {
                e.dam = gf_resist(e.dam, rng);
            }
        }
        "HELL_FIRE" => {
            if def.has("EVIL") {
                e.dam *= 2;
            }
        }
        // GF_PSI (spells1.cc:5023): mindless-ish monsters resist; strong
        // demons/undead can backlash the mindcrafter instead.
        "PSI" | "PSI_DRAIN" => {
            if def.has("EMPTY_MIND") {
                e.dam = 0;
            } else if def.has("STUPID")
                || def.has("WEIRD_MIND")
                || def.has("ANIMAL")
                || (e.dam > 0 && level > rng.gen_range(1..=(3 * e.dam)))
            {
                e.dam /= 3;
                if (def.has("UNDEAD") || def.has("DEMON"))
                    && level > player_level / 2
                    && rng.gen_range(1..=2) == 1
                {
                    e.psi_backlash = true;
                    e.dam = 0;
                }
            }
            if e.dam > 0 && rng.gen_range(1..=4) == 1 {
                match rng.gen_range(1..=4) {
                    1 => e.conf = 3 + rng.gen_range(1..=e.dam.max(1)),
                    2 => e.stun = 3 + rng.gen_range(1..=e.dam.max(1)),
                    3 => e.fear = 3 + rng.gen_range(1..=e.dam.max(1)),
                    _ => e.slow = true,
                }
            }
        }
        // GF_RAISE (spells1.cc:6338): wake and heal, no damage.
        "RAISE" => {
            e.heal = e.dam.max(0);
            e.dam = 0;
        }
        // GF_ATTACK (spells1.cc:4322): a real weapon blow, not damage.
        "ATTACK" => {
            e.attack = true;
            e.dam = 0;
        }
        _ => {}
    }
    // get_angry (spells1.cc:4201): a player projection that a friend
    // shrugs off still turns it hostile.  Only the GFs in the original's
    // explicit list anger (plain damage does not).
    if from_player {
        e.angry = match gf {
            "AWAY_UNDEAD" | "AWAY_EVIL" | "AWAY_ALL" | "CHARM" | "CHARM_UNMOVING"
            | "STAR_CHARM" | "CONTROL_UNDEAD" | "CONTROL_ANIMAL" | "CONTROL_DEMON"
            | "OLD_HEAL" | "OLD_SPEED" | "DARK_WEAK" | "JAM_DOOR" | "RAISE"
            | "RAISE_DEMON" | "ELEMENTAL_GROWTH" | "ELEMENTAL_WALL" => false,
            "TRAP_DEMONSOUL" => def.has("DEMON"),
            "KILL_WALL" => def.has("HURT_ROCK"),
            "HOLY_FIRE" => !def.has("GOOD"),
            "TURN_UNDEAD" | "DISP_UNDEAD" => def.has("UNDEAD"),
            "TURN_EVIL" | "DISP_EVIL" => def.has("EVIL"),
            "DISP_GOOD" => def.has("GOOD"),
            "DISP_DEMON" => def.has("DEMON"),
            "DISP_LIVING" | "UNBREATH" => !def.has("UNDEAD") && !def.has("NONLIVING"),
            "PSI" | "PSI_DRAIN" => !def.has("EMPTY_MIND"),
            "DOMINATION" => !def.has("NO_CONF"),
            "OLD_POLY" | "OLD_CLONE" => rng.gen_range(1..=8) == 1,
            "LITE" | "LITE_WEAK" => def.has("HURT_LITE"),
            "INSTA_DEATH" => true,
            _ => false,
        };
    }
    e
}

/// generate_spell (spells1.cc): roll one random thaumaturgy spell.
pub fn generate_thaum_spell(plev: i32, rng: &mut impl Rng) -> RandomSpell {
    let power = rng.gen_range(0..5);
    let dice = (plev / 2 + power).max(1);
    let sides = (plev + power).max(5);
    let mana = (plev + plev * power / 15).max(1);
    let mut sp = RandomSpell {
        level: plev,
        mana,
        shape: 0,
        gf: String::new(),
        radius: 0,
        dam_dice: dice,
        dam_sides: sides,
        untried: true,
    };
    let chance = rng.gen_range(1..=100);
    let mut destruc_gen = false;
    let mut simple_gen = true;
    if plev == 1 || chance < 25 {
        sp.shape = 0;
        sp.dam_dice = sides;
        sp.dam_sides = dice;
        sp.radius = 0;
    } else if chance < 50 {
        sp.shape = 1;
    } else if chance < 76 {
        sp.shape = 2;
        sp.radius = dice / 3;
    } else if chance < 83 {
        sp.shape = 3;
        sp.radius = sides / 3;
        destruc_gen = true;
        simple_gen = false;
    } else if chance < 90 {
        sp.shape = 4;
        sp.dam_dice = dice / 5;
        sp.dam_sides = sides / 5;
        sp.radius = 4.max(sides / 3);
        destruc_gen = true;
    } else {
        sp.shape = 5;
        sp.dam_sides = sides / 2;
    }
    if destruc_gen && simple_gen {
        if rng.gen_bool(0.25) {
            simple_gen = false;
        } else {
            destruc_gen = false;
        }
    }
    sp.gf = if simple_gen {
        THAUM_ATTACK_TYPES[rng.gen_range(0..25)].to_string()
    } else {
        THAUM_DESTRUCTIVE_TYPES[rng.gen_range(0..10)].to_string()
    };
    sp
}

/// Maximum number of random spells a Power Mage can know (MAX_SPELLS).
pub const MAX_THAUM_SPELLS: usize = 100;

/// Gain new thaumaturgy spells as the skill grows (skills.cc
/// recalc_skills); called once per world turn so every way the skill can
/// change (birth, points, Lost Sword, Thaumaturgist) is covered.
pub fn gain_thaum_spells(ps: &mut PlayerState, log: &mut MessageLog, rng: &mut impl Rng) {
    let target = ps.skill_scale(crate::skill::SK_THAUMATURGY, 100);
    let mut gained = 0;
    while ps.thaum_level < target && ps.random_spells.len() < MAX_THAUM_SPELLS {
        ps.thaum_level += 1;
        let sp = generate_thaum_spell((ps.thaum_level + 1) / 2, rng);
        ps.random_spells.push(sp);
        gained += 1;
    }
    if gained == 1 {
        log.add("You have gained one new thaumaturgy spell.");
    } else if gained > 1 {
        log.add(format!(
            "You have gained {} new thaumaturgy spells.",
            gained
        ));
    }
}

/// Failure chance of a random spell (cmd7.cc spell_chance_random).
pub fn thaum_fail_chance(ps: &PlayerState, sp: &RandomSpell) -> i32 {
    let thaum = ps.skill(crate::skill::SK_THAUMATURGY);
    let mut chance = sp.level + 10
        - 3 * (thaum - sp.level)
        - 3 * (crate::mimic::adj_mag_stat(ps.stats[INT]) - 1);
    if sp.mana > ps.mana {
        chance += 5 * (sp.mana - ps.mana);
    }
    let minfail = crate::mimic::adj_mag_fail(ps.stats[INT]).max(0);
    if chance < minfail {
        chance = minfail;
    }
    if ps.stun > 50 {
        chance += 25;
    } else if ps.stun > 0 {
        chance += 15;
    }
    chance.min(95)
}

