impl PlayerState {
    /// The p_info C: base class title (falls back to the spec title for
    /// pre-spec saves, where the two were the same for the six classes).
    pub fn base_class_name(&self) -> &str {
        if self.base_class.is_empty() {
            &self.class_name
        } else {
            &self.base_class
        }
    }

    /// The chosen specialisation record, if the data has it.
    pub fn spec<'a>(&self, gd: &'a GameData) -> Option<&'a crate::data::SpecDef> {
        gd.classes
            .iter()
            .find(|c| c.name == self.base_class_name())
            .and_then(|c| c.specs.iter().find(|s| s.name == self.class_name))
    }

    /// The base class record (stats, blow params, level flags).
    pub fn class<'a>(&self, gd: &'a GameData) -> Option<&'a crate::data::ClassDef> {
        gd.classes.iter().find(|c| c.name == self.base_class_name())
    }

    pub fn stat_bonus(&self, i: usize) -> i32 {
        (self.stats[i] - 10) / 2
    }

    pub fn melee_bonus(&self) -> i32 {
        self.stat_bonus(STR)
    }

    pub fn spell_bonus(&self) -> i32 {
        self.stat_bonus(INT).max(self.stat_bonus(WIS)).max(0)
    }

    /// Raw skill value (1000ths).
    pub fn skill_value(&self, id: u32) -> i32 {
        self.skills.get(&id).copied().unwrap_or(0)
    }

    /// Skill level (0..50).
    pub fn skill(&self, id: u32) -> i32 {
        self.skill_value(id) / crate::skill::SKILL_STEP
    }

    /// scale * value / SKILL_MAX (skill levels 0..50).
    pub fn skill_scale(&self, id: u32, scale: i32) -> i32 {
        scale * self.skill_value(id) / crate::skill::SKILL_MAX
    }

    pub fn has_ability(&self, ab: u32) -> bool {
        self.abilities.contains(&ab)
    }

    /// `player_type::gain_ability` (player_type.cc:13): append without a
    /// duplicate check (the original accepts duplicates).
    #[allow(dead_code)]
    pub fn gain_ability(&mut self, ab: u32) {
        self.abilities.push(ab);
    }

    /// `player_type::lose_ability` (player_type.cc:21): remove every
    /// occurrence of the ability (`erase(remove(...))`).
    #[allow(dead_code)]
    pub fn lose_ability(&mut self, ab: u32) {
        self.abilities.retain(|&a| a != ab);
    }

    pub fn exp_needed(&self) -> u64 {
        exp_needed_at(self.level, self.exp_factor)
    }
}

/// set_fast (xtra2.cc:723): haste for `v` turns at `p` speed per point.
/// The speed factor is zeroed when the haste ends.
pub fn set_fast(ps: &mut PlayerState, v: i32, p: i32, log: &mut MessageLog) -> bool {
    let v = v.clamp(0, 10000);
    let mut p = p;
    let notice = if v != 0 && ps.fast == 0 {
        log.add("You feel yourself moving faster!");
        true
    } else if v == 0 && ps.fast != 0 {
        log.add("You feel yourself slow down.");
        p = 0;
        true
    } else {
        false
    };
    ps.fast = v;
    ps.speed_factor = p;
    notice
}

