/// `message::text_with_count` (message.cc:5): append " <Nx>" when the
/// message repeated.
pub fn text_with_count(text: &str, count: u32) -> String {
    if count > 1 {
        format!("{} <{}x>", text, count)
    } else {
        text.to_string()
    }
}

#[derive(Resource, Default)]
pub struct MessageLog {
    pub lines: VecDeque<String>,
    /// Repetition count of each line (message.hpp `count`).  Kept
    /// parallel to `lines`; rendered by [`MessageLog::display_lines`].
    pub counts: VecDeque<u32>,
}

impl MessageLog {
    /// `Messages::add(const char*, byte)` (messages.cc:25): append a
    /// message; an identical consecutive text only increments its count.
    /// The colour byte is not modelled (documented in the save codec).
    pub fn add(&mut self, msg: impl Into<String>) {
        let msg = msg.into();
        if let (Some(last), Some(count)) = (self.lines.back(), self.counts.back_mut()) {
            if *last == msg {
                *count += 1;
                return;
            }
        }
        if self.lines.len() >= 100 {
            self.lines.pop_front();
            self.counts.pop_front();
        }
        self.lines.push_back(msg);
        self.counts.push_back(1);
    }

    /// `Messages::size` (messages.cc:8).
    #[allow(dead_code)]
    pub fn size(&self) -> usize {
        self.lines.len()
    }

    /// `Messages::at` (messages.cc:13): age 0 is the newest; the original
    /// asserts the age is inside the buffer.
    #[allow(dead_code)]
    pub fn at(&self, age: usize) -> &str {
        assert!(age < self.size(), "message age out of range");
        &self.lines[self.lines.len() - 1 - age]
    }

    /// The rendered history, one `text_with_count` string per entry.
    pub fn display_lines(&self) -> impl DoubleEndedIterator<Item = String> + '_ {
        self.lines
            .iter()
            .zip(self.counts.iter())
            .map(|(text, &count)| text_with_count(text, count))
    }
}

