/// Turns per game day (defines.hpp: DAY=11520 at 10 ticks per player
/// turn → 1152 turns/day).
pub const TURNS_PER_DAY: u64 = 1152;

/// The day count shown in the HUD (the game starts on day 1 at 06:00).
pub fn day_of(turn: u64) -> u64 {
    turn / TURNS_PER_DAY + 1
}

/// The wall clock shown in the HUD (sunrise is 06:00, sunset 18:00).
pub fn clock_of(turn: u64) -> (u32, u32) {
    let mins = 360 + (turn % TURNS_PER_DAY) * 1440 / TURNS_PER_DAY;
    ((mins / 60 % 24) as u32, (mins % 60) as u32)
}

/// Daytime runs from sunrise to sunset (src/wild.cc: turn % day < day/2).
pub fn is_daytime(turn: u64) -> bool {
    turn % TURNS_PER_DAY < TURNS_PER_DAY / 2
}
/// DUNGEON_DEATH (defines.hpp): the "Death fate" dungeon, 28.
pub const DEATH_DUNGEON: u32 = 28;

/// Strip every staircase from the Death fate dungeon (dungeon.cc:4358).
fn wipe_stairs(map: &mut Map) {
    for y in 0..map::MAP_H {
        for x in 0..map::MAP_W {
            if matches!(
                map.terrain_at(x, y),
                map::T_STAIRS_UP
                    | map::T_STAIRS_DOWN
                    | map::T_SHAFT_UP
                    | map::T_SHAFT_DOWN
                    | map::T_WAY_MORE
                    | map::T_WAY_LESS
            ) {
                map.set_terrain(x, y, map::T_FLOOR);
            }
        }
    }
}

