/// skills.cc forbid_gloves: arcane casters lose mana from normal gloves.
pub fn forbid_gloves(ps: &PlayerState) -> bool {
    [
        crate::skill::SK_SORCERY,
        crate::skill::SK_MANA,
        crate::skill::SK_FIRE,
        crate::skill::SK_AIR,
        crate::skill::SK_WATER,
        crate::skill::SK_EARTH,
        crate::skill::SK_THAUMATURGY,
    ]
    .iter()
    .any(|&s| ps.skill(s) > 0)
}

/// Whether the worn gloves encumber a mage-type caster (xtra1.cc:1579:
/// `cumber_glove`).  FREE_ACT, +DEX and SPELL_CONTAIN gloves are exempt.
pub fn cumber_glove(ps: &PlayerState, inv: &Inventory, gd: &GameData) -> bool {
    if !forbid_gloves(ps) {
        return false;
    }
    inv.equip[crate::data::SLOT_HANDS]
        .as_ref()
        .is_some_and(|g| {
            let flags = item::item_flags(gd, g);
            !flags.iter().any(|f| *f == "FREE_ACT")
                && !(flags.iter().any(|f| *f == "DEX") && g.pval > 0)
                && !flags.iter().any(|f| *f == "SPELL_CONTAIN")
        })
}

/// xtra1.cc calc_mana: the full maximum-mana formula in the original
/// order.  Unlike the earlier port split (base + school + tracked
/// god/equipment boons) every percentage is applied in the C++ sequence:
/// base -> possessor -> race/class -> Eru -> forbidden gloves -> TR_MANA
/// equipment -> armour encumbrance -> mana_school_calc_mana -> Inertia
/// Control, floored at zero.
pub fn calc_mana(ps: &PlayerState, gd: &GameData, inv: &Inventory) -> i32 {
    let levels = ps.level.max(0) as i32;
    // A Possessor's mana comes from the borrowed body
    // (xtra1.cc:1548: 21 - 100/spell frequency).
    let mut msp = if let Some((body, _, _)) = ps.possessed {
        let f = gd
            .monsters
            .get(body)
            .map(|m| m.spell_freq.max(1))
            .unwrap_or(1);
        (21 - 100 / f).max(1)
    } else {
        let mut m = ps.skill_scale(crate::skill::SK_MAGIC, 200)
            + adj_mag_mana(ps.stats[INT].max(ps.stats[WIS])) * levels / 4;
        if m != 0 {
            m += 1;
        }
        m
    };
    // Race/subrace mana multiplier, then class mana bonus.
    msp = msp * ps.mana_mult / 100;
    if let Some(class) = ps.class(gd) {
        msp += msp * class.mana / 100;
    }
    // Eru's blessing (xtra1.cc:1568): grace/100 percent per mille.
    if ps.god == 1 {
        let tmp = ps.grace.clamp(0, 35000) / 100;
        msp += msp * tmp / 1000;
    }
    // Normal gloves hinder mage-type casters (skills.cc forbid_gloves).
    if msp != 0 && cumber_glove(ps, inv, gd) {
        msp = 3 * msp / 4;
    }
    // TR_MANA equipment (+20% per pval).
    let mana_pct = inv.totals_for(gd, ps).mana_pct;
    if mana_pct != 0 {
        msp += msp * mana_pct / 5;
    }
    // Heavy armour encumbrance.
    msp -= cumber_armor_penalty(ps, inv, gd);
    // spells6.cc mana_school_calc_mana: Mana skill past 34 adds percent.
    let mana_skill = ps.skill(crate::skill::SK_MANA);
    if mana_skill >= 35 {
        msp += msp * (mana_skill - 34) / 100;
    }
    // spells3.cc meta_inertia_control_calc_mana reserves 4x the cost.
    if ps.inertia_spell.is_some() {
        msp -= ps.inertia_cost.max(0) * 4;
    }
    msp.max(0)
}

/// calc_schools (xtra1.cc): Air skill >= 50 grants magical breathing and
/// Water skill >= 30 water breathing.  Returns (magical, water); magical
/// breathing implies water breathing in the port's process_world checks.
pub fn school_breaths(ps: &PlayerState) -> (bool, bool) {
    let air = ps.skill(crate::skill::SK_AIR) >= 50;
    (air, air || ps.skill(crate::skill::SK_WATER) >= 30)
}

