/// Effective player speed: equipment + haste - slow (drives free
/// actions; negative values give the monsters bonus turns). Encumbrance
/// and a full belly slow the player down (xtra1.cc calc_bonuses).
pub fn player_speed(ps: &PlayerState, inv: &Inventory, gd: &GameData) -> i32 {
    let totals = inv.totals_for(gd, ps);
    let mut s = totals.speed;
    if ps.fast > 0 {
        s += ps.speed_factor;
    }
    if ps.lightspeed > 0 {
        s += 50;
    }
    if ps.slow > 0 {
        s -= 10;
    }
    s += god_speed(ps);
    // Unencumbered barehand fighters move faster (xtra1.cc:2883).
    if ps.melee_style == crate::skill::SK_HAND && !monk_heavy_armor(ps, inv, gd) {
        s += ps.skill_scale(crate::skill::SK_HAND, 5);
    }
    // Movement mode (tables.cc move_info).
    s += move_info(ps.movement).0;
    // Encumbrance (xtra1.cc:3380): past half capacity the player slows.
    let j = calc_total_weight(gd, inv);
    let i = weight_limit(ps);
    if j > i / 2 {
        s -= (j - i / 2) / (i / 10).max(1);
    }
    // Being bloated slows you down (xtra1.cc:3389).
    if ps.food >= FOOD_MAX {
        s -= 10;
    }
    s
}

/// calc_torch (xtra1.cc:1833): the effective light radius used for FOV.
/// Burned-out FUEL_LITE items stop glowing; a worn LITE flag on a
/// non-lite item (or the SH_FIRE aura) is an intrinsic glow worth 1.
/// Temporary light adds 2, a holy aura 1, and the original hard-caps the
/// radius at 5 (LITE_MAX).
pub fn player_lite(ps: &PlayerState, inv: &Inventory, gd: &GameData) -> i32 {
    player_lite_ex(ps, inv, gd, false, false)
}

/// `player_lite` with the running/wilderness reductions (xtra1.cc:1833):
/// the original is called from the player update with `running` and
/// `options->view_reduce_lite` in scope.
pub fn player_lite_ex(
    ps: &PlayerState,
    inv: &Inventory,
    gd: &GameData,
    running: bool,
    reduce_running: bool,
) -> i32 {
    let totals = inv.totals_for(gd, ps);
    let mut lite = 0;
    // LITE flags present on worn gear, glowing or not: used to tell the
    // equipment contribution apart from race/corruption/mimic sources in
    // the EquipTotals.
    let mut equip_lit = 0;
    let mut intrinsic = false;
    for it in inv.equip.iter().flatten() {
        let def = &gd.objects[it.def];
        let flags = item::item_flags(gd, it);
        let has = |f: &str| flags.iter().any(|x| *x == f);
        let lit = has("LITE1") || has("LITE2") || has("LITE3");
        if !lit {
            continue;
        }
        let n = if has("LITE1") { 1 } else { 0 }
            + if has("LITE2") { 2 } else { 0 }
            + if has("LITE3") { 3 } else { 0 };
        equip_lit += n;
        // A FUEL_LITE light only glows while it still has fuel
        // (xtra1.cc:1856).
        if !has("FUEL_LITE") || it.fuel > 0 {
            lite += n;
        }
        if def.tval != crate::data::TV_LITE {
            intrinsic = true;
        }
    }
    // Non-equipment LITE flags (corruptions, mimic shapes, race/class
    // powers) and the fiery aura make the player glow intrinsically:
    // `apply_flags(xtra_flags, tval 0)` sets p_ptr->lite (xtra1.cc:2529,
    // 2931/3044), which raises an otherwise dark player to radius 1.
    if totals.sh_fire || totals.lite > equip_lit {
        intrinsic = true;
    }
    if ps.tim_lite > 0 {
        lite += 2;
    }
    if ps.holy > 0 {
        lite += 1;
    }
    let mut lite = lite.min(5);
    // No source, but the player glows intrinsically (xtra1.cc:1875).
    if lite == 0 && intrinsic {
        lite = 1;
    }
    // calc_torch_gods (xtra1.cc:1817, applied after the cap).
    if ps.god == 7 {
        lite += 1;
    }
    // The small-scale wilderness map caps the radius (xtra1.cc:1879).
    if ps.wild_mode && lite > 3 {
        lite = 3;
    }
    // Running with view_reduce_lite (xtra1.cc:1895).
    if running && reduce_running && lite > 1 {
        lite = 1;
    }
    lite
}

/// Player-side element resolution (src/spells1.cc project_p): applies
/// resistances/immunities to the raw damage, then the element's side
/// effects (statuses, drains, item destruction). Returns final damage.
#[allow(clippy::too_many_arguments)]
pub fn apply_gf(
    gd: &GameData,
    ps: &mut PlayerState,
    inv: &mut Inventory,
    totals: &crate::item::EquipTotals,
    gf: &str,
    dam: i32,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) -> i32 {
    let mut smashed = Vec::new();
    apply_gf_ex(gd, ps, inv, totals, gf, dam, log, rng, &mut smashed)
}

/// apply_gf with the shattered-potion svals of `inven_damage_ex` (the
/// original calls `potion_smash_effect` inline; the caller here owns the
/// map and projects them at the player's grid).
#[allow(clippy::too_many_arguments)]
pub fn apply_gf_ex(
    gd: &GameData,
    ps: &mut PlayerState,
    inv: &mut Inventory,
    totals: &crate::item::EquipTotals,
    gf: &str,
    dam: i32,
    log: &mut MessageLog,
    rng: &mut impl Rng,
    smashed: &mut Vec<i32>,
) -> i32 {
    // Melkor's faithful always resist fire and, while praying at high
    // grace, are immune to it (xtra1.cc:2275-2280).
    let melkor_fire = ps.god == 4;
    let melkor_immune_fire = ps.god == 4 && ps.praying && ps.grace > 15000;
    let immune = |e: &str| totals.immunities.contains(e) || (melkor_immune_fire && e == "FIRE");
    let resist_timer = ps.resist_timer;
    let (of, oc, oe, oa, op, occ) = (
        ps.oppose_fire,
        ps.oppose_cold,
        ps.oppose_elec,
        ps.oppose_acid,
        ps.oppose_pois,
        ps.oppose_cc,
    );
    let res = |e: &str| {
        totals.resists.contains(e)
            || (melkor_fire && e == "FIRE")
            || (resist_timer > 0 && matches!(e, "ACID" | "ELEC" | "FIRE" | "COLD" | "POIS"))
            || (of > 0 && e == "FIRE")
            || (oc > 0 && e == "COLD")
            || (oe > 0 && e == "ELEC")
            || (oa > 0 && e == "ACID")
            || (op > 0 && e == "POIS")
            // Oppose raw chaos protects against both chaos and confusion.
            || (occ > 0 && matches!(e, "CONF" | "CHAOS"))
    };
    let mut d = dam.max(1);
    match gf {
        "ACID" | "ELEC" | "FIRE" | "COLD" => {
            if gf == "FIRE" && totals.sens_fire {
                d = (d + 2) * 2;
            }
            if immune(gf) {
                log.add(format!("You are immune to {}!", gf.to_lowercase()));
                return 0;
            }
            if res(gf) {
                d = (d + 2) / 3;
                log.add("You resist!");
            }
            // Equipment/inventory damage (original inven_damage): the
            // percentage comes from the *raw* projection damage, and both
            // an oppose spell and a worn resistance suppress it entirely.
            let (oppose, gear_resist) = match gf {
                "ACID" => (oa > 0 || resist_timer > 0, totals.resists.contains("ACID")),
                "ELEC" => (oe > 0 || resist_timer > 0, totals.resists.contains("ELEC")),
                "FIRE" => (
                    of > 0 || resist_timer > 0,
                    totals.resists.contains("FIRE") || melkor_fire,
                ),
                _ => (oc > 0 || resist_timer > 0, totals.resists.contains("COLD")),
            };
            if !(oppose && gear_resist) {
                let perc = if dam < 30 {
                    1
                } else if dam < 60 {
                    2
                } else {
                    3
                };
                smashed.extend(item::inven_damage_ex(gd, inv, gf, perc, log, rng));
            }
            // Unresisted hits can wither a stat (1/32).
            let stat = match gf {
                "ACID" => Some(CHA),
                "ELEC" => Some(DEX),
                _ => Some(STR),
            };
            if !res(gf) && !immune(gf) && rng.gen_bool(1.0 / 32.0) {
                item::drain_stat(ps, stat.unwrap(), totals, log);
            }
        }
        "POIS" => {
            if res("POIS") {
                d = (d + 2) / 3;
                log.add("You resist!");
            } else {
                ps.poison += rng.gen_range(1..=d.max(1)) + 10;
                log.add("You are poisoned!");
                if rng.gen_bool(1.0 / 32.0) {
                    item::drain_stat(ps, CON, totals, log);
                }
            }
        }
        "NUKE" => {
            // GF_NUKE (spells1.cc:6947): a harsher poison resistance and
            // the infamous freakish metamorphosis.
            let resisted = res("POIS") || ps.oppose_pois > 0;
            if resisted {
                d = (2 * d + 2) / 5;
                log.add("You resist!");
            } else {
                ps.poison += rng.gen_range(0..d.max(1)) + 10;
                log.add("You are poisoned!");
                if rng.gen_range(1..=5) == 1 {
                    log.add("You undergo a freakish metamorphosis!");
                    if rng.gen_range(1..=4) == 1 {
                        // do_poly_self (cmd5.cc): the full racial
                        // polymorph (race change, stat decay, corruption
                        // swings, rerolled HP).
                        do_poly_self(gd, ps, inv, log, rng);
                    } else {
                        // corrupt_player (spells1.cc): swap two stats.
                        corrupt_player(ps, rng);
                    }
                }
                if rng.gen_bool(1.0 / 6.0) {
                    smashed.extend(item::inven_damage_ex(gd, inv, "ACID", 2, log, rng));
                }
            }
        }
        "NETHER" => {
            if immune("NETHER") {
                return 0;
            }
            if res("NETHER") {
                d = d * 6 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else {
                let amount = 200 + (ps.exp / 100) * 2;
                item::lose_exp(ps, amount, 75, totals, rng, log);
            }
        }
        "LITE" | "DARK" => {
            if res(gf) {
                d = d * 4 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else if ps.blind <= 0 && !totals.resists.contains("BLIND") {
                ps.blind += rng.gen_range(1..=5) + 2;
                log.add("You are blinded by the flash!");
            }
            // Wraithform is shattered by light and mended by darkness
            // (spells1.cc GF_LITE/GF_DARK).
            if ps.tim_wraith > 0 {
                if gf == "LITE" {
                    ps.tim_wraith = 0;
                    log.add("The light forces you out of your incorporeal shadow form.");
                } else {
                    ps.hp = (ps.hp + d).min(ps.max_hp);
                    log.add("The darkness mends your shadow form.");
                    d = 0;
                }
            }
        }
        "CONF" => {
            if res("CONF") {
                d = d * 5 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else {
                ps.confuse += 10 + rng.gen_range(0..20);
                log.add("You are confused!");
            }
        }
        "SOUND" => {
            if res("SOUND") {
                d = d * 5 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else {
                let k = rng.gen_range(1..=if d > 90 { 35 } else { d / 3 + 5 });
                let v = ps.stun + k;
                set_stun_full(gd, ps, v, Some(totals), log, rng);
                log.add("You are deafened and stunned!");
            }
        }
        "CHAO" => {
            if res("CHAOS") {
                d = d * 6 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else {
                if !totals.resists.contains("CONF") {
                    ps.confuse += 10 + rng.gen_range(0..20);
                }
                // Chaos warps the mind (spells1.cc: hallucination).
                ps.image += rng.gen_range(0..10);
                if !totals.resists.contains("NETHER") {
                    let amount = 5000 + (ps.exp / 100) * 2;
                    item::lose_exp(ps, amount, 75, totals, rng, log);
                }
                log.add("You are engulfed in chaos!");
            }
            if !totals.resists.contains("CHAOS") || rng.gen_bool(1.0 / 9.0) {
                smashed.extend(item::inven_damage_ex(gd, inv, "ELEC", 2, log, rng));
                smashed.extend(item::inven_damage_ex(gd, inv, "FIRE", 2, log, rng));
            }
        }
        "SHAR" => {
            if res("SHARDS") {
                d = d * 6 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else {
                let v = ps.cut + d;
                set_cut_full(gd, ps, v, Some(totals), log, rng);
                log.add("You are cut by shards!");
            }
            if !totals.resists.contains("SHARDS") || rng.gen_bool(1.0 / 13.0) {
                smashed.extend(item::inven_damage_ex(gd, inv, "COLD", 2, log, rng));
            }
        }
        "DISEN" => {
            if res("DISEN") {
                d = d * 6 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else {
                item::disenchant_item(gd, inv, totals, log, rng);
            }
        }
        "NEXU" => {
            if res("NEXUS") {
                d = d * 6 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else if !totals.no_tele {
                log.add("Space warps around you!");
                // Teleportation side effects are handled by the caller
                // (it owns the map/positions); here a small shuffle.
                ps.confuse += rng.gen_range(2..=6);
            }
        }
        "TIME" => {
            // Only mastery of the space/time continuum resists time
            // (spells1.cc:7417).
            if crate::corrupt::resist_continuum(ps) {
                d = d * 4 / (rng.gen_range(1..=6) + 6);
                log.add("You resist!");
            } else {
                match rng.gen_range(1..=10) {
                    1..=5 => {
                        let amount = 100 + (ps.exp / 100) * 2;
                        item::lose_exp(ps, amount, 0, totals, rng, log);
                    }
                    6..=9 => {
                        // One stat withered to 3/4 (spells1.cc).
                        let i = rng.gen_range(0..6);
                        ps.stats[i] = (ps.stats[i] * 3 / 4).max(3);
                        log.add("You feel your body wither!");
                    }
                    _ => {
                        for i in 0..6 {
                            ps.stats[i] = (ps.stats[i] * 3 / 4).max(3);
                        }
                        log.add("You feel your body wither!");
                    }
                }
            }
        }
        "INER" => {
            // Inertia ignores free action (original).
            ps.slow += 4 + rng.gen_range(0..4);
            log.add("You feel slow!");
        }
        "GRAV" => {
            if totals.feather || totals.fly || ps.tim_fly > 0 || ps.tim_ffall > 0 {
                d = d * 2 / 3;
            } else {
                ps.slow += 4 + rng.gen_range(0..4);
                if !totals.resists.contains("SOUND") {
                    let k = rng.gen_range(1..=if d > 90 { 35 } else { d / 3 + 5 });
                    let v = ps.stun + k;
                    set_stun_full(gd, ps, v, Some(totals), log, rng);
                }
            }
            log.add("Gravity crushes you!");
        }
        "PLAS" => {
            // Plasma has no resistance (original).
            if !totals.resists.contains("SOUND") {
                let k = rng.gen_range(1..=if d > 40 { 35 } else { d * 3 / 4 + 5 });
                let v = ps.stun + k;
                set_stun_full(gd, ps, v, Some(totals), log, rng);
            }
            if !res("FIRE") && !immune("FIRE") {
                smashed.extend(item::inven_damage_ex(gd, inv, "ACID", 3, log, rng));
            }
        }
        "WATE" => {
            if !totals.resists.contains("SOUND") {
                let k = rng.gen_range(1..=40);
                let v = ps.stun + k;
                set_stun_full(gd, ps, v, Some(totals), log, rng);
            }
            if !totals.resists.contains("CONF") {
                ps.confuse += rng.gen_range(1..=5) + 5;
            }
            if rng.gen_bool(0.2) {
                smashed.extend(item::inven_damage_ex(gd, inv, "COLD", 3, log, rng));
            }
        }
        "ICE" => {
            if immune("COLD") {
                return 0;
            }
            if res("COLD") {
                d = (d + 2) / 3;
            }
            if !totals.resists.contains("SHARDS") {
                let k = Dice {
                    count: 5,
                    sides: 8,
                    bonus: 0,
                }
                .roll(rng);
                let v = ps.cut + k;
                set_cut_full(gd, ps, v, Some(totals), log, rng);
            }
            if !totals.resists.contains("SOUND") {
                let k = rng.gen_range(1..=15);
                let v = ps.stun + k;
                set_stun_full(gd, ps, v, Some(totals), log, rng);
            }
            // cold_dam's destruction pass (perc from the raw damage,
            // suppressed only when both oppose and worn resistance are
            // up) plus the extra shard-cold roll (spells1.cc GF_ICE).
            let oppose_cold = oc > 0 || resist_timer > 0;
            let gear_cold = totals.resists.contains("COLD");
            if !(oppose_cold && gear_cold) {
                let perc = if dam < 30 {
                    1
                } else if dam < 60 {
                    2
                } else {
                    3
                };
                smashed.extend(item::inven_damage_ex(gd, inv, "COLD", perc, log, rng));
            }
            if !(gear_cold || oppose_cold) || rng.gen_bool(1.0 / 12.0) {
                smashed.extend(item::inven_damage_ex(gd, inv, "COLD", 3, log, rng));
            }
        }
        "FORCE" => {
            // GF_FORCE (spells1.cc:7237): the impact stuns unless the
            // player resists sound; the shove itself is applied by the
            // caller, which owns the map.
            if !totals.resists.contains("SOUND") {
                let v = ps.stun + rng.gen_range(0..20);
                set_stun_full(gd, ps, v, Some(totals), log, rng);
                log.add("You are stunned by the impact!");
            }
        }
        _ => {} // MANA / MISSILE / ARROW / DISI: pure damage
    }
    d
}

/// Whether a monster fails to see an invisible player (melee2.cc
/// player_invis): the player's invisibility power against the monster's
/// adjusted level (race bonuses/penalties).
pub fn player_invisible(
    ps: &PlayerState,
    totals: &crate::item::EquipTotals,
    def: &crate::data::MonsterDef,
    mon_level: i32,
    forced_visible: bool,
    rng: &mut impl Rng,
) -> bool {
    let mut inv = if totals.invis {
        ps.invis_power.max(50)
    } else if ps.invis_turns > 0 {
        // Potion/lasting sources that do not set a power use a default.
        ps.invis_power.max(20)
    } else {
        0
    };
    // Melkor grants invisibility power while praying at grace > 5000
    // (xtra1.cc:2275).
    if ps.god == 4 && ps.praying && ps.grace > 5000 {
        inv += 30;
    }
    if inv <= 0 {
        return false;
    }
    if def.has("INVISIBLE") {
        inv = 0;
    }
    // Quest and player-controlled monsters always see through invisibility
    // (melee2.cc player_invis: MFLAG_QUEST / MFLAG_CONTROL).
    if forced_visible {
        inv = 0;
    }
    let mut mlv = mon_level.max(1);
    if def.has("NO_SLEEP") {
        mlv += 10;
    }
    if def.has("DRAGON") {
        mlv += 20;
    }
    if def.has("UNDEAD") {
        mlv += 15;
    }
    if def.has("DEMON") {
        mlv += 15;
    }
    if def.has("ANIMAL") {
        mlv += 15;
    }
    if def.has("ORC") {
        mlv -= 15;
    }
    if def.has("TROLL") {
        mlv -= 10;
    }
    if def.has("STUPID") {
        mlv /= 2;
    }
    if def.has("SMART") {
        mlv = mlv * 5 / 4;
    }
    mlv = mlv.max(1);
    inv >= rng.gen_range(1..=mlv * 2)
}

/// A skill saving throw against monster tricks (fear, paralysis, ...).
/// xtra1.cc calc_bonuses: adj_wis_sav + Spirituality + tactic, with the
/// minimum/maximum handling and the antimagic field floor of 95.
pub fn player_sav(ps: &PlayerState) -> i32 {
    let mut sav = adj_wis_sav(ps.stats[WIS]);
    sav += ps.skill_scale(crate::skill::SK_SPIRITUALITY, 75);
    // Combat tactic shifts saving throws (tables.cc tactic_info).
    sav += tactic_info(ps.tactic).4;
    if ps.antimagic_field && sav < 95 {
        sav = 95;
    }
    if sav <= 10 {
        sav = 10;
    } else {
        sav += 10;
    }
    sav
}

pub fn skill_save(ps: &PlayerState, rng: &mut impl Rng) -> bool {
    rng.gen_range(0..100) < player_sav(ps)
}

/// The sanity blast of an eldritch horror (monster2.cc sanity_blast):
/// triggered when such a monster becomes visible.  It does not drain the
/// sanity meter, but blasts the mind in five escalating tiers.
pub fn sanity_blast(
    gd: &GameData,
    ps: &mut PlayerState,
    inv: &Inventory,
    totals: &item::EquipTotals,
    def_idx: usize,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    let def = &gd.monsters[def_idx];
    let mut power = def.depth.max(1) as i32 + 10;
    if def.unique {
        power *= 2;
    } else if def.has("FRIENDS") {
        power /= 2;
    }
    let name = hallucinated_name(gd, ps, def_idx, rng);
    // Pets are safe most of the time.
    if def.has("PET") && rng.gen_range(1..=8) != 1 {
        return;
    }
    if rng.gen_range(1..=power) < player_sav(ps) {
        return;
    }
    if ps.image > 0 {
        // Everything is already too strange to matter.
        log.add(format!(
            "You behold the {} visage of {}!",
            funny_desc(rng),
            name
        ));
        if rng.gen_range(1..=3) == 1 {
            log.add(funny_comment(rng));
            ps.image += rng.gen_range(1..=def.depth.max(1) as i32);
        }
        return;
    }
    log.add(format!(
        "You behold the {} visage of {}!",
        horror_desc(rng),
        name
    ));
    // Undead and vampires are inured to such sights.
    let undead = player_has_flag(gd, ps, "UNDEAD");
    if undead && rng.gen_range(1..=100) < 25 + ps.level as i32 {
        return;
    }
    if rng.gen_range(1..=power) < player_sav(ps) {
        // Mind blast.
        if !totals.resists.contains("CONF") {
            ps.confuse += rng.gen_range(0..4) + 4;
        }
        if !totals.resists.contains("CHAOS") && rng.gen_range(1..=3) == 1 {
            ps.image += rng.gen_range(0..250) + 150;
        }
        return;
    }
    if rng.gen_range(1..=power) < player_sav(ps) {
        item::drain_stat(ps, INT, totals, log);
        item::drain_stat(ps, WIS, totals, log);
        log.add("Your mind feels drained!");
        return;
    }
    if rng.gen_range(1..=power) < player_sav(ps) {
        // Brain smash.
        if !totals.resists.contains("CONF") {
            ps.confuse += rng.gen_range(0..4) + 4;
        }
        // C++ checks p_ptr->free_act, which includes the SK_HAND >= 25
        // monk free action and the gods' blessing (item::has_free_act).
        if !item::has_free_act(ps, inv, gd, totals) {
            ps.paralyze = ps.paralyze.max(rng.gen_range(0..4) + 4);
        }
        while rng.gen_range(0..100) >= player_sav(ps) {
            item::drain_stat(ps, INT, totals, log);
        }
        while rng.gen_range(0..100) >= player_sav(ps) {
            item::drain_stat(ps, WIS, totals, log);
        }
        if !totals.resists.contains("CHAOS") {
            ps.image += rng.gen_range(0..250) + 150;
        }
        return;
    }
    if rng.gen_range(1..=power) < player_sav(ps) {
        // Permanent loss of insight.
        let mut happened = false;
        for stat in [INT, WIS] {
            if ps.stat_base[stat] > 3 {
                ps.stat_base[stat] = (ps.stat_base[stat] - 10).max(3);
                ps.stats[stat] = (ps.stats[stat] - 10).max(3);
                happened = true;
            }
        }
        if happened {
            log.add("You feel much less sane than before.");
        }
        return;
    }
    if rng.gen_range(1..=power) < player_sav(ps) {
        // Amnesia: the map is forgotten.
        log.add("You forget everything in your utmost terror!");
    }
}

fn horror_desc(rng: &mut impl Rng) -> &'static str {
    const HORROR: [&str; 20] = [
        "abominable",
        "abysmal",
        "appalling",
        "baleful",
        "blasphemous",
        "disgusting",
        "dreadful",
        "filthy",
        "grisly",
        "hideous",
        "hellish",
        "horrible",
        "infernal",
        "loathsome",
        "nightmarish",
        "repulsive",
        "sacrilegious",
        "terrible",
        "unclean",
        "unspeakable",
    ];
    HORROR[rng.gen_range(0..HORROR.len())]
}

fn funny_desc(rng: &mut impl Rng) -> &'static str {
    const FUNNY: [&str; 22] = [
        "silly",
        "hilarious",
        "absurd",
        "insipid",
        "ridiculous",
        "laughable",
        "ludicrous",
        "far-out",
        "groovy",
        "postmodern",
        "fantastic",
        "dadaistic",
        "cubistic",
        "cosmic",
        "awesome",
        "incomprehensible",
        "fabulous",
        "amazing",
        "incredible",
        "chaotic",
        "wild",
        "preposterous",
    ];
    FUNNY[rng.gen_range(0..FUNNY.len())]
}

fn funny_comment(rng: &mut impl Rng) -> &'static str {
    const COMMENTS: [&str; 5] = ["Wow, cosmic, man!", "Rad!", "Groovy!", "Cool!", "Far out!"];
    COMMENTS[rng.gen_range(0..COMMENTS.len())]
}

