/// The power id of a game.cc power name (Z: lines refer to names).
/// init1.cc find_power_idx compares with iequals, so data names are
/// matched case-insensitively.
pub fn power_id_by_name(name: &str) -> Option<i32> {
    POWERS
        .iter()
        .find(|p| p.1.eq_ignore_ascii_case(name))
        .map(|p| p.0)
}

/// Power ids the player currently has (xtra1.cc calc_powers):
/// corruption grants, the active mimicry shape and grow-mold, plus the
/// Z: powers of the race/subrace/class/spec and of worn egos/artifacts.
pub fn available_powers(gd: &GameData, inv: &Inventory, ps: &PlayerState) -> Vec<i32> {
    let mut out = crate::corrupt::powers(ps);
    out.extend(ps.extra_powers.iter().copied());
    if ps.power_grow_mold {
        out.push(19);
    }
    if let Some(form) = ps.mimic_form {
        if form == crate::mimic::MIMIC_MOUSE && ps.mimic_level >= 30 {
            out.push(62);
        }
        if form == crate::mimic::MIMIC_SPIDER && ps.mimic_level >= 25 {
            out.push(63);
        }
        if form == crate::mimic::MIMIC_ENT {
            out.push(40);
        }
    }
    let mut names: Vec<&str> = Vec::new();
    if let Some(r) = gd.races.iter().find(|r| r.name == ps.race_name) {
        names.extend(r.powers.iter().map(String::as_str));
    }
    if let Some(m) = gd.racemods.get(ps.subrace as usize) {
        names.extend(m.powers.iter().map(String::as_str));
    }
    if let Some(c) = ps.class(gd) {
        names.extend(c.powers.iter().map(String::as_str));
    }
    // object_power (object1.cc): worn egos and artifacts grant powers.
    for it in inv.equip.iter().flatten() {
        if it.artifact != 0 {
            if let Some(a) = gd.artifacts.iter().find(|a| a.id == it.artifact) {
                names.extend(a.powers.iter().map(String::as_str));
            }
        }
        if it.ego != 0 {
            if let Some(e) = gd.egos.iter().find(|e| e.id == it.ego) {
                names.extend(e.powers.iter().map(String::as_str));
            }
        }
    }
    for name in names {
        if let Some(id) = power_id_by_name(name) {
            out.push(id);
        }
    }
    out.sort();
    out.dedup();
    out
}

