/// calc_powers notifications (xtra1.cc:1442-1483): the original keeps a
/// persistent sorted power set and prints `gain_text`/`lose_text` for the
/// set difference on every recompute.  The port recomputes the set on
/// demand, so this runs once per player turn and reports the diff.
pub fn sync_powers(
    gd: &GameData,
    inv: &Inventory,
    ps: &mut PlayerState,
    log: &mut MessageLog,
) {
    let mut new = available_powers(gd, inv, ps);
    new.sort();
    new.dedup();
    if ps.known_powers.is_empty() && ps.turn == 0 {
        ps.known_powers = new;
        return;
    }
    for p in ps.known_powers.iter().filter(|p| !new.contains(p)) {
        if let Some(t) = POWER_TEXTS.iter().find(|t| t.0 == *p) {
            log.add(t.2);
        }
    }
    for p in new.iter().filter(|p| !ps.known_powers.contains(p)) {
        if let Some(t) = POWER_TEXTS.iter().find(|t| t.0 == *p) {
            log.add(t.1);
        }
    }
    ps.known_powers = new;
}

