/// object1.cc:5477 `gain_flag_group`: spend `pval2` points on a realm the
/// weapon does not own yet and set its bit in `pval3`.
pub fn gain_flag_group(
    gd: &GameData,
    item: &mut crate::item::Item,
    known: &std::collections::HashSet<usize>,
    rng: &mut impl Rng,
    log: &mut MessageLog,
) {
    let mut tries = 1000;
    let mut chosen = None;
    while tries > 0 {
        tries -= 1;
        let grp = rng.gen_range(0..FLAGS_GROUPS.len());
        if item.pval3 & (1 << grp) != 0 {
            continue;
        }
        if FLAGS_GROUPS[grp].1 > item.pval2 {
            continue;
        }
        chosen = Some(grp);
        break;
    }
    let Some(grp) = chosen else { return };
    item.pval2 -= FLAGS_GROUPS[grp].1;
    item.pval3 |= 1 << grp;
    let name = item.label(gd, known);
    log.add(format!(
        "{} gains access to the {} realm.",
        name, FLAGS_GROUPS[grp].0
    ));
}

/// object1.cc:5510 `get_flag`: an as-yet-unowned flag of one realm.
pub fn get_flag(
    gd: &GameData,
    item: &crate::item::Item,
    grp: usize,
    rng: &mut impl Rng,
) -> Option<&'static str> {
    let flag_set = FLAGS_GROUPS[grp].2;
    if flag_set.is_empty() {
        return None;
    }
    let owned = crate::item::item_flags(gd, item);
    let mut tries = 1000;
    while tries > 0 {
        tries -= 1;
        let f = flag_set[rng.gen_range(0..flag_set.len())];
        if owned.contains(&f) {
            continue;
        }
        return Some(f);
    }
    None
}

/// object1.cc:5550 `gain_flag_group_flag`: find an owned realm with a
/// flag the weapon does not have yet and add it.
pub fn gain_flag_group_flag(
    gd: &GameData,
    item: &mut crate::item::Item,
    known: &std::collections::HashSet<usize>,
    rng: &mut impl Rng,
    log: &mut MessageLog,
) -> bool {
    for _ in 0..20000 {
        let grp = rng.gen_range(0..FLAGS_GROUPS.len());
        if item.pval3 & (1 << grp) == 0 {
            continue;
        }
        let Some(f) = get_flag(gd, item, grp, rng) else {
            continue;
        };
        crate::item::add_item_flag(item, f);
        let name = item.label(gd, known);
        log.add(format!(
            "{} gains a new power from the {} realm.",
            name, FLAGS_GROUPS[grp].0
        ));
        return true;
    }
    false
}

fn exp_needed_at(level: u32, exp_factor: u64) -> u64 {
    let idx = (level as usize).clamp(1, 50) - 1;
    PLAYER_EXP[idx] * exp_factor / 100
}

/// dec_stat (spells1.cc:2110): direct stat decay.  Sustains do not
/// protect (do_poly_self calls dec_stat, not do_dec_stat); the "max"
/// stat is untouched because only STAT_DEC_PERMANENT would lower it.
fn poly_dec_stat(ps: &mut PlayerState, stat: usize, amount: i32, rng: &mut impl Rng) {
    let cur = ps.stats[stat];
    if cur <= 3 {
        return;
    }
    let mut cur_new = cur;
    if cur <= 18 {
        if amount > 90 {
            cur_new -= 1;
        }
        if amount > 50 {
            cur_new -= 1;
        }
        if amount > 20 {
            cur_new -= 1;
        }
        cur_new -= 1;
    } else {
        // Decrement by a random amount between one-quarter and one-half
        // of the stat bonus times the percentage (spells1.cc).
        let base = ((cur - 18) / 2 + 1) / 2 + 1;
        let mut loss = ((rng.gen_range(1..=base.max(1)) + base) * amount) / 100;
        if loss < amount / 2 {
            loss = amount / 2;
        }
        cur_new -= loss;
        if cur_new < 18 {
            cur_new = if amount <= 20 { 18 } else { 17 };
        }
    }
    ps.stats[stat] = cur_new.max(3);
}

/// do_poly_wounds (cmd5.cc:260): heal cuts/hit points, with a 1/5
/// chance of creating a new wound instead.
fn poly_wounds(ps: &mut PlayerState, log: &mut MessageLog, rng: &mut impl Rng) {
    let wounds = ps.cut;
    let hit_p = ps.max_hp - ps.hp;
    let change = Dice {
        count: ps.level as i32,
        sides: 5,
        bonus: 0,
    }
    .roll(rng);
    let nasty = rng.gen_range(0..5) == 0;
    if wounds == 0 && hit_p <= 0 && !nasty {
        return;
    }
    log.add("Your wounds are polymorphed into less serious ones.");
    ps.hp = (ps.hp + change).min(ps.max_hp);
    if nasty {
        log.add("A new wound was created!");
        ps.hp -= change / 2;
        ps.cut = (ps.cut + change).min(10000);
    } else {
        ps.cut = (ps.cut - change / 2).max(0);
    }
}

/// corrupt_player (spells1.cc:2350): swap two stats' current and
/// maximum values.
fn corrupt_player(ps: &mut PlayerState, rng: &mut impl Rng) {
    let i = rng.gen_range(0..6);
    let mut j = rng.gen_range(0..6);
    while j == i {
        j = rng.gen_range(0..6);
    }
    ps.stats.swap(i, j);
    ps.stat_base.swap(i, j);
}

/// do_cmd_rerate (wizard2.cc:115): reroll the whole HP history with
/// birth.cc roll_player_hp's 3/8..5/8 band at level 50, then let the
/// PU_HP pass (xtra1.cc calc_hitpoints) rebuild max_hp from the new rolls
/// (adj_con_mhp[stat_index(CON)] * level / 2).  The Life Rating uses the
/// cumulative level-50 total (player_hp[PY_MAX_LEVEL-1]).
pub fn rerate_hp(ps: &mut PlayerState, gd: &GameData, log: &mut MessageLog, rng: &mut impl Rng) {
    const PY_MAX_LEVEL: i32 = 50;
    let hd = ps.hitdie.max(1);
    let min_value = (PY_MAX_LEVEL * (hd - 1) * 3) / 8 + PY_MAX_LEVEL;
    let max_value = (PY_MAX_LEVEL * (hd - 1) * 5) / 8 + PY_MAX_LEVEL;
    let mut rolls = vec![hd];
    loop {
        rolls.truncate(1);
        while (rolls.len() as i32) < PY_MAX_LEVEL {
            rolls.push(rng.gen_range(1..=hd));
        }
        let total: i32 = rolls.iter().sum();
        if total >= min_value && total <= max_value {
            break;
        }
    }
    let total_all: i32 = rolls.iter().sum();
    let level = (ps.level as usize).min(rolls.len());
    ps.hp_planned = rolls.clone();
    ps.hp_rolls = rolls[..level].to_vec();
    // handle_stuff (PU_HP) -> calc_hitpoints.
    recalc_max_hp(ps, &crate::item::Inventory::default(), gd);
    ps.hp = ps.hp.min(ps.max_hp);
    let percent = (total_all * 200) / (hd * PY_MAX_LEVEL).max(1);
    log.add(format!("Current Life Rating is {}/100.", percent));
}

/// do_rebirth (xtra2.cc:5366): recompute the experience factor and hit
/// die from the current race/subrace/class, re-rate the HP pool and run
/// the level check.  Used by the dynamic vampire corruption chain
/// (corrupt.cc player_gain_vampire_strength; the corrupt.rs call site is
/// outside this module).
pub fn do_rebirth(
    ps: &mut PlayerState,
    gd: &GameData,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    let race = gd.races.iter().find(|r| r.name == ps.race_name);
    let subrace = gd.racemods.get(ps.subrace as usize);
    let class = ps.class(gd);
    if let Some(r) = race {
        ps.exp_factor = (r.exp as i32
            + subrace.map(|m| m.exp).unwrap_or(0)
            + class.map(|c| c.exp as i32).unwrap_or(0))
        .max(1) as u64;
        ps.hitdie = (r.hitdie as i32
            + subrace.map(|m| m.hitdie).unwrap_or(0)
            + class.map(|c| c.hitdie as i32).unwrap_or(0))
        .max(1);
    }
    rerate_hp(ps, gd, log, rng);
    check_experience(ps, log, rng);
    ps.max_plv = ps.level;
}

/// do_poly_self (cmd5.cc:288): the permanent racial polymorph triggered
/// by GF_NUKE.  Mutations may deform the body, drain stats and
/// corruptions, reroll hit points and finally change the player's race
/// outright (the old race is simply discarded; the subrace is kept).
pub fn do_poly_self(
    gd: &GameData,
    ps: &mut PlayerState,
    inv: &Inventory,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    let mut power = ps.level as i32;
    let mut deformed = false;
    log.add("You feel a change coming over you...");

    if power > rng.gen_range(0..20) && rng.gen_range(0..3) == 0 {
        // Some form of racial polymorph...
        power -= 10;

        if power > rng.gen_range(0..30) && rng.gen_range(0..5) == 0 {
            // Harmful deformity
            power -= 15;
            for stat in 0..6 {
                if rng.gen_range(0..2) == 0 {
                    poly_dec_stat(ps, stat, rng.gen_range(1..=6) + 6, rng);
                    power -= 1;
                }
            }
            // Deformities are discriminated against!
            poly_dec_stat(ps, CHA, rng.gen_range(1..=6), rng);
            deformed = true;
        }

        while power > rng.gen_range(0..20) && rng.gen_range(0..10) == 0 {
            // Polymorph into a less corrupted form
            power -= 10;
            crate::corrupt::lose_random(ps, log, rng);
        }

        let poly_power = power.max(1);
        // Restrict the race choices by exp penalty so weak polymorph
        // always means weak race.
        let goalexpfact = 100 + 3 * rng.gen_range(0..poly_power);
        let old_race = gd
            .races
            .iter()
            .position(|r| r.name == ps.race_name)
            .unwrap_or(0);
        let new_race = loop {
            let idx = rng.gen_range(0..gd.races.len());
            let race = &gd.races[idx];
            if race.name != ps.race_name && race.exp as i32 <= goalexpfact {
                break idx;
            }
        };
        let title = gd.races[new_race].name.clone();
        if deformed {
            log.add(format!("You turn into a deformed {}!", title));
        } else {
            let vowel = title
                .chars()
                .next()
                .map(|c| "aeiouAEIOU".contains(c))
                .unwrap_or(false);
            log.add(format!(
                "You turn into {} {}!",
                if vowel { "an" } else { "a" },
                title
            ));
        }
        // The race's stat modifiers replace the old race's (calc_bonuses).
        for i in 0..6 {
            let delta = gd.races[new_race].stats[i] - gd.races[old_race].stats[i];
            ps.stats[i] += delta;
            ps.stat_base[i] += delta;
        }
        ps.race_name = title;
        // Experience factor (xp_ptr->ps.exp + rmp_ptr->ps.exp + cp_ptr->ps.exp)
        let sub_exp = gd
            .racemods
            .get(ps.subrace as usize)
            .map(|m| m.exp)
            .unwrap_or(0);
        let class_exp = ps.class(gd).map(|c| c.exp as i32).unwrap_or(0);
        ps.exp_factor = (gd.races[new_race].exp as i32 + sub_exp + class_exp).max(1) as u64;
        // Level up/down if necessary.
        check_experience(ps, log, rng);
        ps.ac = player_ac(ps, inv, gd);
    }

    if power > rng.gen_range(0..30) && rng.gen_range(0..6) == 0 {
        // Abomination!
        power -= 20;
        log.add("Your internal organs are rearranged!");
        for stat in 0..6 {
            poly_dec_stat(ps, stat, rng.gen_range(1..=6) + 6, rng);
        }
        if rng.gen_range(0..6) == 0 {
            log.add("You find living difficult in your present form!");
            let d = Dice {
                count: rng.gen_range(1..=10),
                sides: ps.level as i32,
                bonus: 0,
            }
            .roll(rng);
            ps.hp -= d;
            power -= 10;
        }
    }

    if power > rng.gen_range(0..20) && rng.gen_range(0..4) == 0 {
        power -= 10;
        rerate_hp(ps, gd, log, rng);
    }

    while power > rng.gen_range(0..15) && rng.gen_range(0..3) == 0 {
        power -= 7;
        crate::corrupt::gain_random(gd, ps, log, rng);
    }

    if power > rng.gen_range(0..5) {
        power -= 5;
        poly_wounds(ps, log, rng);
    }

    // Note: earlier deductions may have left power < 0 already.
    while power > 0 {
        corrupt_player(ps, rng);
        power -= 1;
    }
}

/// gain_fate (src/xtra1.cc): roll a new prophecy.  Called rarely from
/// upkeep (one in 50000 turns past level 10) and by forced fates.
pub fn gain_fate(
    gd: &GameData,
    ps: &mut PlayerState,
    luck: i32,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    if ps.fates.iter().filter(|f| f.fate != 0).count() >= MAX_FATES {
        return;
    }
    let maxd = ps.max_depth.max(ps.depth).max(1) as i32;
    let mut f = Fate::default();
    // Lucky characters never draw the death fate (xtra1.cc gain_fate:
    // `rand_int(p_ptr->luck_cur > 0 ? 17 : 18)`).
    let top = if luck > 0 { 17 } else { 18 };
    match rng.gen_range(0..top) {
        6 | 2 | 3 | 7 | 8 | 9 | 13 => f.fate = FATE_FIND_O,
        1 | 4 | 5 | 10 | 11 | 12 | 14 => f.fate = FATE_FIND_R,
        15 | 16 => f.fate = FATE_FIND_A,
        17 => f.fate = FATE_DIE,
        _ => {
            // The all-important death-immunity fate is rare and
            // depth-scaled (xtra1.cc gain_fate case 0).
            let chance = (maxd / 4).min(50);
            f.fate = if rng.gen_range(0..100) < chance {
                FATE_NO_DIE_MORTAL
            } else {
                FATE_FIND_O
            };
        }
    }
    match f.fate {
        FATE_FIND_O => {
            for _ in 0..1000 {
                let level = (maxd + rng.gen_range(1..=10)).max(1) as u32;
                let Some(k) = crate::item::gen_object_kind(gd, level, rng) else {
                    break;
                };
                if gd.objects[k]
                    .flags
                    .iter()
                    .any(|x| x == "INSTA_ART" || x == "NORM_ART")
                {
                    continue;
                }
                f.object = k as u32;
                break;
            }
            if f.object == 0 {
                return;
            }
            f.level = fate_level(maxd + rng.gen_range(-20..=20));
            f.serious = rng.gen_range(0..=1) == 1;
        }
        FATE_FIND_R => {
            let level = fate_level(maxd + rng.gen_range(-20..=20));
            let candidates: Vec<usize> = (0..gd.monster_base_count)
                .filter(|&i| {
                    let d = &gd.monsters[i];
                    d.depth >= 1 && d.depth <= level && !d.unique
                })
                .collect();
            if candidates.is_empty() {
                return;
            }
            f.monster = candidates[rng.gen_range(0..candidates.len())] as u32;
            f.level = level;
            f.serious = rng.gen_range(0..=1) == 1;
        }
        FATE_FIND_A => {
            f.artifact = choose_fate_artifact(gd, maxd, rng);
            f.level = fate_level(maxd + rng.gen_range(-20..=20));
            f.serious = true;
        }
        FATE_DIE => {
            f.level = fate_level(maxd + rng.gen_range(-20..=20));
            f.serious = true;
        }
        FATE_NO_DIE_MORTAL => {
            f.serious = true;
            ps.no_mortal = true;
        }
        _ => {}
    }
    log.add("More of your prophecy has been unearthed!");
    log.add("You should see a soothsayer quickly.");
    ps.fates.push(f);
}

/// get_artifact_idx (xtra1.cc): a random uncreated artifact within the
/// level, never SPECIAL_GENE.  0 means "grant a randart".
fn choose_fate_artifact(gd: &GameData, level: i32, rng: &mut impl Rng) -> u32 {
    for _ in 0..1000 {
        let a = &gd.artifacts[rng.gen_range(0..gd.artifacts.len())];
        if a.tval == 0 {
            continue;
        }
        if a.depth as i32 > level {
            continue;
        }
        if a.flags.iter().any(|f| f == "SPECIAL_GENE") {
            continue;
        }
        return a.id;
    }
    0
}

/// fate_desc (xtra1.cc): the soothsayer's reading of one fate.
pub fn fate_desc(gd: &GameData, f: &Fate) -> String {
    let lead = if f.serious {
        "You are fated to "
    } else {
        "You may "
    };
    match f.fate {
        FATE_FIND_O => format!(
            "{lead}find {} on level {}.",
            gd.objects
                .get(f.object as usize)
                .map(|o| o.name.clone())
                .unwrap_or_else(|| "something".to_string()),
            f.level
        ),
        FATE_FIND_A => {
            let name = gd
                .artifacts
                .iter()
                .find(|a| a.id == f.artifact)
                .map(|a| {
                    let base = gd
                        .object_by_tval_sval(a.tval, a.sval)
                        .map(|k| gd.objects[k].name.clone())
                        .unwrap_or_default();
                    format!("{} {}", base, a.name)
                })
                .unwrap_or_else(|| "something special".to_string());
            format!("{lead}find {name} on level {}.", f.level)
        }
        FATE_FIND_R => format!(
            "{lead}meet {} on level {}.",
            gd.monsters
                .get(f.monster as usize)
                .map(|m| m.name.clone())
                .unwrap_or_else(|| "someone".to_string()),
            f.level
        ),
        FATE_DIE => format!("{lead}die on level {}.", f.level),
        FATE_NO_DIE_MORTAL => {
            "You are fated never to die by the hand of a mortal being.".to_string()
        }
        _ => String::new(),
    }
}

/// dump_fates (xtra1.cc): every known fate line, plus a warning while
/// some fate is still unknown.
#[allow(dead_code)]
pub fn dump_fates(gd: &GameData, ps: &PlayerState) -> String {
    let mut out = String::new();
    let mut pending = false;
    for f in &ps.fates {
        if f.fate != 0 && f.know {
            out.push_str(&fate_desc(gd, f));
            out.push('\n');
        }
        pending |= f.fate != 0 && !f.know;
    }
    if pending {
        out.push_str("You do not know all of your fate.\n");
    }
    out
}

/// `quest_main_monsters_hook` (q_main.cc:44): Sauron is not generated
/// while the Necromancer lives, Morgoth not while Sauron lives.
pub fn main_quest_blocks(name: &str, plot: &PlotQuest) -> bool {
    (name == "Sauron, the Sorcerer" && plot.status(PLOT_NECRO) < PLOT_COMPLETED)
        || (name == "Morgoth, Lord of Darkness" && plot.status(PLOT_SAURON) < PLOT_COMPLETED)
}

/// The main plot's kill progression (q_main.cc / q_one.cc): the
/// Necromancer -> One Ring -> Sauron -> Morgoth -> Void chain, driven by
/// the plot-quest states instead of the retired linear quest chain.
pub fn check_main_quest_kill(
    gd: &GameData,
    def_idx: usize,
    ps: &mut PlayerState,
    plot: &mut PlotQuest,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    let Some(def) = gd.monsters.get(def_idx) else {
        return;
    };
    // quest_sauron_resurrect_hook: while Sauron has not been permanently
    // slain, a dying Nazgul calls him back (max_num = 1).
    if def.has("NAZGUL") && plot.status(PLOT_SAURON) < PLOT_COMPLETED {
        let sauron = gd.monster_by_name("Sauron, the Sorcerer");
        if let Some(s) = sauron {
            if ps.unique_seen.contains(&s) {
                log.add("Somehow you feel Sauron is not totally destroyed...");
                ps.unique_seen.remove(&s);
            }
        }
    }
    match def.name.as_str() {
        "The Necromancer of Dol Guldur" => {
            if plot.status(PLOT_NECRO) == PLOT_TAKEN {
                log.add("You see the spirit of the necromancer rise and flee...");
                log.add("It looks like it was indeed Sauron...");
                log.add("You should report that to Galadriel as soon as possible.");
                plot.set(PLOT_NECRO, PLOT_COMPLETED);
            }
        }
        "Sauron, the Sorcerer" => {
            if plot.status(PLOT_SAURON) != PLOT_TAKEN {
                return;
            }
            if !(ps.ring_destroyed || ps.ring_worn) {
                log.add("Sauron will not be permanently defeated until the One Ring is either destroyed or used...");
                ps.unique_seen.remove(&def_idx);
                return;
            }
            if ps.ring_worn {
                log.add("'The Ring is mine!' Sauron's spirit is drawn into the Ring;");
                log.add("his dark tower is silent at last.");
            }
            log.add("Well done! You are on the way to slaying Morgoth...");
            plot.set(PLOT_SAURON, PLOT_COMPLETED);
            plot.set(PLOT_MORGOTH, PLOT_TAKEN);
        }
        "Morgoth, Lord of Darkness" => {
            if plot.status(PLOT_MORGOTH) != PLOT_TAKEN {
                return;
            }
            plot.set(PLOT_MORGOTH, PLOT_COMPLETED);
            if ps.ring_destroyed {
                log.add("*** CONGRATULATIONS ***");
                log.add("You have banished Morgoth's foul spirit from Ea, and as you watch, a cleansing");
                log.add("wind roars through the dungeon, dispersing the nether mists around where the");
                log.add("body fell. You feel thanks, and a touch of sorrow, from the Valar");
                log.add("for your deed. You will be forever heralded, your deed forever legendary.");
                log.add("You may retire (commit suicide) when you are ready.");
                // With the One Ring destroyed the plot continues in the
                // Void (q_main.cc: plot = QUEST_ULTRA_GOOD).
                plot.set(PLOT_ULTRA_GOOD, PLOT_TAKEN);
                plot.ultra_good_unlocked = true;
                log.add("But a greater shadow still lurks beyond the world: Melkor.");
                log.add("The mirror of Galadriel in Lothlorien may show you the way.");
            } else {
                log.add("*** CONGRATULATIONS ***");
                log.add("You have banished Morgoth from Arda, and made Ea a safer place.");
                log.add("As you look down at the dispersing mists around Morgoth, a sudden intuition");
                log.add("grasps you. Fingering the One Ring, you gather the nether mists around");
                log.add("yourself, and inhale deeply their seductive power.");
                log.add("You will be forever feared, your orders forever obeyed.");
                log.add("You may retire (commit suicide) when you are ready.");
                plot.set(PLOT_ULTRA_EVIL, PLOT_COMPLETED);
                plot.won = true;
            }
            let _ = rng;
        }
        _ => {}
    }
}

/// `quest_invasion_ai_hook`'s escape clause (q_invas.cc:71): Maeglin
/// reaching the exit staircase fails the invasion and destroys Gondolin
/// (town 2).
pub fn invasion_maeglin_escaped(plot: &mut PlotQuest, log: &mut MessageLog) {
    plot.set(PLOT_INVASION, PLOT_FAILED);
    plot.destroyed_towns[2] = true;
    plot.town_dirty = true;
    log.add("Maeglin has escaped! Gondolin will fall...");
}

/// Plot-quest kill checks: kill-everything quests end when no quest
/// monster remains; named bosses count by name; nirnaeth needs only
/// two thirds of the trolls dead; killing Maggot's dogs fails his quest.
/// Pays each quest's reward and opens the exit staircase.
#[allow(clippy::too_many_arguments)]
pub fn check_plot_kill(
    gd: &GameData,
    def_idx: usize,
    quest_left: i32,
    enemy_left: i32,
    depth: u32,
    pos: (i32, i32),
    map: &mut Map,
    plot: &mut PlotQuest,
    ps: &mut PlayerState,
    inv: &mut Inventory,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    let name = gd.monsters[def_idx].name.as_str();
    // The Dark Horseman rides through Bree itself (depth 0).
    if depth == 0 {
        if name == "Uvatha the Horseman" && plot.status(PLOT_NAZGUL) == PLOT_TAKEN {
            // q_nazgul.cc death hook: completion only; the six Athelas
            // are handed over when the mayor is told (finish hook).
            plot.set(PLOT_NAZGUL, PLOT_COMPLETED);
            log.add("The Dark Horseman is destroyed!");
        }
        return;
    }
    if depth < PLOT_DEPTH_BASE {
        // Thrain's nazgul gaolers (the vault sits inside the dungeon).
        if plot.status(PLOT_THRAIN) == PLOT_TAKEN
            && matches!(name, "Dwar, Dog Lord of Waw" | "Hoarmurath of Dir")
            && quest_left <= 0
        {
            plot.set(PLOT_THRAIN, PLOT_FINISHED);
            log.add("The magic hiding the room dissipates.");
            log.add("Thrain speaks:");
            log.add("'Ah, at last you came to me!  But... I fear it is too late for me.");
            log.add("However your quest continues, you must beware for the Necromancer");
            log.add("is in fact Sauron, the Dark Lord! He stole the Ring of Durin and tortured");
            log.add("me... arrgh... please make him pay!'");
            // Thrain's reward: a randart Dragon Helm "of Thrain" is
            // dropped where he stood (q_thrain.cc: drop_near; the kill
            // handler below creates it so the floor stack is available).
            plot.thrain_reward = true;
        }
        return;
    }
    let qid = depth - PLOT_DEPTH_BASE;
    if plot.status(qid) != PLOT_TAKEN {
        return;
    }
    // Every death inside the Nirnaeth counts toward the two-thirds bonus
    // (q_nirna.cc death hook).
    if qid == PLOT_NIRNAETH {
        plot.nirnaeth_kills += 1;
    }
    // q_betwen.cc death hook: once fewer than two non-friendly monsters
    // remain the way out opens under the player ("You can escape now.").
    // The staircase itself is raised on the next input frame where the
    // player's position is available.
    if qid == PLOT_BETWEEN && enemy_left <= 0 {
        plot.between_escape = true;
    }
    if qid == PLOT_SHROOM {
        if name.ends_with("Farmer Maggot's dog") {
            plot.set(PLOT_SHROOM, PLOT_FAILED);
            log.add("You killed one of Farmer Maggot's dogs!");
        }
        return;
    }
    let done = match qid {
        // Every enemy must fall, not just the quest-flagged ones
        // (q_wolves/q_spider/q_haunted/q_dragons/q_evil death hooks:
        // status <= MSTATUS_ENEMY, mcnt <= 1 counting the fresh corpse;
        // q_library the same via count == 0).
        PLOT_WOLVES | PLOT_SPIDER | PLOT_HAUNTED | PLOT_DRAGONS | PLOT_EVIL | PLOT_LIBRARY => {
            enemy_left <= 0
        }
        // Thieves count down to zero too, but include neutrals
        // (q_thief.cc: status < MSTATUS_FRIEND && !mcnt).
        PLOT_THIEVES => quest_left <= 0 && enemy_left <= 0,
        PLOT_TROLL => name == "Tom the Stone Troll",
        PLOT_WIGHT => name == "The Wight-King of the Barrow-downs",
        PLOT_INVASION => name == "Maeglin, the Traitor of Gondolin",
        PLOT_EOL => name == "Eol, the Dark Elf",
        _ => false,
    };
    if !done {
        return;
    }
    // q_evil's death hook finishes the quest outright: the original has no
    // mayor for it (q_evil.cc:78 sets QUEST_STATUS_FINISHED and clears the
    // plot, with the "change to COMPLETED ... when mayor is added" TODO).
    plot.set(
        qid,
        if qid == PLOT_EVIL {
            PLOT_FINISHED
        } else {
            PLOT_COMPLETED
        },
    );
    // The death hooks' completion messages (q_*.cc; quests without a
    // message keep the port's generic line).
    match qid {
        PLOT_WOLVES => log.add("Lothlorien is safer now."),
        PLOT_SPIDER => {
            log.add("The forest is now safer, thanks to you.");
            // Yavanna LOVES saving forests (q_spider.cc death hook).
            if ps.god == 5 {
                log.add("You feel the gentle touch of Yavanna, as she smiles at you.");
                ps.grace = (ps.grace + 6000).min(300000);
            }
        }
        PLOT_THIEVES => {
            log.add("The magic hiding the stairs is now gone.");
            log.add("You stopped the thieves and saved Bree!");
        }
        PLOT_HAUNTED => log.add("Minas Anor is safer now."),
        PLOT_DRAGONS => log.add("Gondolin is safer now."),
        PLOT_EVIL => log.add("Khazad-Dum is safer now."),
        PLOT_LIBRARY => log.add("The library is safe now."),
        PLOT_TROLL => log.add("Without Tom, the trolls won't be able to do much."),
        PLOT_INVASION => log.add("You did it! Gondolin will remain hidden."),
        PLOT_EOL => log.add("Such a sad end..."),
        _ => log.add(format!("You have completed {}!", plot_quest_name(qid))),
    }
    if qid == PLOT_WIGHT {
        // The Wight-King's fall opens the way right under the player
        // (q_wight.cc: cave_set_feat(py, px, FEAT_LESS)).
        log.add("Without their King the wights won't be able to do much.");
        map.set_terrain(pos.0, pos.1, map::T_STAIRS_UP);
    } else if let Some(qm) = gd.quest_map(qid) {
        // The way out appears (the original spawns the exit staircase).
        let (ox, oy) = map::quest_map_offset(qm);
        map.set_terrain(qm.exit.0 + ox, qm.exit.1 + oy, map::T_STAIRS_UP);
        log.add("A staircase leading up appears!");
    }
}

/// Hand a reward item to the player (into the pack).
pub fn ps_reward_item(inv: &mut Inventory, gd: &GameData, it: item::Item, log: &mut MessageLog) {
    log.add(format!("You receive {}!", it.label(gd, &inv.known)));
    inv.add_with(gd, it);
}

/// Report a completed quest to its patron: COMPLETED -> FINISHED and the
/// original finish hook's reward (bldg.cc castle_quest + q_*.cc
/// HOOK_QUEST_FINISH). Returns true when anything was reported.
pub fn finish_plot_quest(
    gd: &GameData,
    plot: &mut PlotQuest,
    ps: &mut PlayerState,
    inv: &mut Inventory,
    log: &mut MessageLog,
    rng: &mut impl Rng,
    qid: u32,
) -> bool {
    // Reporting a failed quest marks it done but failed (bldg.cc
    // castle_quest HOOK_QUEST_FAIL; only Eol has a fail message).
    if plot.status(qid) == PLOT_FAILED {
        plot.set(qid, PLOT_FAILED_DONE);
        if qid == PLOT_EOL {
            log.add("You fled ! I did not think you would flee...");
        } else {
            log.add("You have failed your quest. It is over.");
        }
        return true;
    }
    if plot.status(qid) != PLOT_COMPLETED {
        return false;
    }
    plot.set(qid, PLOT_FINISHED);
    plot.town_dirty = true;
    match qid {
        PLOT_THIEVES => {
            log.add("'Thank you for killing the band of thieves!'");
            log.add("'You can use the hideout as your house as a reward.'");
        }
        PLOT_TROLL | PLOT_WIGHT => {
            log.add("'I heard about your noble deeds.'");
            log.add("'Keep what you found... may it serve you well.'");
        }
        PLOT_WOLVES => {
            log.add("'Thank you for killing the pack of wolves!'");
            log.add("'You can use the hut as your house as a reward.'");
        }
        PLOT_SPIDER => {
            log.add("'All of us praise your mighty deed in driving back the menace.'");
            log.add("'Take this as a reward.'");
            if let Some(it) = named_item(gd, "Augmentation", None, 25, &mut HashSet::new(), rng) {
                ps_reward_item(inv, gd, it, log);
            }
            if ps.god == 5 {
                ps.grace = (ps.grace + 6000).min(300000);
                log.add("Yavanna smiles upon you. (+6000 grace)");
            }
            // Finishing the spiders starts the poisoned-water quest
            // (q_spider.cc finish hook).
            if plot.status(PLOT_POISON) == PLOT_UNTAKEN {
                const POISON_LOCS: [(i32, i32); 4] = [(32, 49), (32, 48), (33, 48), (34, 48)];
                let cell = POISON_LOCS[rng.gen_range(0..4)];
                plot.poison_cell = Some(cell);
                plot.set(PLOT_POISON, PLOT_TAKEN);
                if let Some(def) = gd.object_by_name("Water Curing") {
                    let mut it = item::Item::base(gd, def);
                    it.count = 99;
                    inv.add_with(gd, it);
                }
                log.add("Mallorn water has been poisoned! The elves ask for help.");
                log.add("(You receive 99 flasks of cure-water; seek the foul pond.)");
            }
        }
        PLOT_HAUNTED => {
            log.add("'Minas Anor is safer now. The freed house is yours to rest in.'");
        }
        PLOT_NAZGUL => {
            // q_nazgul.cc finish hook: the six Athelas reward.
            log.add("'I believe he will not come back! Thank you.'");
            log.add("'Some time ago a ranger gave me this.'");
            log.add("'I believe it will help you on your quest.'");
            if let Some(def) = gd.object_by_tval_sval(crate::data::TV_FOOD, 40) {
                let mut it = item::Item::base(gd, def);
                it.count = 6;
                ps_reward_item(inv, gd, it, log);
            }
        }
        PLOT_DRAGONS => {
            log.add("'The dragon lair makes a fine new home for you.'");
        }
        PLOT_EVIL => {
            // q_evil.cc quest_evil_finish_hook (normally unreachable: the
            // death hook finishes the quest directly).
            log.add("'Thank you for saving us!'");
            log.add("'You can use the cave as your house as a reward.'");
        }
        PLOT_POISON => {
            // q_poison.cc quest_poison_finish_hook: the mayor's thanks and
            // the Blue Dragon Scale Mail with the Elvenkind ego (forced by
            // name2, EGO_ELVENKIND = 10).
            log.add("'The water is clean again! Thank you so much.'");
            log.add("'The beautiful Mallorns are safe. Take this as a proof of our gratitude.'");
            if let Some(def) = gd.object_by_tval_sval(crate::data::TV_DRAG_ARMOR, 2) {
                let mut it = item::force_ego(gd, def, 10, 1, rng);
                it.found = item::OBJ_FOUND_REWARD;
                it.count = 1;
                it.identified = true;
                ps_reward_item(inv, gd, it, log);
            }
        }
        PLOT_LIBRARY => {
            log.add("'The library is saved! My sage will help you write a book of your own.'");
        }
        PLOT_NIRNAETH => {
            // Only slaying at least two thirds of the trolls earns the gold
            // (q_nirna.cc finish hook); the shop is granted either way.
            if plot.quest_total > 0 && 3 * plot.nirnaeth_kills >= 2 * plot.quest_total {
                log.add("'Not only did you found a way out, but you also destroyed a good'");
                log.add("'number of trolls! Thank you so much. Take this gold please.'");
                log.add("'I also grant you access to the royal jewelry shop!'");
                ps.gold += 200000;
            } else {
                log.add("'I thank you for your efforts.'");
                log.add("'I grant you access to the royal jewelry shop!'");
            }
        }
        PLOT_INVASION => {
            log.add("'I will never be able to thank you enough.'");
        }
        PLOT_EOL => {
            log.add("'A tragedy, but the deed needed to be done.'");
            log.add("'Accept my thanks, and that reward.'");
            if let Some(it) = named_item(
                gd,
                "Dwarven Lantern",
                Some("of the Magi"),
                30,
                &mut HashSet::new(),
                rng,
            ) {
                ps_reward_item(inv, gd, it, log);
            }
        }
        PLOT_BETWEEN => {
            log.add("'Ah you finally arrived, I hope your travel wasn't too hard.'");
            log.add("'As a reward you can freely use the Void Jumpgates for quick travel.'");
            log.add("'Oh and take that horn, it shall serve you well.'");
            if let Some(def) = gd.object_by_id(298) {
                let mut horn = item::Item::base(gd, def);
                horn.identified = true;
                ps_reward_item(inv, gd, horn, log);
            }
        }
        _ => {}
    }
    true
}

/// Build a d_info '@:' set-piece level (fixed layout and monsters).
/// The originals are the final levels of side dungeons; as our dungeon
/// is a single shaft, staircases are guaranteed both ways.
#[allow(clippy::too_many_arguments)]
fn build_spec_level(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    dungeon: u32,
    sl: &crate::data::SpecLevelDef,
    level_flags: &[String],
    created: &mut HashSet<u32>,
    rng: &mut impl Rng,
) -> map::GeneratedLevel {
    let mut map = map::blank_pub(map::T_PERMANENT);
    let (ox, oy) = ((map::MAP_W - sl.w) / 2, (map::MAP_H - sl.h) / 2);
    for (i, c) in sl.cells.iter().enumerate() {
        let x = ox + i as i32 % sl.w;
        let y = oy + i as i32 / sl.w;
        map.set_terrain(x, y, c.t);
        map.lit[Map::idx(x, y)] = c.l;
    }
    // `M:` mimic cells display another feature until the map is learned.
    for m in &sl.mimics {
        let (x, y) = (m.x + ox, m.y + oy);
        if Map::in_bounds(x, y) && m.t != map::T_NOTHING {
            map.mimic.insert(Map::idx(x, y), m.t);
        }
    }
    let mut start = (sl.start.0 + ox, sl.start.1 + oy);
    if !map.walkable(gd, start.0, start.1) {
        'outer: for r in 1i32..20 {
            for dy in -r..=r {
                for dx in -r..=r {
                    if dx.abs().max(dy.abs()) != r {
                        continue;
                    }
                    let (x, y) = (start.0 + dx, start.1 + dy);
                    if Map::in_bounds(x, y) && map.walkable(gd, x, y) {
                        start = (x, y);
                        break 'outer;
                    }
                }
            }
        }
    }
    // Guarantee both staircases (the originals are one-way finals)
    // unless the level's `@:` flags say NO_STAIR (generate.cc:725).
    let no_stair = level_flags.iter().any(|f| f == "NO_STAIR");
    let mut has_up = false;
    let mut has_down = false;
    for y in 0..map::MAP_H {
        for x in 0..map::MAP_W {
            let t = map.terrain_at(x, y);
            has_up |= t == map::T_STAIRS_UP;
            has_down |= t == map::T_STAIRS_DOWN;
        }
    }
    if !no_stair && !has_up {
        map.set_terrain(start.0, start.1, map::T_STAIRS_UP);
    }
    if !no_stair && !has_down {
        for _ in 0..500 {
            let x = rng.gen_range(1..map::MAP_W - 1);
            let y = rng.gen_range(1..map::MAP_H - 1);
            if map.walkable(gd, x, y) && (x, y) != start {
                map.set_terrain(x, y, map::T_STAIRS_DOWN);
                break;
            }
        }
    }
    for m in &sl.monsters {
        if let Some(d) = gd.monster_by_id(m.def) {
            spawn_single(
                commands,
                gd,
                tiles,
                d,
                m.x + ox,
                m.y + oy,
                false,
                false,
                rng,
            );
        }
    }
    for o in &sl.objects {
        if let Some(def) = gd.object_by_id(o.def) {
            let it = item::Item::base(gd, def);
            let od = &gd.objects[def];
            commands.spawn((
                item::FloorItem { stack: vec![it] },
                GameEntity,
                GridPos {
                    x: o.x + ox,
                    y: o.y + oy,
                },
                render::glyph_sprite(tiles, od.glyph(), od.color),
                Transform::from_translation(render::grid_to_world(o.x + ox, o.y + oy, 1.5)),
                Visibility::Hidden,
            ));
        }
    }
    // Fixed map artifact placements (the F: artifact field; init1.cc
    // builds these with a_allow_special, so SPECIAL_GENE is fine here --
    // e.g. Narya in s_gates.map).
    for a in &sl.artifacts {
        let (x, y) = (a.x + ox, a.y + oy);
        if let Some(mut it) = item::make_specific_artifact(gd, a.id, created, rng) {
            // init1.cc:6359: o_ptr->found = OBJ_FOUND_SPECIAL.
            it.found = item::OBJ_FOUND_SPECIAL;
            let od = &gd.objects[it.def];
            commands.spawn((
                item::FloorItem { stack: vec![it] },
                GameEntity,
                GridPos { x, y },
                render::glyph_sprite(tiles, od.glyph(), od.color),
                Transform::from_translation(render::grid_to_world(x, y, 1.5)),
                Visibility::Hidden,
            ));
        }
    }
    // `F:...:*N` random monster/object markers (spec levels load with
    // quest level 0, so the recorded offsets are absolute).
    let mut vault = map::VaultSpawns::default();
    map::roll_map_markers(
        0,
        &sl.random_monsters,
        &sl.random_objects,
        (ox, oy),
        &mut vault,
        rng,
    );
    let theme = gd.dungeon(dungeon).theme;
    for &(level, x, y) in &vault.random_monsters {
        if let Some(def) = random_monster_of_level(gd, level, rng) {
            spawn_single(commands, gd, tiles, def, x, y, false, false, rng);
        }
    }
    for &(level, x, y, good, great) in &vault.random_objects {
        if let Some(mut it) = item::make_object_themed(gd, level, good, great, theme, created, rng)
        {
            // init1.cc:6335: place_object(..., OBJ_FOUND_SPECIAL).
            let (r, g) = item::rating_of(gd, &it, level);
            map.rating += r;
            map.good_item |= g;
            it.found = item::OBJ_FOUND_SPECIAL;
            let od = &gd.objects[it.def];
            commands.spawn((
                item::FloorItem { stack: vec![it] },
                GameEntity,
                GridPos { x, y },
                render::glyph_sprite(tiles, od.glyph(), od.color),
                Transform::from_translation(render::grid_to_world(x, y, 1.5)),
                Visibility::Hidden,
            ));
        }
    }
    // build_special_level: the level always carries the "special item"
    // feeling (good_item_flag = true, rating += 40).
    map.good_item = true;
    map.rating += 40;
    map.feeling = map::feeling_from_rating(map.rating, true);
    map::GeneratedLevel { map, start, vault }
}

/// Embed the Thrain vault into a normal dungeon level (q_thrain.cc):
/// the cell block is stamped into the map, the nazgul gaolers guard
/// the prisoner.
#[allow(clippy::too_many_arguments)]
fn embed_thrain(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &mut Map,
    plot: &mut PlotQuest,
    rng: &mut impl Rng,
    log: &mut MessageLog,
) {
    let Some(qm) = gd.quest_map(PLOT_THRAIN) else {
        return;
    };
    // Find a spot where the vault fits over floor/rock.
    let mut placed = false;
    for _ in 0..200 {
        let ox = rng.gen_range(1..map::MAP_W - qm.w - 1);
        let oy = rng.gen_range(1..map::MAP_H - qm.h - 1);
        let fits = (0..qm.h).all(|y| {
            (0..qm.w).all(|x| {
                let t = map.terrain_at(ox + x, oy + y);
                t == map::T_GRANITE || t == map::T_FLOOR
            })
        });
        if !fits {
            continue;
        }
        for (i, c) in qm.cells.iter().enumerate() {
            let x = ox + i as i32 % qm.w;
            let y = oy + i as i32 / qm.w;
            map.set_terrain(x, y, c.t);
            map.lit[Map::idx(x, y)] = c.l;
        }
        for m in &qm.monsters {
            if let Some(d) = gd.monster_by_id(m.def) {
                let friendly = m.def == 1042; // Thrain himself
                if friendly {
                    plot.thrain_pos = Some((m.x + ox, m.y + oy));
                }
                spawn_single(
                    commands,
                    gd,
                    tiles,
                    d,
                    m.x + ox,
                    m.y + oy,
                    friendly,
                    m.quest,
                    rng,
                );
            }
        }
        // q_thrain.cc gen hook: Thrain himself waits on the map's
        // FEAT_MARKER (the data map has no monster record for him).
        if let Some(d) = gd.monster_by_name("Thrain, the King Under the Mountain") {
            let (mx, my) = (qm.marker.0 + ox, qm.marker.1 + oy);
            plot.thrain_pos = Some((mx, my));
            spawn_single(commands, gd, tiles, d, mx, my, true, true, rng);
        }
        // `M:` mimic cells display another feature until somone steps on
        // one of them (q_thrain.cc: cave.mimic = 61 in the vault).
        for m in &qm.mimics {
            let (x, y) = (m.x + ox, m.y + oy);
            if Map::in_bounds(x, y) && m.t != map::T_NOTHING {
                map.mimic.insert(Map::idx(x, y), m.t);
            }
        }
        placed = true;
        break;
    }
    if placed {
        plot.set(PLOT_THRAIN, PLOT_TAKEN);
        log.add("You hear the screams of a tortured prisoner nearby!");
    }
}

/// Pick an out-of-depth quest monster (q_rand.cc): never breeders,
/// friends, nazgul, special-genes or exploding attackers; uniques only
/// for the princess-in-peril type 1.
fn roll_rand_monster(
    gd: &GameData,
    rl: u32,
    want_unique: bool,
    rng: &mut impl Rng,
) -> Option<usize> {
    // q_rand.cc initialize_random_quests: get_mon_num(rl+4+randint(6))
    // through the quest filter, keeping only monsters above
    // min(rl, RQ_LEVEL_CAP=49).
    let min_level = rl.min(49);
    let candidates: Vec<usize> = (0..gd.monster_base_count)
        .filter(|&i| {
            let d = &gd.monsters[i];
            d.depth > min_level
                && d.unique == want_unique
                && !d.has("SPECIAL_GENE")
                && !d.has("NEVER_GENE")
                && !d.has("JOKEANGBAND")
                && !d.has("PET")
                && !d.has("NAZGUL")
                && !d.has("GOOD")
                && !d.has("AQUATIC")
                && !d.has("WILD_ONLY")
                && !d.spells.iter().any(|s| s == "MULTIPLY")
                && !d.blows.iter().any(|b| b.method == "EXPLODE")
        })
        .collect();
    let level = rl + 4 + rng.gen_range(1..=6);
    get_mon_num_from(gd, level, &candidates, rng)
}

/// Build the level's pre-rolled random quest (q_rand.cc): a princess in
/// a glass room or a swordsman whose pack was stolen.
#[allow(clippy::too_many_arguments)]
fn apply_rand_quest(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &mut Map,
    rq: &RandQuest,
    start: (i32, i32),
    rng: &mut impl Rng,
    log: &mut MessageLog,
) -> Option<(i32, i32)> {
    let needed = rq.needed;
    let def = rq.def;
    if rq.princess {
        let Some(qm) = gd.quest_map(200 + needed as u32) else {
            return None;
        };
        // Stamp the princess room into the level.
        for _ in 0..200 {
            let ox = rng.gen_range(1..map::MAP_W - qm.w - 1);
            let oy = rng.gen_range(1..map::MAP_H - qm.h - 1);
            let fits = (0..qm.h)
                .all(|y| (0..qm.w).all(|x| map.terrain_at(ox + x, oy + y) == map::T_GRANITE));
            if !fits {
                continue;
            }
            for (i, c) in qm.cells.iter().enumerate() {
                let x = ox + i as i32 % qm.w;
                let y = oy + i as i32 / qm.w;
                map.set_terrain(x, y, c.t);
                map.lit[Map::idx(x, y)] = c.l;
            }
            let mut princess_pos = None;
            for m in &qm.monsters {
                if let Some(d) = gd.monster_by_id(m.def) {
                    let friendly = m.def == 969;
                    if friendly {
                        princess_pos = Some((m.x + ox, m.y + oy));
                    }
                    spawn_single(
                        commands,
                        gd,
                        tiles,
                        d,
                        m.x + ox,
                        m.y + oy,
                        friendly,
                        false,
                        rng,
                    );
                }
            }
            // The wanted monsters guard the marker cell.
            let (mx, my) = (qm.marker.0 + ox, qm.marker.1 + oy);
            for _ in 0..needed {
                spawn_near(
                    commands,
                    gd,
                    tiles,
                    map,
                    gd.monsters[def].id,
                    mx,
                    my,
                    true,
                    rng,
                );
            }
            // "Boost level feeling a bit - a la pits" (q_rand.cc:591).
            map.rating += 10;
            map.feeling = map::feeling_from_rating(map.rating, map.good_item);
            // quest_random_feeling_hook (q_rand.cc:466): the princess
            // shouts at the wanted race.
            log.add(format!(
                "You hear someone shouting: 'Leave me alone, stupid {}'",
                gd.monsters[def].name
            ));
            return princess_pos;
        }
        None
    } else {
        for _ in 0..needed {
            let id = gd.monsters[def].id;
            spawn_near(commands, gd, tiles, map, id, start.0, start.1, true, rng);
        }
        // quest_random_feeling_hook (q_rand.cc:460): the lost swordsman
        // names the thief race.
        log.add("A strange man wrapped in a dark cloak steps out of the shadows:");
        log.add(format!(
            "'Oh, please help me! A horrible {} stole my sword! I'm nothing without it.'",
            gd.monsters[def].name
        ));
        None
    }
}

/// The Wight-King's cursed rags (q_wight.cc:75): a Filthy Rag named
/// "of the Wight" with the fixed flag set plus SPELL/pval 6 or MANA/pval 2
/// (randint(2)).  The King carries them from spawn; they fall on death.
fn wight_king_rags(gd: &GameData, rng: &mut impl Rng) -> Option<item::Item> {
    let def = gd.object_by_name("Filthy Rag")?;
    let mut rags = item::Item::base(gd, def);
    rags.identified = true;
    rags.artifact_name = "of the Wight".to_string();
    rags.cursed = true;
    for f in [
        "INT",
        "RES_BLIND",
        "SENS_FIRE",
        "RES_CONF",
        "IGNORE_ACID",
        "IGNORE_ELEC",
        "IGNORE_FIRE",
        "IGNORE_COLD",
        "SEE_INVIS",
        "HEAVY_CURSE",
    ] {
        rags.flags.push(f.to_string());
    }
    if crate::rng::randint(2, rng) == 1 {
        rags.flags.push("SPELL".to_string());
        rags.pval = 6;
    } else {
        rags.flags.push("MANA".to_string());
        rags.pval = 2;
    }
    Some(rags)
}

/// `quest_one_gen_hook` (q_one.cc:373): while the One Ring quest is under
/// way, Sauron is force-spawned on Angband's depth 99 regardless of the
/// normal unique roll, carrying MFLAG_QUEST.  Returns true when he was
/// placed.
pub fn quest_one_gen_hook(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    depth: u32,
    dungeon: u32,
    plot: &PlotQuest,
    rng: &mut impl Rng,
) -> bool {
    if plot.status(PLOT_ONE) != PLOT_TAKEN
        || dungeon != crate::base_defs::DUNGEON_ANGBAND as u32
        || depth != 99
    {
        return false;
    }
    let Some(def) = gd.monster_by_name("Sauron, the Sorcerer") else {
        return false;
    };
    // "Find a good position": randint(cur_hgt-4)+2 / randint(cur_wid-4)+2,
    // up to 10000 tries (cave_empty_bold).
    let mut spot = None;
    for _ in 0..10000 {
        let x = crate::rng::randint(map::MAP_W - 4, rng) + 2;
        let y = crate::rng::randint(map::MAP_H - 4, rng) + 2;
        if map.walkable(gd, x, y) {
            spot = Some((x, y));
            break;
        }
    }
    let Some((x, y)) = spot else {
        return false;
    };
    spawn_single(commands, gd, tiles, def, x, y, false, true, rng);
    true
}

/// Shared post-generation content for a freshly entered level
/// (setup_level / level_transition): town NPCs, dungeon monsters and
/// objects, the quest unique, the lost hobbit, the Thrain vault,
/// random quests and the god's relic.
#[allow(clippy::too_many_arguments)]
pub fn populate_level(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &mut Map,
    vault: &map::VaultSpawns,
    depth: u32,
    dungeon: u32,
    start: (i32, i32),
    created: &mut HashSet<u32>,
    inv: &mut Inventory,
    plot: &mut PlotQuest,
    ps: &mut PlayerState,
    rng: &mut impl Rng,
    log: &mut MessageLog,
) {
    // The Lost Temple uses the god's runtime attributes (q_god.cc
    // set_god_dungeon_attributes), not the static d_info record.
    let temple_def;
    let dinfo = if ps.dungeon == DUNGEON_GOD {
        temple_def = god_temple_def(gd, ps);
        &temple_def
    } else {
        gd.dungeon(dungeon)
    };
    // ADJUST_LEVEL (monster2.cc:2432) applies to every monster placed in
    // the dungeon, vault contents and quest spawns included.
    let adjust = if depth > 0 {
        dungeon_adjust_level(dinfo, depth)
    } else {
        None
    };
    // Vault contents (v_info; the original places these in build_vault).
    for &(def, x, y, level) in &vault.monsters {
        spawn_one_monster(commands, gd, tiles, map, def, x, y, level, adjust, rng);
    }
    // Single spawns with no ego or companions (dungeon town townspeople).
    for &(def, x, y) in &vault.singles {
        spawn_single(commands, gd, tiles, def, x, y, false, false, rng);
    }
    // Monster nests and pits (generate.cc build_type5/6).
    for nest in &vault.nests {
        let cands: Vec<usize> = (0..gd.monster_base_count)
            .filter(|&i| {
                let m = &gd.monsters[i];
                !m.unique && m.depth >= 1 && m.depth <= depth + 5 && nest_theme_ok(m, &nest.theme)
            })
            .collect();
        if cands.is_empty() {
            continue;
        }
        let mut cells = nest.cells.clone();
        cells.shuffle(rng);
        for &(x, y) in cells.iter().take(nest.count) {
            let def = cands[rng.gen_range(0..cands.len())];
            spawn_single(commands, gd, tiles, def, x, y, false, false, rng);
        }
    }
    // place_object uses the dungeon's O: theme (d_info objs).
    let theme = dinfo.theme;
    for &(level, x, y, good) in &vault.objects {
        let Some(mut it) = item::make_object_themed(gd, level, good, false, theme, created, rng)
        else {
            continue;
        };
        // place_object(y, x, good, false, OBJ_FOUND_VAULT).
        let (r, g) = item::rating_of(gd, &it, level);
        map.rating += r;
        map.good_item |= g;
        it.found = item::OBJ_FOUND_VAULT;
        it.found_aux1 = dungeon as i32;
        it.found_aux2 = level_or_feat(map, ps, x, y);
        let od = &gd.objects[it.def];
        commands.spawn((
            item::FloorItem { stack: vec![it] },
            GameEntity,
            GridPos { x, y },
            render::glyph_sprite(tiles, od.glyph(), od.color),
            Transform::from_translation(render::grid_to_world(x, y, 1.5)),
            Visibility::Hidden,
        ));
    }
    if depth == 0 {
        if map.town != 0 {
            populate_town(commands, gd, tiles, map, plot, ps, rng, start);
        } else {
            populate_wilderness(commands, gd, tiles, map, plot, ps, rng, start);
        }
        return;
    }
    if depth >= PLOT_DEPTH_BASE {
        return; // quest levels are populated by build_quest_level
    }
    let d = dinfo;
    let special_level = d.special_at(depth).is_some();
    if !special_level {
        spawn_monsters(
            commands, gd, tiles, map, dungeon, depth, Some(dinfo), ps, plot, rng, start,
        );
    }
    let (scatter_rating, scatter_good) = item::scatter_objects(
        commands, gd, tiles, map, depth, dungeon, start, created, rng,
    );
    map.rating += scatter_rating;
    map.good_item |= scatter_good;
    map.feeling = map::feeling_from_rating(map.rating, map.good_item);
    // quest_one_gen_hook: the forced Sauron on Angband 99 (HOOK_LEVEL_END_GEN,
    // q_one.cc:373) runs after the ordinary monster/object generation.
    quest_one_gen_hook(commands, gd, tiles, map, depth, dungeon, plot, rng);
    // The lost hobbit (q_hobbit): Merton wanders the Maze (dungeon 18) at
    // his rolled level.
    if plot.status(PLOT_HOBBIT) == PLOT_TAKEN && plot.hobbit_depth == depth && ps.dungeon == 18 {
        if let Some(d) = gd.monster_by_name("Merton Proudfoot, the lost hobbit") {
            for _ in 0..100 {
                let x = rng.gen_range(1..map::MAP_W - 1);
                let y = rng.gen_range(1..map::MAP_H - 1);
                if map.walkable(gd, x, y) && map::chebyshev(x, y, start.0, start.1) > 15 {
                    spawn_single(commands, gd, tiles, d, x, y, true, false, rng);
                    break;
                }
            }
        }
    }
    // The prisoner of Dol Guldur (q_thrain): rolled for one random depth
    // of that dungeon (mindepth+1 .. maxdepth-1) and embedded there; the
    // torture cries reveal it (q_thrain.cc feeling hook).
    if plot.status(PLOT_THRAIN) == PLOT_UNTAKEN && ps.dungeon == 23 {
        if plot.thrain_depth == 0 {
            plot.thrain_depth = rng.gen_range(58..=69);
        }
        if depth == plot.thrain_depth {
            plot.set(PLOT_THRAIN, PLOT_TAKEN);
            log.add("You hear someone shouting under the torture.");
            embed_thrain(commands, gd, tiles, map, plot, rng, log);
        }
    }
    // Random quests (q_rand.cc): pre-rolled at birth for this depth, and
    // only in the principal dungeon that hosts them.
    if let Some(rq) = plot
        .rands
        .get(&depth)
        .filter(|rq| rq.dungeon == 0 || rq.dungeon == ps.dungeon)
        .cloned()
    {
        // A freshly generated level resets the kill counter
        // (q_rand.cc quest_random_turn_hook).
        if let Some(r) = plot.rands.get_mut(&depth) {
            r.got = 0;
        }
        let princess_pos = apply_rand_quest(commands, gd, tiles, map, &rq, start, rng, log);
        if let Some(r) = plot.rands.get_mut(&depth) {
            r.princess_pos = princess_pos;
        }
    }
    // The god's lost relic (q_god.cc quest_god_level_end_gen_hook): only
    // the Lost Temple's levels can hold it, 20% each, forced on the fifth.
    if ps.dungeon == DUNGEON_GOD
        && ps.relic_quest
        && ps.relic_depth == 0
        && depth > 0
        && depth < PLOT_DEPTH_BASE
    {
        if ps.relic_tries >= 4 || rng.gen_bool(0.2) {
            ps.relic_depth = depth;
        } else {
            ps.relic_tries += 1;
        }
    }
    // The relic lies somewhere on its level (per-deity relic piece).
    // quest_god_generate_relic (q_god.cc:369-430): 1000 tries for any
    // floor grid that is not permanent; if none is found the relic goes
    // into the pack ("you stumble across the relic on the stairs").
    if ps.relic_depth == depth {
        let relic = format!("Piece of the Relic of {}", crate::spell::god_name(ps.god));
        if let Some(def) = gd.object_by_name(&relic) {
            let mut spot = None;
            for _ in 0..1000 {
                let x = rng.gen_range(1..map.w - 1);
                let y = rng.gen_range(1..map.h - 1);
                let td = gd.terrain(map.terrain_at(x, y));
                if td.is_floor && !td.permanent {
                    spot = Some((x, y));
                    break;
                }
            }
            let mut it = item::Item::base(gd, def);
            it.inscription = "quest".to_string();
            let drop_at = |commands: &mut Commands, it: item::Item, x: i32, y: i32| {
                let od = &gd.objects[it.def];
                commands.spawn((
                    item::FloorItem { stack: vec![it] },
                    GameEntity,
                    GridPos { x, y },
                    render::glyph_sprite(tiles, od.glyph(), od.color),
                    Transform::from_translation(render::grid_to_world(x, y, 1.5)),
                    Visibility::Hidden,
                ));
            };
            match spot {
                Some((x, y)) => {
                    drop_at(commands, it, x, y);
                    log.add("Your god whispers: the relic lies on this level.");
                }
                None => {
                    log.add("You luckily stumble across the relic on the stairs!");
                    if inv.pack.len() < 23 || inv.merge_target(gd, &it).is_some() {
                        inv.add_with(gd, it);
                    } else {
                        // inven_carry_okay refused: drop it at the player.
                        drop_at(commands, it, start.0, start.1);
                    }
                }
            }
        }
    }
    // Prophecies that fire on this level (generate.cc "Check fates").
    spawn_fates(
        commands, gd, tiles, map, depth, adjust, created, ps, start, rng, log,
    );
    // The dungeon's final guardian waits on its deepest level and holds
    // the final artifact/object (generate.cc).
    if depth == d.maxdepth {
        spawn_guardian(commands, gd, tiles, map, dungeon, created, plot, rng, start, log);
    }
}

/// Place the fated object/monster/artifact within ten grids of the player
/// start (generate.cc:7544 get_pos_player).
#[allow(clippy::too_many_arguments)]
fn spawn_fates(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    depth: u32,
    adjust: Option<(u32, u32)>,
    created: &mut HashSet<u32>,
    ps: &mut PlayerState,
    start: (i32, i32),
    rng: &mut impl Rng,
    log: &mut MessageLog,
) {
    let mut fired: Vec<usize> = Vec::new();
    for (i, f) in ps.fates.iter().enumerate() {
        if f.fate == 0 || f.level != depth {
            continue;
        }
        if !f.serious && rng.gen_range(0..2) == 0 {
            continue;
        }
        let mut spot = None;
        for _ in 0..200 {
            let (x, y) = (
                start.0 + rng.gen_range(-10..=10),
                start.1 + rng.gen_range(-10..=10),
            );
            if Map::in_bounds(x, y) && map.walkable(gd, x, y) && !map::is_door(map.terrain_at(x, y))
            {
                spot = Some((x, y));
                break;
            }
        }
        let Some((x, y)) = spot else { continue };
        let drop = |commands: &mut Commands, it: item::Item| {
            let od = &gd.objects[it.def];
            commands.spawn((
                item::FloorItem { stack: vec![it] },
                GameEntity,
                GridPos { x, y },
                render::glyph_sprite(tiles, od.glyph(), od.color),
                Transform::from_translation(render::grid_to_world(x, y, 1.5)),
                Visibility::Hidden,
            ));
        };
        match f.fate {
            FATE_FIND_O => {
                if f.object as usize >= gd.objects.len() {
                    fired.push(i);
                    continue;
                }
                let it = item::make_item(gd, f.object as usize, depth, true, created, rng);
                log.add("A fateful treasure lies nearby!");
                drop(commands, it);
                fired.push(i);
            }
            FATE_FIND_R => {
                if f.monster as usize >= gd.monster_base_count {
                    fired.push(i);
                    continue;
                }
                spawn_one_monster(commands, gd, tiles, map, f.monster as usize, x, y, 0, adjust, rng);
                log.add("A figure from your prophecy appears!");
                fired.push(i);
            }
            FATE_FIND_A => {
                let it = if f.artifact == 0 {
                    // generate.cc:7601: allocate with kind_is_artifactable
                    // at max_dlv[dungeon_type] + randint(10).
                    let obj_lev = ps.max_depth.max(1) + rng.gen_range(1..=10);
                    let mut kind = None;
                    for _ in 0..100 {
                        let Some(k) = crate::item::gen_object_kind(gd, obj_lev, rng) else {
                            break;
                        };
                        if item::kind_is_artifactable(gd, k) {
                            kind = Some(k);
                            break;
                        }
                    }
                    kind.map(|k| {
                        let mut item = item::Item::base(gd, k);
                        item::create_artifact(gd, &mut item, depth, false, "", rng);
                        item
                    })
                } else {
                    item::make_specific_artifact(gd, f.artifact, created, rng)
                };
                if let Some(it) = it {
                    log.add("A legendary treasure appears!");
                    drop(commands, it);
                }
                fired.push(i);
            }
            _ => {}
        }
    }
    for i in fired.into_iter().rev() {
        ps.fates.remove(i);
    }
}

/// Whether a wilderness monster fits the terrain kind of an area
/// (reset_get_monster_hook, src/monster1.cc).
fn wild_monster_ok(idx: usize, gd: &GameData, terrain_idx: u32) -> bool {
    let def = &gd.monsters[idx];
    match terrain_idx {
        1 => def.has("WILD_TOWN"),
        2 => def.has("WILD_OCEAN"),
        3 => def.has("WILD_SHORE"),
        5 => def.has("WILD_WASTE"),
        6 => def.has("WILD_GRASS"),
        7 => def.has("WILD_WOOD"),
        9 | 10 => def.has("WILD_VOLCANO"),
        11 => def.has("WILD_MOUNTAIN"),
        _ => !def.has("WILD_ONLY"),
    }
}

/// The surface residents: WILD_*-filtered monsters for the area's terrain
/// (wilderness_gen), or the 60-strong ambush party when the player was
/// caught in the open.
fn populate_surface(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    rng: &mut impl Rng,
    start: (i32, i32),
) {
    let wf = gd.wf(map.wf);
    let level = wf.level.max(1);
    // The resident count is clamped to the area's floor grids minus one
    // (wild.cc generate_area / wilderness_gen: lim > hack_floor - 1).
    let floor_count = (0..map.h)
        .flat_map(|y| (0..map.w).map(move |x| (x, y)))
        .filter(|&(x, y)| map.walkable(gd, x, y))
        .count() as i32;
    let mut count = if map.encounter { 60 } else { 8 };
    if count > floor_count - 1 {
        count = (floor_count - 1).max(0);
    }
    let candidates: Vec<usize> = (0..gd.monster_base_count)
        .filter(|&i| {
            let d = &gd.monsters[i];
            d.depth <= level + 2 && !d.unique && wild_monster_ok(i, gd, wf.terrain_idx)
        })
        .collect();
    if candidates.is_empty() {
        return;
    }
    let weights: Vec<u32> = candidates
        .iter()
        .map(|&i| (10 / gd.monsters[i].rarity).max(1))
        .collect();
    let Ok(dist) = WeightedIndex::new(&weights) else {
        return;
    };
    let mut placed = 0;
    let mut tries = 0;
    while placed < count && tries < 1500 {
        tries += 1;
        let x = rng.gen_range(1..map::MAP_W - 1);
        let y = rng.gen_range(1..map::MAP_H - 1);
        if !map.walkable(gd, x, y) || map::chebyshev(x, y, start.0, start.1) < 6 {
            continue;
        }
        spawn_one_monster(
            commands,
            gd,
            tiles,
            map,
            candidates[dist.sample(rng)],
            x,
            y,
            level,
            None,
            rng,
        );
        placed += 1;
    }
}

/// Place a friendly quest NPC somewhere far from the player's entry point.
fn place_npc(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    name: &str,
    friendly: bool,
    quest: bool,
    rng: &mut impl Rng,
    start: (i32, i32),
) {
    let Some(def) = gd.monster_by_name(name) else {
        return;
    };
    for _ in 0..300 {
        let x = rng.gen_range(1..map::MAP_W - 1);
        let y = rng.gen_range(1..map::MAP_H - 1);
        if map.walkable(gd, x, y) && map::chebyshev(x, y, start.0, start.1) > 10 {
            spawn_single(commands, gd, tiles, def, x, y, friendly, quest, rng);
            return;
        }
    }
}

/// A town level: the plot NPCs (q_shroom/q_hobbit/q_nazgul town_gen
/// hooks).  The town's residents come from `place_townspeople` in the
/// level generator (1% per free grid, `t` monsters); the original has no
/// MIN_M_ALLOC_TN resident pass on a town level.
fn populate_town(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    plot: &PlotQuest,
    ps: &PlayerState,
    rng: &mut impl Rng,
    start: (i32, i32),
) {
    if map.town != 1 {
        return;
    }
    let day = is_daytime(ps.turn);
    if day && plot.status(PLOT_SHROOM) <= PLOT_COMPLETED {
        place_npc(
            commands,
            gd,
            tiles,
            map,
            "Farmer Maggot",
            true,
            false,
            rng,
            start,
        );
    }
    // Melinda only appears ten days after the quest was initialised
    // (q_hobbit.cc town_gen hook: turn >= data[1] + DAY*10); once the
    // quest is under way she stays in Bree.
    if day
        && plot.status(PLOT_HOBBIT) <= PLOT_COMPLETED
        && (plot.status(PLOT_HOBBIT) != PLOT_UNTAKEN
            || ps.turn >= plot.hobbit_turn + 10 * TURNS_PER_DAY)
    {
        place_npc(
            commands,
            gd,
            tiles,
            map,
            "Melinda Proudfoot",
            true,
            false,
            rng,
            start,
        );
    }
    if plot.status(PLOT_NAZGUL) == PLOT_TAKEN {
        place_npc(
            commands,
            gd,
            tiles,
            map,
            "Uvatha the Horseman",
            false,
            true,
            rng,
            start,
        );
    }
}

/// A non-town wilderness area: its residents plus the plot hooks that
/// live in the wild (Maggot's field, the poisoned pond).
#[allow(clippy::too_many_arguments)]
fn populate_wilderness(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    plot: &mut PlotQuest,
    ps: &PlayerState,
    rng: &mut impl Rng,
    start: (i32, i32),
) {
    populate_surface(commands, gd, tiles, map, rng, start);
    // Maggot's field (q_shroom.cc): mushrooms and three quest dogs.
    if map.wild == (33, 21) {
        let (cx, cy) = (map::MAP_W / 2, map::MAP_H / 2);
        let shrooms: Vec<usize> = (0..gd.objects.len())
            .filter(|&i| {
                let o = &gd.objects[i];
                o.tval == crate::data::TV_FOOD && (0..=19).contains(&o.sval)
            })
            .collect();
        // q_shroom.cc town_gen hook: data[1] - data[0] mushrooms (the
        // birth/init roll fills shrooms_needed before the first visit).
        let count = plot.shrooms_needed.max(1);
        let mut used: HashSet<(i32, i32)> = HashSet::new();
        for _ in 0..count {
            if shrooms.is_empty() {
                break;
            }
            for _ in 0..50 {
                let (x, y) = (cx + rng.gen_range(-7..=7), cy + rng.gen_range(-5..=5));
                if used.insert((x, y)) && map.walkable(gd, x, y) {
                    let def = shrooms[rng.gen_range(0..shrooms.len())];
                    let it = item::Item::base(gd, def);
                    let o = &gd.objects[def];
                    commands.spawn((
                        item::FloorItem { stack: vec![it] },
                        GameEntity,
                        GridPos { x, y },
                        render::glyph_sprite(tiles, o.glyph(), o.color),
                        Transform::from_translation(render::grid_to_world(x, y, 1.5)),
                        Visibility::Hidden,
                    ));
                    break;
                }
            }
        }
        for name in [
            "Grip, Farmer Maggot's dog",
            "Wolf, Farmer Maggot's dog",
            "Fang, Farmer Maggot's dog",
        ] {
            if let Some(def) = gd.monster_by_name(name) {
                for _ in 0..50 {
                    let (x, y) = (cx + rng.gen_range(-7..=7), cy + rng.gen_range(-5..=5));
                    if used.insert((x, y)) && map.walkable(gd, x, y) {
                        // MSTATUS_ENEMY + MFLAG_QUEST (q_shroom.cc).
                        spawn_flagged(commands, gd, tiles, def, x, y, false, true, false, rng);
                        break;
                    }
                }
            }
        }
    }
    // The poisoned pond's beasts (q_poison.cc quest_poison_gen_hook).
    if plot.status(PLOT_POISON) == PLOT_TAKEN && plot.poison_cell == Some(map.wild) {
        let (cy, cx) = (
            rng.gen_range(22..map::MAP_H - 22),
            rng.gen_range(32..map::MAP_W - 32),
        );
        let molds: Vec<usize> = (0..gd.monster_base_count)
            .filter(|&i| {
                let d = &gd.monsters[i];
                matches!(d.glyph(), 'm' | ',' | 'e')
                    && !d.unique
                    && !d.has("MULTIPLY")
                    && d.depth >= 1
                    && d.depth <= 30
            })
            .collect();
        if !molds.is_empty() {
            let mut placed = 0;
            let mut tries = 0;
            while placed < 40 && tries < 2000 {
                tries += 1;
                let x = cx + rng.gen_range(-10..=10);
                let y = cy + rng.gen_range(-10..=10);
                if Map::in_bounds(x, y) && map.walkable(gd, x, y) && rng.gen_bool(0.6) {
                    let def = molds[rng.gen_range(0..molds.len())];
                    // 80% chance to raise a low mold up towards the
                    // player's level (q_poison.cc:132).
                    let base = gd.monsters[def].depth.max(1) as i32;
                    let level = if rng.gen_bool(0.8) && base < ps.level as i32 {
                        base + rng.gen_range(1..=(ps.level as i32 - base))
                    } else {
                        0
                    };
                    spawn_flagged_held(
                        commands, gd, tiles, def, x, y, false, true, false, None, None, None,
                        level, 0, false, false, rng,
                    );
                    placed += 1;
                }
            }
        }
    }
}

/// Spawn the dungeon's FINAL_GUARDIAN on its deepest level; it holds the
/// dungeon's final artifact/object until slain.
#[allow(clippy::too_many_arguments)]
fn spawn_guardian(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    dungeon: u32,
    created: &mut HashSet<u32>,
    plot: &PlotQuest,
    rng: &mut impl Rng,
    start: (i32, i32),
    log: &mut MessageLog,
) {
    let d = gd.dungeon(dungeon);
    let Some(guardian) = d.guardian else {
        return;
    };
    let Some(def) = gd.monster_by_id(guardian) else {
        return;
    };
    // quest_main_monsters_hook: the guardian waits for its predecessor.
    if main_quest_blocks(&gd.monsters[def].name, plot) {
        return;
    }
    // Find a spot away from the entrance.
    let mut spot = None;
    for _ in 0..10000 {
        let x = rng.gen_range(1..map::MAP_W - 1);
        let y = rng.gen_range(1..map::MAP_H - 1);
        if map.walkable(gd, x, y) && map::chebyshev(x, y, start.0, start.1) > 10 {
            spot = Some((x, y));
            break;
        }
    }
    let Some((x, y)) = spot else { return };
    let mut held_artifact = None;
    if let Some(aid) = d.final_artifact {
        if item::make_specific_artifact(gd, aid, created, rng).is_some() {
            held_artifact = Some(aid);
        }
    }
    let mut held_object = None;
    if let Some(oid) = d.final_object {
        if gd.object_by_id(oid).is_some() {
            held_object = Some(oid);
        }
    }
    spawn_flagged_held(
        commands,
        gd,
        tiles,
        def,
        x,
        y,
        false,
        false,
        false,
        held_artifact,
        held_object,
        None,
        0,
        0,
        false,
        false,
        rng,
    );
    log.add(format!(
        "You sense the presence of {}!",
        gd.monsters[def].name
    ));
}

/// Roll a random quest for this level (q_rand.cc): either a princess

/// NO_DEATH monsters cannot be killed (xtra2.cc mon_take_hit): they
/// survive at 1 hp whatever hits them.
pub fn clamp_no_death(gd: &GameData, m: &mut Monster) {
    if gd.monsters[m.def].has("NO_DEATH") && m.hp < 1 {
        m.hp = 1;
    }
}

/// ai_deincarnate (monster3.cc:247): a POSSESSOR soul whose borrowed
/// body died reverts to its own race at full health instead of dying.
/// Returns true when the monster was deincarnated (the caller must not
/// kill it).
pub fn deincarnate_monster(
    gd: &GameData,
    m: &mut Monster,
    extra: Option<&mut MonsterExtra>,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) -> bool {
    let Some(back) = m.possessor else {
        return false;
    };
    if m.seen {
        log.add(format!(
            "The soul of the {} deincarnates!",
            gd.monsters[m.def].name
        ));
    }
    m.def = back;
    m.possessor = None;
    // "No damage yet": reset the transient combat state.
    m.stun = 0;
    m.confused = 0;
    m.fear = 0;
    m.cut = 0;
    m.poison = 0;
    m.target = None;
    m.awake = true;
    m.mon_level = 0;
    m.mspeed_mod = 0;
    m.max_hp = roll_monster_hp(&gd.monsters[back], rng);
    m.hp = m.max_hp;
    m.energy = 0;
    if let Some(x) = extra {
        x.exp = monster_exp(gd.monsters[back].depth.max(1) as i32);
        x.partial = false;
    }
    true
}

/// Slay a monster: message, despawn, quest checks, loot, experience.
#[allow(clippy::too_many_arguments)]
pub fn kill_monster(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    stacks: &mut Query<
        (Entity, &GridPos, &mut item::FloorItem),
        impl bevy::ecs::query::QueryFilter,
    >,
    e: Entity,
    def_idx: usize,
    pos: (i32, i32),
    held_artifact: Option<u32>,
    held_object: Option<u32>,
    held_items: Vec<item::Item>,
    held_gold: i32,
    looted: bool,
    ps: &mut PlayerState,
    plot: &mut PlotQuest,
    map: &mut Map,
    quest_left: i32,
    enemy_left: i32,
    created: &mut HashSet<u32>,
    inv: &mut Inventory,
    log: &mut MessageLog,
    rng: &mut impl Rng,
    by_companion: bool,
) {
    kill_monster_with_note(
        commands,
        gd,
        tiles,
        stacks,
        e,
        def_idx,
        pos,
        held_artifact,
        held_object,
        held_items,
        held_gold,
        looted,
        ps,
        plot,
        map,
        quest_left,
        enemy_left,
        created,
        inv,
        log,
        rng,
        by_companion,
        None,
    )
}

/// curse_equipment_dg (melee2.cc:2377): a random worn slot is cursed
/// with DG_CURSE (and, for artifacts, HEAVY_CURSE) unless a blessed item
/// resists.  Used by dying RF_DG_CURSE monsters.
fn curse_equipment_dg(
    gd: &GameData,
    inv: &mut Inventory,
    chance: i32,
    heavy_chance: i32,
    log: &mut MessageLog,
    rng: &mut impl Rng,
) {
    if rng.gen_range(0..100) > chance {
        return;
    }
    let slot = rng.gen_range(0..crate::data::NUM_SLOTS);
    let Some(it) = inv.equip[slot].as_mut() else {
        return;
    };
    let flags = item::item_flags(gd, it);
    let has = |f: &str| flags.iter().any(|x| *x == f);
    if has("BLESSED") && rng.gen_range(1..=888) > chance {
        let label = it.label(gd, &inv.known);
        log.add(format!(
            "Your {} resist{} cursing!",
            label,
            if it.count > 1 { "" } else { "s" }
        ));
        return;
    }
    let mut changed = false;
    let is_artifact = it.artifact != 0 || !it.artifact_name.is_empty() || it.ego != 0;
    if rng.gen_range(0..100) <= heavy_chance && is_artifact {
        if !has("HEAVY_CURSE") {
            changed = true;
        }
        for f in ["HEAVY_CURSE", "CURSED", "DG_CURSE"] {
            if !it.flags.iter().any(|x| x == f) {
                it.flags.push(f.to_string());
            }
        }
    } else {
        if !has("CURSED") {
            changed = true;
        }
        for f in ["CURSED", "DG_CURSE"] {
            if !it.flags.iter().any(|x| x == f) {
                it.flags.push(f.to_string());
            }
        }
    }
    it.cursed = true;
    if changed {
        log.add("There is a malignant black aura surrounding you...");
        if it.inscription == "uncursed" {
            it.inscription.clear();
        }
    }
}

/// place_corpse's hp value (xtra2.cc:2131): (maxroll + player mhp)/2
/// minus a random third, carried on the corpse as pval3 so resurrection
/// and raising restore the original vitality.
fn corpse_hp(def: &crate::data::MonsterDef, ps: &PlayerState, rng: &mut impl Rng) -> i32 {
    let maxroll = crate::data::Dice::parse(&def.hp)
        .map(|d| d.count * d.sides)
        .unwrap_or(1)
        .max(1);
    let mut p3 = (maxroll + ps.max_hp) / 2;
    p3 -= rng.gen_range(1..=p3.max(1)) / 3;
    p3.max(1)
}

/// level_or_feat (defines.hpp): the dungeon depth, or the terrain of the
/// wilderness cell on the surface (Object.found_aux4).
fn level_or_feat(map: &Map, ps: &PlayerState, x: i32, y: i32) -> i32 {
    if ps.depth == 0 {
        map.terrain_at(x, y) as i32
    } else {
        ps.depth as i32
    }
}

/// Slay a monster with a custom death line (mon_take_hit_mon's
/// " is destroyed."/" is killed." messages); None keeps "The X dies.".
#[allow(clippy::too_many_arguments)]
pub fn kill_monster_with_note(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    stacks: &mut Query<
        (Entity, &GridPos, &mut item::FloorItem),
        impl bevy::ecs::query::QueryFilter,
    >,
    e: Entity,
    def_idx: usize,
    pos: (i32, i32),
    held_artifact: Option<u32>,
    held_object: Option<u32>,
    held_items: Vec<item::Item>,
    held_gold: i32,
    looted: bool,
    ps: &mut PlayerState,
    plot: &mut PlotQuest,
    map: &mut Map,
    quest_left: i32,
    enemy_left: i32,
    created: &mut HashSet<u32>,
    inv: &mut Inventory,
    log: &mut MessageLog,
    rng: &mut impl Rng,
    by_companion: bool,
    death_message: Option<String>,
) {
    let def = &gd.monsters[def_idx];
    // The type-identification set drives the breakage/decompose prose;
    // no monster occupies the scatter cells at this point (the corpse was
    // just removed), so the artifact bounce gets an empty occupied set.
    let known = inv.known.clone();
    let occupied: HashSet<(i32, i32)> = HashSet::new();
    *ps.kills.entry(def_idx as u32).or_insert(0) += 1;
    // A slain unique stays dead (melee2.cc: "When an Unique dies, it
    // stays dead": max_num = 0, so get_mon_num skips it forever).
    if def.unique {
        ps.unique_seen.insert(def_idx);
    }
    let dead_name = killed_monster_desc(gd, ps, def_idx, rng);
    match death_message {
        // An empty line means the death was not witnessed (mon_take_hit_mon).
        Some(m) if m.is_empty() => {}
        Some(m) => log.add(m),
        None => log.add(format!("{} dies.", cap_first(&dead_name))),
    }
    // A dying CAN_SPEAK monster has last words (xtra2.cc).
    if def.has("CAN_SPEAK") {
        if let Some(line) = crate::speech::death_line(rng) {
            log.add(format!("{} says: {}", cap_first(&dead_name), line));
        }
    }
    // A dying Morgoth-cursed monster may curse the player's gear
    // (xtra2.cc mon_take_hit RF_DG_CURSE).
    if def.has("DG_CURSE") && rng.gen_range(1..=2) == 1 {
        log.add(format!(
            "{} puts a terrible Morgothian curse on you!",
            cap_first(&dead_name)
        ));
        curse_equipment_dg(gd, inv, 100, 50, log, rng);
    }
    // Kill experience (xtra2.cc mon_take_hit): mexp * monster_level /
    // max_plv, with the fractional remainder carried in exp_frac.
    let mon_level = def.depth.max(1) as u64;
    let div = ps.max_plv.max(ps.level).max(1) as u64;
    let (exp, frac) = kill_experience(def, ps);
    ps.exp_frac = frac;
    // LEVELS artifacts (Narthanc & co.) grow with every kill
    // (xtra2.cc: mexp * monster_level / (2 * max player level)).
    if !by_companion {
        let gain = (def.exp as u64 * mon_level) / (div * 2);
        for i in 0..crate::data::NUM_SLOTS {
            let Some(it) = inv.equip[i].as_mut() else {
                continue;
            };
            if !item::item_flags(gd, it).iter().any(|f| *f == "LEVELS") {
                continue;
            }
            it.mon_exp = it.mon_exp.saturating_add(gain as u32);
            // calc_object_need_exp: player_exp[elevel-1] * 5 / 2
            // (object1.cc:683), capped at PY_MAX_LEVEL (50).
            loop {
                let idx = (it.elevel as usize).clamp(1, 50) - 1;
                let need = PLAYER_EXP[idx] * 5 / 2;
                if it.elevel >= 50 || (it.mon_exp as u64) < need {
                    break;
                }
                it.mon_exp = (it.mon_exp as u64 - need) as u32;
                it.elevel += 1;
                // object_gain_level (object1.cc:5595): weapon plusses,
                // realm groups and realm flags.
                let tval = gd.objects[it.def].tval;
                if matches!(
                    tval,
                    crate::data::TV_AXE
                        | crate::data::TV_SWORD
                        | crate::data::TV_POLEARM
                        | crate::data::TV_HAFTED
                        | crate::data::TV_MSTAFF
                ) {
                    let roll = rng.gen_range(0..100);
                    if roll < 33 {
                        it.to_h += rng.gen_range(1..=2);
                        it.to_d += 1;
                    } else if roll < 66 {
                        it.to_h += 1;
                        it.pval2 += 1;
                        // NEW_GROUP_CHANCE = 40.
                        if rng.gen_range(0..100) < 40 {
                            gain_flag_group(gd, it, &inv.known, rng, log);
                        }
                    } else {
                        if it.pval3 == 0 {
                            gain_flag_group(gd, it, &inv.known, rng, log);
                        }
                        gain_flag_group_flag(gd, it, &inv.known, rng, log);
                        if it.pval == 0 {
                            it.pval = 1;
                        } else {
                            while it.pval < 10 && rng.gen_range(0..100) < 20 - it.pval * 2 {
                                it.pval += 1;
                            }
                            if it.pval > 5 {
                                it.pval = 5;
                            }
                        }
                    }
                }
                log.add(format!(
                    "{} gains a level! (level {})",
                    it.label(gd, &inv.known),
                    it.elevel
                ));
            }
        }
    }
    // q_main.cc quest_sauron_resurrect_hook: while Sauron is not
    // permanently dead (the Ring neither destroyed nor worn) a slain
    // Nazgul is only scattered, never destroyed — its max_num is reset to
    // 1 so it can be generated again.
    if def.has("NAZGUL") && !(ps.ring_destroyed || ps.ring_worn) {
        log.add(format!(
            "Somehow you feel {} is not totally destroyed...",
            if def.has("FEMALE") { "she" } else { "he" }
        ));
        ps.unique_seen.remove(&def_idx);
    }
    // Sauron himself is not permanently defeated while the One Ring is
    // neither destroyed nor used (q_main.cc:184): max_num = 1 again.
    // The message lives in check_main_quest_kill (the main plot).
    if def.name == "Sauron, the Sorcerer" && !(ps.ring_destroyed || ps.ring_worn) {
        ps.unique_seen.remove(&def_idx);
    }
    // The One Ring (q_one.cc quest_one_death_hook): once Galadriel's
    // warning is given and the Ring does not yet exist, its bearers may
    // drop it — Sauron 30%, the others 10% each.
    if plot.one_taken && !plot.ring_spawned {
        let chance = match def.name.as_str() {
            "Sauron, the Sorcerer" => 30,
            "Ar-Pharazon the Golden"
            | "Shelob, Spider of Darkness"
            | "The Watcher in the Water"
            | "Glaurung, Father of the Dragons"
            | "Feagwath, the Undead Sorcerer" => 10,
            _ => 0,
        };
        if chance > 0 && rng.gen_range(0..100) < chance {
            plot.ring_spawned = true;
            // The real artifact (a_info 13, TV_RING sval 37); it slips
            // straight into the pack (q_one.cc inven_carry), a full pack
            // pushing its last item out.
            if let Some(ring) = item::make_specific_artifact(gd, 13, created, rng) {
                log.add("You feel the urge to pick up that plain gold ring you see.");
                if inv.pack.len() >= 23 {
                    if let Some(last) = inv.pack.pop() {
                        item::place_floor_item(commands, gd, tiles, stacks, pos.0, pos.1, last);
                    }
                }
                inv.add_with(gd, ring);
            }
        }
    }
    commands.entity(e).despawn();
    // q_troll.cc ambush: the first non-Tom troll death springs the hidden
    // 'H' cells of the glade (terrain 96), spawning forest/stone trolls.
    if ps.depth == PLOT_DEPTH_BASE + PLOT_TROLL
        && plot.status(PLOT_TROLL) == PLOT_TAKEN
        && !plot.troll_ambush
        && def.name != "Tom the Stone Troll"
    {
        plot.troll_ambush = true;
        log.add("Oops, seems like an ambush...");
        let forest = gd.monster_by_name("Forest troll");
        let stone = gd.monster_by_name("Stone troll");
        for y in 0..map::MAP_H {
            for x in 0..map::MAP_W {
                if map.terrain_at(x, y) == 96 {
                    map.set_terrain(x, y, map::T_GRASS);
                    let pick = if rng.gen_bool(0.5) { forest } else { stone };
                    if let Some(d) = pick {
                        spawn_single(commands, gd, tiles, d, x, y, false, false, rng);
                    }
                }
            }
        }
    }
    // q_troll.cc: Tom the Stone Troll carries Glamdring (SPECIAL_GENE, so
    // it only ever appears through this scripted drop).
    if def.name == "Tom the Stone Troll" && plot.status(PLOT_TROLL) <= PLOT_COMPLETED {
        if let Some(it) = item::make_specific_artifact(gd, 73, created, rng) {
            item::place_floor_item(commands, gd, tiles, stacks, pos.0, pos.1, it);
            log.add("Glamdring clatters to the ground!");
        }
    }
    // (The Wight-King's "of the Wight" rags are carried from spawn and
    // fall through the generic held-items path above, q_wight.cc.)
    // A FINAL_GUARDIAN's held artifact/object falls where it stood.
    if let Some(aid) = held_artifact {
        if let Some(it) = item::specific_artifact_item(gd, aid, rng) {
            item::place_floor_item(commands, gd, tiles, stacks, pos.0, pos.1, it);
            log.add("It was holding a legendary treasure!");
        }
    }
    if let Some(oid) = held_object {
        if let Some(def_idx2) = gd.object_by_id(oid) {
            let it = item::Item::base(gd, def_idx2);
            item::place_floor_item(commands, gd, tiles, stacks, pos.0, pos.1, it);
        }
    }
    // q_ultrag.cc: Tik'srvzllat surrenders the Flame Imperishable in the
    // Nether Realm once the Void quest is under way.
    if def.id == 1032 && plot.status(PLOT_ULTRA_GOOD) == PLOT_TAKEN {
        if let Some(k) = gd.object_by_id(296) {
            let mut flame = item::Item::base(gd, k);
            flame.identified = true;
            // A full pack pushes the last item out (q_ultrag.cc:263-270).
            if inv.pack.len() >= 23 {
                if let Some(last) = inv.pack.pop() {
                    let label = last.label(gd, &inv.known);
                    item::place_floor_item(commands, gd, tiles, stacks, pos.0, pos.1, last);
                    log.add(format!(
                        "You feel the urge to drop your {} to make room in your inventory.",
                        label
                    ));
                }
            }
            inv.pack.push(flame);
            log.add("You feel the urge to pick up the Flame Imperishable.");
        }
    }
    // q_ultrag.cc: Melkor's final death wins the ultra-good path and opens
    // the portal back to Arda beneath the player.
    if def.id == 1044 && plot.status(PLOT_ULTRA_GOOD) == PLOT_TAKEN {
        plot.set(PLOT_ULTRA_GOOD, PLOT_COMPLETED);
        plot.ultra_won = true;
        plot.won = true;
        log.add("****** CONGRATULATIONS ******");
        log.add("You have done more than the impossible. You ended the threat of");
        log.add("Melkor forever. Thanks to you, Arda will live in eternal peace.");
        log.add("You feel the spirit of Eru touching you. You feel your spirit rising!");
        log.add("Before you, a portal to Arda opens. You can now come back to your world");
        log.add("and live happily ever after.");
        log.add("What you do now is up to you, but your deeds shall ever be remembered.");
        log.add("You may retire (commit suicide) when you are ready.");
    }
    check_main_quest_kill(gd, def_idx, ps, plot, log, rng);
    check_plot_kill(
        gd, def_idx, quest_left, enemy_left, ps.depth, pos, map, plot, ps, inv, log, rng,
    );
    // q_thrain.cc: drop the Dragon Helm "of Thrain" where he stood.
    if plot.thrain_reward {
        plot.thrain_reward = false;
        let drop_at = plot.thrain_pos.unwrap_or(pos);
        if let Some(def) = gd.object_by_tval_sval(crate::data::TV_HELM, 7) {
            let mut helm = item::Item::base(gd, def);
            item::create_artifact(gd, &mut helm, ps.level, false, "", rng);
            helm.artifact_name = "of Thrain".to_string();
            item::place_floor_item(commands, gd, tiles, stacks, drop_at.0, drop_at.1, helm);
            log.add("Thrain's dragon helm lies on the floor.");
        }
    }
    // Random quest progress (q_rand.cc): count the wanted monsters.
    let rand_done = plot
        .rands
        .get_mut(&ps.depth)
        .filter(|rq| rq.def == def_idx && (rq.dungeon == 0 || rq.dungeon == ps.dungeon))
        .map(|rq| {
            rq.got += 1;
            rq.got >= rq.needed
        })
        .unwrap_or(false);
    if rand_done {
        if let Some(rq) = plot.rands.remove(&ps.depth) {
            let princess = rq.princess;
            let depth = rq.depth;
            if princess {
                // Three fine items: the princess lets you pick one.
                // Three great items (q_rand.cc do_get_new_obj:
                // make_object(true, true, no_theme)).
                let mut offers = Vec::new();
                for _ in 0..3 {
                    if let Some(it) = item::make_object_ex(gd, depth + 5, true, true, created, rng)
                    {
                        offers.push(it);
                    }
                }
                // q_rand.cc princess_death: her glass room is wiped and a
                // staircase down raised where she stood (handled on the
                // next input frame so the monster query is available).
                log.add("O Great And Noble Hero, you saved me!");
                log.add("I am heading home now. I cannot reward you as I should, but please take this.");
                plot.offers = Some(offers);
                plot.rand_exit = Some(rq.princess_pos.unwrap_or(pos));
            } else {
                // q_rand.cc hero_death: the swordsman offers to join or
                // teach a skill; the choice needs the companion count, so
                // it is made on the next input frame.
                log.add("The adventurer steps out of the shadows and picks up his sword:");
                log.add("'Ah! My sword! My trusty sword! Thanks.");
                plot.hero_join = gd.monster_by_name("Adventurer");
            }
        }
    }
    // Bounty office progress: the beastmaster wants the corpse back
    // (q_bounty.cc); the bounty body is always recoverable.
    if let Some((bd, done)) = plot.bounty {
        if bd == def_idx && !done {
            plot.bounty = Some((bd, true));
            log.add("You have slain the bounty! Bring its corpse to the Pet Shop.");
            if !def.has("DROP_CORPSE") && !def.has("DROP_SKELETON") {
                if let Some(cd) = gd.object_by_tval_sval(crate::data::TV_CORPSE, 1) {
                    let mut corpse = item::Item::base(gd, cd);
                    item::init_corpse(gd, &mut corpse, def_idx, 1000, rng);
                    corpse.pval3 = corpse_hp(def, ps, rng);
                    // found_aux3/4: dungeon type and level_or_feat.
                    corpse.found_aux3 = ps.dungeon as i32;
                    corpse.found_aux4 = level_or_feat(map, ps, pos.0, pos.1);
                    item::drop_near(
                        commands, gd, tiles, map, stacks, log, &known, &occupied, None, corpse,
                        -1, pos.0, pos.1, rng,
                    );
                }
            }
        }
    }
    // Nazgûl drop a Ring of Power: a plain cursed ring imbued as a randart
    // named "of <nazgul>" (xtra2.cc make_artifact_special death handling).
    if def.has("NAZGUL") {
        if let Some(ring_def) = gd.object_by_tval_sval(crate::data::TV_RING, 5) {
            let mut ring = item::Item::base(gd, ring_def);
            item::create_artifact(gd, &mut ring, ps.level, false, "", rng);
            ring.artifact_name = format!("of {}", def.name);
            log.add("A Ring of Power clatters to the ground!");
            item::drop_near(
                commands, gd, tiles, map, stacks, log, &known, &occupied, None, ring, -1, pos.0,
                pos.1, rng,
            );
        }
    }
    // DROP_CHOSEN unique treasures (xtra2.cc): Morgoth carries Grond and
    // his iron crown; Smeagol hides a ring of invisibility.
    if def.has("DROP_CHOSEN") {
        if def.name.starts_with("Morgoth, Lord of Darkness") {
            for aid in [111u32, 34] {
                if let Some(it) = item::make_specific_artifact(gd, aid, created, rng) {
                    item::place_floor_item(commands, gd, tiles, stacks, pos.0, pos.1, it);
                }
            }
            log.add("Morgoth's treasures clatter to the ground!");
        } else if def.name.contains("Smeagol") {
            if let Some(rd) = gd.object_by_name("Ring of Invisibility") {
                let it = item::make_item(gd, rd, def.depth.max(1), true, created, rng);
                item::place_floor_item(commands, gd, tiles, stacks, pos.0, pos.1, it);
            }
        }
    }
    // Held/stolen loot and the death roll both scatter through drop_near
    // (xtra2.cc monster_death).  The player cell is not available here,
    // so the "roll beneath your feet" notice stays off for monster drops.
    // Held objects (the Wight-King's rags, items stolen from the player)
    // always fall; a robbed monster's pre-rolled treasure replaces the
    // fresh death roll.
    if held_gold > 0 {
        item::place_gold(commands, tiles, pos.0, pos.1, held_gold);
    }
    for it in held_items {
        item::drop_near(
            commands,
            gd,
            tiles,
            map,
            stacks,
            log,
            &known,
            &occupied,
            None,
            it,
            -1,
            pos.0,
            pos.1,
            rng,
        );
    }
    if !looted {
        item::drop_loot_ex(
            commands,
            gd,
            tiles,
            map,
            stacks,
            log,
            &known,
            &occupied,
            None,
            pos.0,
            pos.1,
            def.depth.max(1),
            def,
            created,
            rng,
        );
    }
    // r_info A:<artifact>:<percent> -- a standard artifact drop on death
    // (xtra2.cc; e.g. Saruman's Orthanc).
    if def.artifact_idx > 0 && rng.gen_range(1..=99) <= def.artifact_chance {
        if let Some(it) = item::make_specific_artifact(gd, def.artifact_idx, created, rng) {
            log.add(format!("{} drops a fabled treasure!", cap_first(&dead_name)));
            item::drop_near(
                commands, gd, tiles, map, stacks, log, &known, &occupied, None, it, -1, pos.0,
                pos.1, rng,
            );
        }
    }
    // Corpse-carrying monsters leave a body behind (DROP_CORPSE /
    // DROP_SKELETON; the monster kind rides in `note`). Corpses decay
    // after a while (k_info F:DECAY; fuel doubles as the decay timer).
    // Creeping coins leave no corpse (xtra2.cc:2900 `!force_coin`).
    if (def.has("DROP_CORPSE") || def.has("DROP_SKELETON"))
        && item::get_coin_type(def).is_none()
    {
        let sval = if def.has("DROP_SKELETON") { 2 } else { 1 };
        if let Some(cd) = gd.object_by_tval_sval(crate::data::TV_CORPSE, sval) {
            let mut corpse = item::Item::base(gd, cd);
            item::init_corpse(gd, &mut corpse, def_idx, 1000, rng);
            corpse.pval3 = corpse_hp(def, ps, rng);
            // found_aux3/4: dungeon type and level_or_feat (xtra2.cc:2141).
            corpse.found_aux3 = ps.dungeon as i32;
            corpse.found_aux4 = level_or_feat(map, ps, pos.0, pos.1);
            // Unique corpses are unique (xtra2.cc place_corpse:
            // object_aware + name1 = 201).  The port marks them by name.
            if def.unique {
                corpse.identified = true;
                corpse.artifact_name = "unique corpse".to_string();
            }
            item::drop_near(
                commands, gd, tiles, map, stacks, log, &known, &occupied, None, corpse, -1,
                pos.0, pos.1, rng,
            );
        }
    }
    // Egg-laying monsters sometimes leave an egg (r_info F:HAS_EGG); it
    // hatches into a companion after a while.
    if def.has("HAS_EGG") && rng.gen_bool(0.25) {
        if let Some(ed) = gd.object_by_tval_sval(crate::data::TV_EGG, 1) {
            let mut egg = item::Item::base(gd, ed);
            egg.note = def_idx as u32;
            egg.fuel = 500;
            item::drop_near(
                commands, gd, tiles, map, stacks, log, &known, &occupied, None, egg, -1, pos.0,
                pos.1, rng,
            );
        }
    }
    // WYRM_PROTECT (xtra2.cc): a protected monster's death calls its
    // guardian wyrm onto a nearby floor cell.
    if def.has("WYRM_PROTECT") {
        if let Some(wyrm) = gd.monster_by_name("Great Wyrm of Power") {
            log.add(format!(
                "{} was under the protection of a Great Wyrm of Power!",
                cap_first(&dead_name)
            ));
            for _ in 0..50 {
                let (wx, wy) = (pos.0 + rng.gen_range(-6..=6), pos.1 + rng.gen_range(-6..=6));
                if Map::in_bounds(wx, wy) && map.walkable(gd, wx, wy) {
                    spawn_single(commands, gd, tiles, wyrm, wx, wy, false, false, rng);
                    break;
                }
            }
        }
    }
    // Absorb Soul (Necromancy power): living kills heal the necromancer
    // (xtra2.cc monster death).
    if ps.absorb_soul > 0 && !def.has("UNDEAD") && !def.has("NONLIVING") {
        let heal = 1 + def.depth as i32 / 2 + ps.skill_scale(crate::skill::SK_NECROMANCY, 40);
        ps.hp = (ps.hp + heal).min(ps.max_hp);
        log.add("You absorb the life of the dying soul.");
    }
    god_piety_on_kill(ps, def, log);
    monster_death_gods(ps, gd, def_idx);
    if by_companion {
        // Monster Lore: pet kills only teach the master when the skill is
        // trained, at 120% of the normal kill exp (melee2.cc:161-190).
        let lore = ps.skill(crate::skill::SK_LORE);
        if lore > 0 {
            let scaled = exp * ps.skill_scale(crate::skill::SK_LORE, 120) as u64 / 100;
            gain_exp(ps, scaled, log, rng);
        }
    } else {
        gain_exp(ps, exp, log, rng);
        // Undead Form life debt (dungeon.cc).
        undead_form_kill(ps, log);
    }
}

/// Ctrl-W (dungeon.cc:2802): toggle wizard mode.  The first entry asks
/// (the `confirmed` argument carries the get_check answer / the -w arg)
/// and marks the save unscored with noscore bit 0x0002.
pub fn toggle_wizard(ps: &mut PlayerState, confirmed: bool, log: &mut MessageLog) -> bool {
    if ps.wizard {
        ps.wizard = false;
        log.add("Wizard mode off.");
    } else if crate::data::debug_mode::enter_wizard_mode(&mut ps.noscore, ps.hp, confirmed) {
        ps.wizard = true;
        log.add("Wizard mode on.");
    }
    ps.wizard
}

/// Ctrl-A (dungeon.cc:2837): the debug-command confirmation gate
/// (noscore bit 0x0008; never prompts once wizard mode is on).
pub fn enter_debug_mode_cmd(ps: &mut PlayerState, confirmed: bool, log: &mut MessageLog) -> bool {
    if crate::data::debug_mode::enter_debug_mode(&mut ps.noscore, ps.wizard, confirmed) {
        log.add("Debug commands are enabled.");
        true
    } else {
        false
    }
}

/// OnEnter(Playing): build the level, sprites, player and monsters.
/// When a saved game is pending (continue menu), restore it instead.
#[allow(clippy::too_many_arguments)]
pub fn setup_level(
    mut commands: Commands,
    gd: Res<GameData>,
    tiles: Res<TileAssets>,
    mut ps: ResMut<PlayerState>,
    mut inv: ResMut<Inventory>,
    mut created: ResMut<item::CreatedArtifacts>,
    pending: Option<Res<crate::save::PendingLoad>>,
    mut store: ResMut<crate::save::LevelStore>,
    mut opts: ResMut<crate::options::Options>,
    mut log: ResMut<MessageLog>,
    mut turn: ResMut<TurnState>,
    mut plot: ResMut<PlotQuest>,
) {
    let mut rng = crate::rng::current();

    // dungeon.cc:4680: the -w command line flag enters wizard mode after
    // the confirmation gate (the headless port takes the flag as the
    // confirmation, like answering yes to get_check).
    if !ps.wizard && std::env::args().any(|a| a == "-w" || a == "--wizard") {
        toggle_wizard(&mut ps, true, &mut log);
    }

    // Restore a saved game: use the saved map and respawn its contents.
    if let Some(pending) = pending {
        let save = &pending.0;
        let mut m = save.map.clone();
        let light = player_lite_ex(&ps, &inv, &gd, turn.running.is_some(), opts.view_reduce_lite);
        let (px, py) = save.player_pos;
        map::compute_fov(&mut m, &gd, px, py, light);
        let grid = render::spawn_tile_grid(&mut commands, &tiles);
        commands.insert_resource(grid);
        commands.spawn((
            Player,
            GameEntity,
            GridPos { x: px, y: py },
            render::glyph_sprite(&tiles, '@', 1),
            Transform::from_translation(render::grid_to_world(px, py, 3.0)),
        ));
        for ms in &save.monsters {
            let def = &gd.monsters[ms.def];
            commands.spawn((
                ms.to_monster(),
                ms.to_extra(),
                GameEntity,
                GridPos { x: ms.x, y: ms.y },
                render::glyph_sprite(&tiles, def.ch.chars().next().unwrap_or('?'), def.color),
                Transform::from_translation(render::grid_to_world(ms.x, ms.y, 2.0)),
                Visibility::Hidden,
            ));
        }
        for (x, y, stack) in &save.floor_items {
            if stack.is_empty() {
                continue;
            }
            let o = &gd.objects[stack[0].def];
            commands.spawn((
                item::FloorItem {
                    stack: stack.clone(),
                },
                GameEntity,
                GridPos { x: *x, y: *y },
                render::glyph_sprite(&tiles, o.glyph(), o.color),
                Transform::from_translation(render::grid_to_world(*x, *y, 1.5)),
                Visibility::Hidden,
            ));
        }
        for (x, y, amount) in &save.floor_gold {
            item::place_gold(&mut commands, &tiles, *x, *y, *amount);
        }
        commands.insert_resource(m);
        commands.remove_resource::<crate::save::PendingLoad>();
        // Only save-extension levels persist (save_dungeon); drop any other
        // snapshot an older savefile may still carry (towns, wilderness,
        // the overview, quests, normal dungeon levels).
        store.levels.retain(|k, _| level_persists(&gd, *k));
        // z-rand.cc: reload restores the saved complex RNG state.
        if save.rng_state.is_empty() {
            crate::rng::set_complex_rng();
        } else {
            crate::rng::do_randomizer_restore(&save.rng_state);
        }
        // loadsave.cc do_options: restore the saved preferences.
        *opts = save.options.clone();
        let _ = &mut created;
        log.add("You continue your adventure.");
        *turn = TurnState::default();
        turn.fov_dirty = true;
        return;
    }

    let quest_layer = ps.depth >= PLOT_DEPTH_BASE;
    let gen = generate_current_level(
        &mut commands,
        &gd,
        &tiles,
        &store.wilderness,
        &mut plot,
        &mut ps,
        &turn,
        &opts,
        &mut created.0,
        &mut rng,
        &mut log,
    );
    let mut m = gen.map;
    let vault = gen.vault;
    let light = player_lite_ex(&ps, &inv, &gd, turn.running.is_some(), opts.view_reduce_lite);
    map::compute_fov(&mut m, &gd, gen.start.0, gen.start.1, light);
    // Astral beings see the whole (dungeon) level (generate.cc:8523).
    if ps.astral && ps.depth > 0 {
        m.reveal_all();
    }
    // The Death fate dungeon has no exits (dungeon.cc "wipe all stairs").
    if ps.dungeon == DEATH_DUNGEON {
        wipe_stairs(&mut m);
    }
    let start = gen.start;

    let grid = render::spawn_tile_grid(&mut commands, &tiles);
    commands.insert_resource(grid);

    commands.spawn((
        Player,
        GameEntity,
        GridPos {
            x: start.0,
            y: start.1,
        },
        render::glyph_sprite(&tiles, '@', 1),
        Transform::from_translation(render::grid_to_world(start.0, start.1, 3.0)),
    ));

    if !quest_layer && !ps.wild_mode {
        populate_level(
            &mut commands,
            &gd,
            &tiles,
            &mut m,
            &vault,
            ps.depth,
            ps.dungeon,
            start,
            &mut created.0,
            &mut inv,
            &mut plot,
            &mut ps,
            &mut rng,
            &mut log,
        );
    }
    // The thieves' den ambush (q_thief.cc HOOK_GEN_QUEST): a blow on the
    // head, and everything not cursed is stolen into the great hall.
    // Shared with level_transition so both entry paths behave identically.
    if ps.depth == PLOT_DEPTH_BASE + PLOT_THIEVES {
        quest_thieves_gen_hook(
            &mut commands,
            &gd,
            &tiles,
            &m,
            &mut inv,
            &mut ps,
            &mut rng,
            &mut log,
        );
    }
    let town_num = m.town;
    let feeling = m.feeling;
    commands.insert_resource(m);

    if quest_layer {
        log.add(format!(
            "You enter {}.",
            plot_quest_name(ps.depth - PLOT_DEPTH_BASE)
        ));
    } else if ps.depth == 0 {
        if ps.wild_mode {
            log.add("You look out over the wilderness of Middle-earth.");
        } else if town_num != 0 {
            let name = gd
                .town(town_num, plot.town_destroyed(town_num))
                .map(|t| t.name.clone());
            log.add(format!(
                "You are in {}.",
                name.unwrap_or_else(|| "a town".into())
            ));
        } else {
            log.add("You are in the wilderness.");
        }
    } else {
        let d = gd.dungeon(ps.dungeon);
        log.add(format!("You enter {} (depth {}).", d.name, ps.depth));
        if random_town_at(&ps, ps.dungeon, ps.depth).is_some() {
            log.add("You hear the sound of a market.");
        }
        // Level feeling (cmd4.cc do_cmd_feeling).
        if feeling > 0 {
            log.add(feeling_text(feeling));
        }
    }
    *turn = TurnState::default();
    turn.fov_dirty = true;
    turn.precog_pending = true;
}

/// Whether a monster fits a dungeon's R:/M:/S: generation rules
/// (restrict_monster_to_dungeon, src/monster2.cc).
pub fn monster_ok_in_dungeon(
    gd: &GameData,
    idx: usize,
    d: &crate::data::DungeonDef,
    rng: &mut impl Rng,
) -> bool {
    // Spirits only exist in the Void (monster2.cc:2103).
    if gd.monsters[idx].has("SPIRIT") && d.id != 11 {
        return false;
    }
    if d.rules.is_empty() {
        return true;
    }
    let rule_idx = *d.rule_percents.get(rng.gen_range(0..100)).unwrap_or(&0) as usize;
    let Some(r) = d.rules.get(rule_idx) else {
        return true;
    };
    if r.mode == 0 {
        return true;
    }
    let def = &gd.monsters[idx];
    let all = |list: &Vec<String>| list.iter().all(|f| def.has(f));
    let any = |list: &Vec<String>| list.iter().any(|f| def.has(f));
    let char_match =
        |list: &Vec<String>| list.iter().any(|c| c.chars().next() == Some(def.glyph()));
    let matches = if r.mode == 1 || r.mode == 2 {
        if !r.mflags.is_empty() && !all(&r.mflags) {
            false
        } else if !r.mspells.is_empty() && !all(&r.mspells) {
            false
        } else if !r.chars.is_empty() && !char_match(&r.chars) {
            false
        } else {
            true
        }
    } else if !r.mflags.is_empty() && any(&r.mflags) {
        true
    } else if !r.mspells.is_empty() && any(&r.mspells) {
        true
    } else {
        char_match(&r.chars)
    };
    if r.mode == 2 || r.mode == 4 {
        !matches
    } else {
        matches
    }
}

/// The allocation level (generate.cc:8217 `monster_level = dun_level`):
/// normally the dungeon depth; the Death fate dungeon uses the maximum
/// level (dungeon.cc:4383).  The ADJUST_LEVEL flags do *not* shift this:
/// they set the spawned monster's own level (monster2.cc:2432).
fn dungeon_monster_level(d: &crate::data::DungeonDef, depth: u32) -> u32 {
    if d.id == DEATH_DUNGEON {
        return 127;
    }
    depth.max(1)
}

/// The monster_set_level range a dungeon's ADJUST_LEVEL flags impose on
/// a freshly placed monster (monster2.cc:2432-2449).  The original keeps
/// a single min/max pair, so a 1_2 + 1 dungeon rolls in
/// [depth/2, depth].
pub fn dungeon_adjust_level(d: &crate::data::DungeonDef, depth: u32) -> Option<(u32, u32)> {
    let mut min_level = 0;
    let mut max_level = 0;
    let mut add = false;
    if d.has("ADJUST_LEVEL_1_2") {
        min_level = depth / 2;
        max_level = depth / 2;
        add = true;
    }
    if d.has("ADJUST_LEVEL_1") {
        if min_level == 0 {
            min_level = depth;
        }
        max_level = depth;
        add = true;
    }
    if d.has("ADJUST_LEVEL_2") {
        if min_level == 0 {
            min_level = depth * 2;
        }
        max_level = depth * 2;
        add = true;
    }
    if add {
        Some((min_level.max(1), max_level.max(1)))
    } else {
        None
    }
}

/// Roll the monster_set_level target for one spawn (0 = no override).
fn pick_adjust_level(adjust: Option<(u32, u32)>, rng: &mut impl Rng) -> i32 {
    match adjust {
        Some((lo, hi)) => rng.gen_range(lo.min(hi)..=hi.max(lo)) as i32,
        None => 0,
    }
}

/// Pick a random depth-appropriate monster for a dungeon level
/// (get_mon_num + monster_dungeon restrictions).
/// get_mon_num (monster2.cc:950) over an already-filtered allocation
/// list: the two NASTY_MON level boosts (1/50 each, +level/4+2 capped 5),
/// the 100/rarity weighting and the 50%/10% "keep the harder monster"
/// re-rolls.
pub fn get_mon_num_from(
    gd: &GameData,
    level: u32,
    candidates: &[usize],
    rng: &mut impl Rng,
) -> Option<usize> {
    if candidates.is_empty() {
        return None;
    }
    let mut level = level;
    for _ in 0..2 {
        if level > 0 && rng.gen_range(0..50) == 0 {
            let d = level as i32 / 4 + 2;
            level += d.min(5) as u32;
        }
    }
    let pool: Vec<usize> = candidates
        .iter()
        .copied()
        // r_info[0] is the player placeholder; C++ allocation scans from
        // index 1 (init2.cc:812), so it is never generated as a monster.
        .filter(|&i| gd.monsters[i].id != 0 && gd.monsters[i].depth <= level)
        .collect();
    if pool.is_empty() {
        return None;
    }
    let weights: Vec<u32> = pool
        .iter()
        .map(|&i| (100 / gd.monsters[i].rarity.max(1)).max(1))
        .collect();
    let total: u32 = weights.iter().sum();
    let mut i = weighted_index_pick(&pool, &weights, total, rng);
    let p = rng.gen_range(0..100);
    if p < 60 {
        let j = i;
        let k = weighted_index_pick(&pool, &weights, total, rng);
        if gd.monsters[k].depth >= gd.monsters[j].depth {
            i = k;
        }
    }
    if p < 10 {
        let j = i;
        let k = weighted_index_pick(&pool, &weights, total, rng);
        if gd.monsters[k].depth >= gd.monsters[j].depth {
            i = k;
        }
    }
    Some(i)
}

/// One weighted draw from an allocation pool (the `rand_int(total)` walk
/// of get_mon_num).
fn weighted_index_pick(
    pool: &[usize],
    weights: &[u32],
    total: u32,
    rng: &mut impl Rng,
) -> usize {
    let mut value = rng.gen_range(0..total);
    for (n, &i) in pool.iter().enumerate() {
        if value < weights[n] {
            return i;
        }
        value -= weights[n];
    }
    *pool.last().expect("non-empty")
}

fn pick_dungeon_monster(
    gd: &GameData,
    dinfo: &crate::data::DungeonDef,
    level: u32,
    ps: &PlayerState,
    plot: &PlotQuest,
    rng: &mut impl Rng,
) -> Option<usize> {
    let candidates: Vec<usize> = (0..gd.monster_base_count)
        .filter(|&i| {
            let d = &gd.monsters[i];
            // Joke monsters are off by default (options->joke_monsters,
            // monster2.cc:1025); wilderness-only monsters never appear in
            // dungeons (monster1.cc monster_dungeon).
            d.depth >= 1
                // Uniques join the allocation but only while unused
                // (cur_num >= max_num, monster2.cc get_mon_num:1005).
                && (!d.unique || !ps.unique_seen.contains(&i))
                // quest_main_monsters_hook (q_main.cc).
                && !main_quest_blocks(&d.name, plot)
                && !d.has("JOKEANGBAND")
                && !d.has("WILD_ONLY")
                // place_monster_one refusals: quest-only and never-generated
                // monsters (monster2.cc:2096/2110).
                && !d.has("SPECIAL_GENE")
                && !d.has("NEVER_GENE")
                // FORCE_DEPTH never appears out of depth; ONLY_DEPTH only
                // at its exact depth (monster2.cc:1013).
                && !(d.has("FORCE_DEPTH") && d.depth > level)
                && !(d.has("ONLY_DEPTH") && d.depth != level)
        })
        .filter(|&i| monster_ok_in_dungeon(gd, i, dinfo, rng))
        .collect();
    let picked = get_mon_num_from(gd, level, &candidates, rng)?;
    Some(picked)
}

/// get_mon_num at an explicit monster level, without the dungeon's R:/M:
/// restrictions: the fixed-map `F:...:*N` random markers spawn through
/// this (init1.cc place_monster).
pub fn random_monster_of_level(gd: &GameData, level: u32, rng: &mut impl Rng) -> Option<usize> {
    let candidates: Vec<usize> = (0..gd.monster_base_count)
        .filter(|&i| {
            let d = &gd.monsters[i];
            d.depth >= 1
                && !d.unique
                && !d.has("JOKEANGBAND")
                && !d.has("WILD_ONLY")
                && !d.has("SPECIAL_GENE")
                && !d.has("NEVER_GENE")
                && !(d.has("FORCE_DEPTH") && d.depth > level)
                && !(d.has("ONLY_DEPTH") && d.depth != level)
        })
        .collect();
    get_mon_num_from(gd, level, &candidates, rng)
}

/// Spawn a batch of monsters appropriate for the dungeon depth.
#[allow(clippy::too_many_arguments)]
pub fn spawn_monsters(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    dungeon: u32,
    depth: u32,
    def_override: Option<&crate::data::DungeonDef>,
    ps: &mut PlayerState,
    plot: &PlotQuest,
    rng: &mut impl Rng,
    player: (i32, i32),
) {
    let dinfo = def_override.unwrap_or_else(|| gd.dungeon(dungeon));
    let level = dungeon_monster_level(dinfo, depth);
    let adjust = dungeon_adjust_level(dinfo, depth);
    // min_m_alloc_level + randint(8) + k (src/generate.cc).
    let k = (depth / 3).clamp(2, 10) as i32;
    let count = (dinfo.min_alloc as i32 + rng.gen_range(1..=8) + k).min(60);

    let mut placed_cells: HashSet<(i32, i32)> = HashSet::new();
    let mut placed = 0;
    let mut tries = 0;
    while placed < count && tries < 500 {
        tries += 1;
        let x = rng.gen_range(1..map::MAP_W - 1);
        let y = rng.gen_range(1..map::MAP_H - 1);
        if map::chebyshev(x, y, player.0, player.1) < 7 {
            continue;
        }
        if !map.walkable(gd, x, y) {
            continue;
        }
        if !placed_cells.insert((x, y)) {
            continue;
        }
        let Some(def) = pick_dungeon_monster(gd, dinfo, level, ps, plot, rng) else {
            return;
        };
        // set_monster_aux_hook: refuse a race that cannot stand on the
        // spawn terrain (and retry the placement).
        if !monster_spawn_ok(gd, &gd.monsters[def], map, x, y) {
            continue;
        }
        if gd.monsters[def].unique {
            ps.unique_seen.insert(def);
        }
        spawn_one_monster_occ(
            commands,
            gd,
            tiles,
            map,
            def,
            x,
            y,
            depth,
            adjust,
            true,
            &mut placed_cells,
            rng,
        );
        placed += 1;
    }
}

/// Natural creature generation (src/monster2.cc alloc_monster, called every
/// world turn from dungeon.cc process_world): find an empty grid farther
/// than MAX_SIGHT + 5 from the player. One in 5000 chances per dungeon
/// level a horde (leader + 5-15 kin) is generated instead.
#[allow(clippy::too_many_arguments)]
pub fn alloc_wandering_monster(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    dungeon: u32,
    depth: u32,
    player: (i32, i32),
    occupied: &HashSet<(i32, i32)>,
    ps: &mut PlayerState,
    plot: &PlotQuest,
    rng: &mut impl Rng,
) -> bool {
    // The Lost Temple's natural generation uses its per-god attributes
    // (W: min_m_alloc_level / max_m_alloc_chance), not the static record.
    let temple_def;
    let dinfo = if dungeon == DUNGEON_GOD {
        temple_def = god_temple_def(gd, ps);
        &temple_def
    } else {
        gd.dungeon(dungeon)
    };
    let level = dungeon_monster_level(dinfo, depth);
    let adjust = dungeon_adjust_level(dinfo, depth);
    let mut occ: HashSet<(i32, i32)> = occupied.clone();
    let mut spot = None;
    for _ in 0..10000 {
        let x = rng.gen_range(0..map::MAP_W);
        let y = rng.gen_range(0..map::MAP_H);
        // MAX_SIGHT (20) + 5 in the original.
        if map::chebyshev(x, y, player.0, player.1) <= 25 {
            continue;
        }
        if !map.walkable(gd, x, y) || occupied.contains(&(x, y)) {
            continue;
        }
        spot = Some((x, y));
        break;
    }
    let Some((x, y)) = spot else { return false };
    if rng.gen_range(1..=5000) <= depth {
        // alloc_horde: a leader plus randint(10) + 5 kin.
        let def = loop {
            let Some(d) = pick_dungeon_monster(gd, dinfo, level, ps, plot, rng) else {
                return false;
            };
            // alloc_horde skips uniques and RF_ESCORTS leaders.
            if !gd.monsters[d].unique && !gd.monsters[d].has("ESCORTS") {
                break d;
            }
        };
        spawn_one_monster_occ(
            commands, gd, tiles, map, def, x, y, depth, adjust, true, &mut occ, rng,
        );
        let caster = gd.monsters[def].clone();
        // summon_specific level = (dun_level + dun_level) / 2 + 5.
        let kin_level = depth + 5;
        for _ in 0..rng.gen_range(6..=15) {
            summon_kin_horde(
                commands,
                gd,
                tiles,
                map,
                kin_level,
                adjust,
                (x, y),
                &caster,
                &mut occ,
                rng,
            );
        }
        return true;
    }
    let Some(def) = pick_dungeon_monster(gd, dinfo, level, ps, plot, rng) else {
        return false;
    };
    if !monster_spawn_ok(gd, &gd.monsters[def], map, x, y) {
        return false;
    }
    if gd.monsters[def].unique {
        ps.unique_seen.insert(def);
    }
    spawn_one_monster_occ(
        commands, gd, tiles, map, def, x, y, depth, adjust, true, &mut occ, rng,
    );
    true
}

/// One SUMMON_KIN call for a horde (src/melee2.cc summon_specific with the
/// bare dungeon level).
#[allow(clippy::too_many_arguments)]
fn summon_kin_horde(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    level: u32,
    adjust: Option<(u32, u32)>,
    around: (i32, i32),
    caster: &crate::data::MonsterDef,
    occupied: &mut HashSet<(i32, i32)>,
    rng: &mut impl Rng,
) {
    let candidates: Vec<usize> = (0..gd.monster_base_count)
        .filter(|&i| {
            let d = &gd.monsters[i];
            !d.unique && d.depth >= 1 && d.depth <= level && d.glyph() == caster.glyph()
        })
        .collect();
    if candidates.is_empty() {
        return;
    }
    let def = candidates[rng.gen_range(0..candidates.len())];
    for _ in 0..20 {
        let x = around.0 + rng.gen_range(-2..=2);
        let y = around.1 + rng.gen_range(-2..=2);
        if map.walkable(gd, x, y) && !occupied.contains(&(x, y)) {
            spawn_one_monster_occ(
                commands, gd, tiles, map, def, x, y, level, adjust, true, occupied, rng,
            );
            break;
        }
    }
}

/// Roll an ego variant for a randomly generated monster (monster2.cc
/// pick_ego_monster): 18% chance, the base must match the ego's flags and
/// glyph, then out-of-depth and rarity checks.  In Elven/Dwarven towns
/// (map.mflag, from the t_info `f:` line) only the matching ego applies:
/// no 18% roll, no level/rarity checks, mego_ok still rules.  Returns a
/// variant def index (>= monster_base_count) or None.
pub fn roll_monster_ego(
    gd: &GameData,
    base: usize,
    depth: u32,
    theme: &str,
    rng: &mut impl Rng,
) -> Option<usize> {
    // Themed townspeople bypass the random scan (monster2.cc:275-285).
    let themed = match theme {
        "ELVEN" => Some("Elven"),
        "DWARVEN" => Some("Dwarven"),
        _ => None,
    };
    let cands = gd.variants_by_base.get(&base)?;
    if let Some(name) = themed {
        return cands.iter().copied().find(|&vi| {
            let ego_id = gd.variant_egos[vi - gd.monster_base_count];
            gd.monster_egos
                .iter()
                .any(|e| e.id == ego_id && e.name == name)
        });
    }
    if depth == 0 || gd.monsters[base].depth == 0 {
        // No townspeople / depth-0 ego (monster2.cc `if (!r_ptr->level)`).
        return None;
    }
    if cands.is_empty() || !rng.gen_bool(0.18) {
        return None;
    }
    let base_depth = gd.monsters[base].depth as i32;
    for _ in 0..cands.len() + 10 {
        let vi = cands[rng.gen_range(0..cands.len())];
        let ego_id = gd.variant_egos[vi - gd.monster_base_count];
        let Some(e) = gd.monster_egos.iter().find(|e| e.id == ego_id) else {
            continue;
        };
        let mut lvl = crate::data::apply_mod(base_depth, &e.level);
        lvl -= (depth / 2) as i32 + rng.gen_range(0..(depth / 2).max(1)) as i32;
        if lvl < 1 {
            lvl = 1;
        }
        if rng.gen_range(0..lvl as u32) != 0 {
            continue;
        }
        if rng.gen_range(0..e.rarity.max(1)) != 0 {
            continue;
        }
        return Some(vi);
    }
    None
}

/// modules.cc:542 drunk_takes_wine: giving Ale or Wine (TV_FOOD svals
/// 38/39) to the "Singing, happy drunk" destroys the drink and leaves an
/// empty bottle. Returns the bottle for the Give handler to drop.
pub fn drunk_takes_wine(gd: &GameData, def_idx: usize, it: &item::Item) -> Option<item::Item> {
    let d = gd.monsters.get(def_idx)?;
    let o = &gd.objects[it.def];
    if d.name == "Singing, happy drunk"
        && o.tval == crate::data::TV_FOOD
        && (o.sval == 38 || o.sval == 39)
    {
        let def = gd.object_by_tval_sval(crate::data::TV_BOTTLE, 1)?;
        Some(item::Item::base(gd, def))
    } else {
        None
    }
}

/// A parsed wish (xtra2.cc make_wish). `status` uses the original
/// MSTATUS_* values (0 enemy, 1 neutral, 2 friend, 3 pet, 4 companion).
pub enum Wish {
    Object(item::Item),
    Monster {
        def: usize,
        ego: Option<u32>,
        status: u8,
    },
    Refused,
}

pub const WISH_ENEMY: u8 = 0;
pub const WISH_NEUTRAL: u8 = 1;
pub const WISH_FRIEND: u8 = 2;
pub const WISH_PET: u8 = 3;
pub const WISH_COMPANION: u8 = 4;

/// clean_wish_name (xtra2.cc:5140): lowercase, collapse spaces.
fn clean_wish_name(buf: &str) -> String {
    buf.to_lowercase()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

/// make_wish (xtra2.cc:5187): turn a typed wish into an object or a
/// monster. The caller owns the text input and the actual placement
/// (item::place_floor_item / spawn_single). Base object names and
/// base+ego monster names are matched; the full generated-description
/// scan of the original is approximated.
pub fn make_wish(
    gd: &GameData,
    ps: &PlayerState,
    text: &str,
    created: &mut HashSet<u32>,
    rng: &mut impl Rng,
) -> Wish {
    let name = clean_wish_name(text);
    if name.is_empty() || name.contains("wish") {
        return Wish::Refused;
    }
    // Objects: exact lowercased base name (artifacts/randarts are never
    // wished for, xtra2.cc:5009).
    if let Some(def) = gd
        .objects
        .iter()
        .position(|o| !o.name.is_empty() && o.name.to_lowercase() == name)
    {
        let it = item::make_item(gd, def, ps.depth.max(1), false, created, rng);
        return Wish::Object(it);
    }
    // Monster wishes carry an optional status prefix.
    let (status, mname) = if let Some(rest) = name.strip_prefix("enemy ") {
        (WISH_ENEMY, rest)
    } else if let Some(rest) = name.strip_prefix("neutral ") {
        (WISH_NEUTRAL, rest)
    } else if let Some(rest) = name.strip_prefix("friendly ") {
        (WISH_FRIEND, rest)
    } else if let Some(rest) = name.strip_prefix("pet ") {
        (WISH_PET, rest)
    } else if let Some(rest) = name.strip_prefix("companion ") {
        (WISH_COMPANION, rest)
    } else {
        (WISH_ENEMY, name.as_str())
    };
    for i in 0..gd.monster_base_count {
        let d = &gd.monsters[i];
        if d.name.is_empty() || d.unique || d.has("SPECIAL_GENE") || d.has("NEVER_GENE") {
            continue;
        }
        let base = d.name.to_lowercase();
        if mname == base {
            return Wish::Monster {
                def: i,
                ego: None,
                status,
            };
        }
        // Try the ego variants of this base (monster_ego_modify names).
        let Some(variants) = gd.variants_by_base.get(&i) else {
            continue;
        };
        for &v in variants {
            let ego_id = gd.variant_egos[v - gd.monster_base_count];
            let Some(e) = gd.monster_egos.iter().find(|e| e.id == ego_id) else {
                continue;
            };
            if e.name.is_empty() {
                continue;
            }
            let full = if e.before {
                format!("{} {}", e.name.to_lowercase(), base)
            } else {
                format!("{} {}", base, e.name.to_lowercase())
            };
            if mname == full {
                return Wish::Monster {
                    def: v,
                    ego: Some(ego_id),
                    status,
                };
            }
        }
    }
    Wish::Refused
}

/// Spawn one monster of the given def at (x, y). Monsters with the
/// FRIENDS flag bring 1-2 companions of the same kind; ESCORT uniques
/// bring 1-2 depth-appropriate escorts.
#[allow(clippy::too_many_arguments)]
pub fn spawn_one_monster(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    map: &Map,
    def_idx: usize,
    x: i32,
    y: i32,
    ego_depth: u32,
    adjust: Option<(u32, u32)>,
    rng: &mut impl Rng,
) {
    // Randomly-generated monsters may carry a monster ego (re_info);
    // themed towns always consider their ego (monster2.cc).
    let def_idx = if ego_depth > 0 || !map.mflag.is_empty() {
        roll_monster_ego(gd, def_idx, ego_depth, &map.mflag, rng).unwrap_or(def_idx)
    } else {
        def_idx
    };
    let level = pick_adjust_level(adjust, rng);
    spawn_single_level(commands, gd, tiles, def_idx, x, y, level, rng);
    let def = &gd.monsters[def_idx];
    if def.friends || def.escort || def.has("ESCORTS") {
        let mut occupied: HashSet<(i32, i32)> = HashSet::new();
        occupied.insert((x, y));
        for _ in 0..rng.gen_range(1..=2) {
            // Friends are the same kind; escorts pass place_monster_okay.
            let buddy = if def.friends {
                def_idx
            } else {
                let candidates: Vec<usize> = (0..gd.monster_base_count)
                    .filter(|&i| monster_escort_ok(def, &gd.monsters[i], def_idx, i))
                    .collect();
                if candidates.is_empty() {
                    continue;
                }
                candidates[rng.gen_range(0..candidates.len())]
            };
            for _ in 0..10 {
                let nx = x + rng.gen_range(-2..=2);
                let ny = y + rng.gen_range(-2..=2);
                if (nx, ny) != (x, y)
                    && !occupied.contains(&(nx, ny))
                    && map.walkable(gd, nx, ny)
                {
                    let level = pick_adjust_level(adjust, rng);
                    spawn_single_level(commands, gd, tiles, buddy, nx, ny, level, rng);
                    occupied.insert((nx, ny));
                    break;
                }
            }
        }
    }
}

/// Spawn one monster with an explicit monster_set_level override
