/// Spawn a companion that fights for the player (pets, charms, calls).
#[allow(clippy::too_many_arguments)]
/// Roll a monster's hit dice (r_info HD), honouring FORCE_MAXHP
/// (monster2.cc place_monster_one).
pub fn roll_monster_hp(def: &crate::data::MonsterDef, rng: &mut impl Rng) -> i32 {
    let Some(d) = Dice::parse(&def.hp) else {
        return 1;
    };
    let hp = if def.has("FORCE_MAXHP") {
        d.count * d.sides + d.bonus
    } else {
        d.roll(rng)
    };
    hp.max(1)
}

