/// Spawn the rescued swordsman as a companion (q_rand.cc hero_death):
/// experience for `monster_exp(1 + dun_level*3/2)` followed by
/// monster_check_experience, exactly like the C++ unique.
#[allow(clippy::too_many_arguments)]
pub fn spawn_hero_companion(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    def_idx: usize,
    x: i32,
    y: i32,
    depth: u32,
    rng: &mut impl Rng,
) {
    let def = &gd.monsters[def_idx];
    let hp = roll_monster_hp(def, rng);
    let mut mon = Monster {
        def: def_idx,
        hp,
        max_hp: hp,
        energy: rng.gen_range(0..100),
        awake: true,
        friendly: true,
        quest: false,
        cut: 0,
        poison: 0,
        fear: 0,
        companion: true,
        // q_rand.cc:382 places the hero as MSTATUS_COMPANION.
        pet: false,
        neutral: false,
        gold: 0,
        mimic: 0,
        smart: 0,
        mspeed_mod: 0,
        stun: 0,
        confused: 0,
        held_artifact: None,
        held_object: None,
        items: Vec::new(),
        looted: false,
        seen: false,
        detected: 0,
        controlled: false,
        mon_level: 0,
        possessor: None,
            ac_mod: 0,
            blow_penalty: 0,
        target: None,
    };
    let mut extra = MonsterExtra {
        exp: monster_exp(1 + depth as i32 * 3 / 2),
        ..Default::default()
    };
    let mut log = MessageLog::default();
    monster_check_experience(gd, &mut mon, &mut extra, true, rng, &mut log);
    commands.spawn((
        mon,
        extra,
        GameEntity,
        GridPos { x, y },
        render::glyph_sprite(tiles, def.ch.chars().next().unwrap_or('?'), def.color),
        Transform::from_translation(render::grid_to_world(x, y, 2.0)),
        Visibility::Hidden,
    ));
}

