/// spawn_flagged_held with carried items (q_wight.cc's held rags).
#[allow(clippy::too_many_arguments)]
fn spawn_flagged_held_items(
    commands: &mut Commands,
    gd: &GameData,
    tiles: &TileAssets,
    def_idx: usize,
    x: i32,
    y: i32,
    friendly: bool,
    quest: bool,
    companion: bool,
    held_artifact: Option<u32>,
    held_object: Option<u32>,
    hp_override: Option<i32>,
    mon_level: i32,
    smart: u32,
    partial: bool,
    pet: bool,
    items: Vec<item::Item>,
    rng: &mut impl Rng,
) {
    let def = &gd.monsters[def_idx];
    let hp = hp_override.unwrap_or_else(|| roll_monster_hp(def, rng));
    // MIMIC monsters carry an object to imitate while asleep (monster2.cc).
    let mimic = if def.has("MIMIC") {
        crate::item::gen_object_kind(gd, def.depth.max(1), rng).unwrap_or(0) as u32
    } else {
        0
    };
    // Hack -- small racial variety (monster2.cc place_monster_one):
    // non-unique monsters get a random speed spread of extract_energy/10.
    let mut mspeed_mod = 0;
    if !def.unique {
        let spread = extract_energy(def.speed.clamp(0, 299)) / 10;
        if spread != 0 {
            mspeed_mod += rng.gen_range(-spread..=spread);
        }
    }
    commands.spawn((
        Monster {
            def: def_idx,
            hp,
            max_hp: hp,
            // Give a random starting energy (monster2.cc).
            energy: rng.gen_range(0..100),
            awake: companion,
            quest,
            // PET monsters spawn friendly (monster2.cc).
            friendly: friendly || def.has("PET"),
                cut: 0,
            poison: 0,
            fear: 0,
            companion,
            // place_monster_one raises r_info PET races to MSTATUS_PET
            // unless the caller asked for a faithful companion.
            pet: pet || (def.has("PET") && !companion),
            neutral: def.has("NEUTRAL") && !(friendly || def.has("PET")) && !companion,
            gold: 0,
            mimic,
            smart,
            mspeed_mod,
            stun: 0,
            confused: 0,
            held_artifact,
            held_object,
            items,
            looted: false,
            seen: false,
            detected: 0,
            controlled: false,
            mon_level,
            possessor: None,
            ac_mod: 0,
            blow_penalty: 0,
            target: None,
        },
        MonsterExtra {
            exp: monster_exp(if mon_level > 0 {
                mon_level
            } else {
                def.depth.max(1) as i32
            }),
            nice: def.has("FORCE_SLEEP"),
            partial,
            ..Default::default()
        },
        GameEntity,
        GridPos { x, y },
        render::glyph_sprite(tiles, def.ch.chars().next().unwrap_or('?'), def.color),
        Transform::from_translation(render::grid_to_world(x, y, 2.0)),
        Visibility::Hidden,
    ));
}

// --- Gods (deity system; tables.cc deity_info) ---

/// The stat boons a god grants at grace thresholds (xtra1.cc calc_gods).
pub fn god_boons(ps: &PlayerState) -> [i32; 6] {
    let g = ps.grace;
    match ps.god {
        1 => [
            0,
            0,
            (g > 10000) as i32 + (g > 20000) as i32 + (g > 30000) as i32,
            0,
            0,
            0,
        ], // Eru: +WIS
        3 => [
            (g > 10000) as i32 + (g > 15000) as i32 + (g > 20000) as i32,
            0,
            0,
            0,
            (g > 5000) as i32 + (g > 10000) as i32 + (g > 15000) as i32,
            0,
        ], // Tulkas: +STR/+CON
        4 => [
            (g > 10000) as i32 + (g > 20000) as i32 + (g > 30000) as i32,
            -((g > 10000) as i32 + (g > 20000) as i32 + (g > 30000) as i32),
            -((g > 10000) as i32 + (g > 20000) as i32 + (g > 30000) as i32),
            0,
            (g > 10000) as i32 + (g > 20000) as i32 + (g > 30000) as i32,
            (g > 10000) as i32 + (g > 20000) as i32 + (g > 30000) as i32,
        ], // Melkor: +STR/CON/CHR, -INT/WIS
        _ => [0; 6],
    }
}

/// Manwe's blessings: feather fall (2000), free action (7000, while
/// praying), flight (15000, while praying).
pub fn god_feather(ps: &PlayerState) -> bool {
    ps.god == 2 && ps.grace >= 2000
}

pub fn god_free_act(ps: &PlayerState) -> bool {
    praying_to(ps, 2) && ps.grace >= 7000
}

/// Burning Yavanna's trees costs her grace (spells1.cc:3026/3037/3182/3206:
/// fire -50, nether -60, disintegration -60).  Only her worshippers are
/// affected.  modal.rs's gf_terrain tree arms call this.
pub fn yavanna_tree_piety(ps: &mut PlayerState, amount: i32) {
    if ps.god == 5 {
        ps.grace = (ps.grace - amount).max(-300000);
    }
}

/// set_poison (xtra2.cc:328) with its activation/deactivation notices.
pub fn set_tim_poison(ps: &mut PlayerState, v: i32, log: &mut MessageLog) -> bool {
    let v = v.clamp(0, 10000);
    let notice = if v > 0 && ps.tim_poison == 0 {
        log.add("Your hands are dripping with venom.");
        true
    } else if v == 0 && ps.tim_poison > 0 {
        log.add("The venom source dries out.");
        true
    } else {
        false
    };
    ps.tim_poison = v;
    notice
}

/// set_tim_thunder (xtra2.cc:1025) with its notices and power pair.
pub fn set_tim_thunder(
    ps: &mut PlayerState,
    v: i32,
    p1: i32,
    p2: i32,
    log: &mut MessageLog,
) -> bool {
    let v = v.clamp(0, 10000);
    let (mut p1, mut p2) = (p1, p2);
    let notice = if v > 0 && ps.tim_thunder == 0 {
        log.add("The air around you charges with lightning!");
        true
    } else if v == 0 && ps.tim_thunder > 0 {
        log.add("The air around you discharges.");
        // The discharged storm forgets its dice (xtra2.cc:1041).
        p1 = 0;
        p2 = 0;
        true
    } else {
        false
    };
    ps.tim_thunder = v;
    ps.thunder_dd = p1;
    ps.thunder_ds = p2;
    notice
}

/// set_simple_field (xtra2.cc:147): clamp `v` to [0, 10000] and print the
/// activation/deactivation line on the empty<->non-empty transition.
/// The original's PU_BONUS update is implicit in the port (equipment and
/// statuses are recomputed every turn), so this only carries the state and
/// the notice.
#[allow(dead_code)]
fn set_simple_field(
    field: &mut i32,
    v: i32,
    activate: &str,
    deactivate: &str,
    log: &mut MessageLog,
) -> bool {
    let v = v.clamp(0, 10000);
    let notice = if v != 0 && *field == 0 {
        log.add(activate);
        true
    } else if v == 0 && *field != 0 {
        log.add(deactivate);
        true
    } else {
        false
    };
    *field = v;
    notice
}

