    #[test]
    fn monster2_spawn_groups_and_escorts() {        use bevy::ecs::system::RunSystemOnce;
        use bevy::prelude::*;
        let gd = load_game_data();
        // place_monster_okay: same glyph, level <= leader, non-unique.
        let ufthak = gd.monster_by_name("Ufthak of Cirith Ungol").unwrap();
        let orc = gd
            .monsters
            .iter()
            .position(|d| {
                d.glyph() == 'o'
                    && !d.unique
                    && d.depth <= gd.monsters[ufthak].depth
                    && !d.has("WILD_ONLY")
            })
            .unwrap();
        assert!(monster_escort_ok(
            &gd.monsters[ufthak],
            &gd.monsters[orc],
            ufthak,
            orc
        ));
        let human = gd.monster_by_name("Battle-scarred veteran").unwrap();
        assert!(!monster_escort_ok(
            &gd.monsters[ufthak],
            &gd.monsters[human],
            ufthak,
            human
        ));
        let unique_orc = (0..gd.monster_base_count)
            .find(|&i| gd.monsters[i].unique && gd.monsters[i].glyph() == 'o')
            .unwrap();
        assert!(!monster_escort_ok(
            &gd.monsters[ufthak],
            &gd.monsters[unique_orc],
            ufthak,
            unique_orc
        ));

        let mut world = World::new();
        world.insert_resource(crate::options::Options::default());
        world.insert_resource(gd);
        world.insert_resource(crate::render::TileAssets {
            font: Default::default(),
            bg_image: Default::default(),
            bg_layout: Default::default(),
            fg_image: Default::default(),
            fg_layout: Default::default(),
        });
        world.run_system_once(spawn_group_system).unwrap();
        world.flush();
        let mut q = world.query::<&Monster>();
        let n = q.iter(&world).count();
        assert!(n > 3, "expected groups and escorts, spawned {n}");
    }

