    #[test]
    fn monster2_summons_and_pain_messages() {
        use bevy::ecs::system::RunSystemOnce;
        use bevy::prelude::*;
        let gd = load_game_data();
        let mut world = World::new();
        world.insert_resource(crate::options::Options::default());
        world.insert_resource(load_game_data());
        world.insert_resource(crate::render::TileAssets {
            font: Default::default(),
            bg_image: Default::default(),
            bg_layout: Default::default(),
            fg_image: Default::default(),
            fg_layout: Default::default(),
        });
        world.run_system_once(summon_system).unwrap();
        world.flush();
        let mut q = world.query::<&Monster>();
        let spiders: Vec<usize> = q
            .iter(&world)
            .map(|m| m.def)
            .filter(|&d| world.resource::<GameData>().monsters[d].glyph() == 'S')
            .collect();
        assert!(!spiders.is_empty(), "SUMMON_SPIDER placed nothing");

        // monster_race_desc: uniques bare, the rest indefinite.
        let sparrow = gd.monster_by_name("Sparrow").unwrap();        assert_eq!(monster_race_desc(&gd, sparrow), "a Sparrow");
        let unique = gd.monsters.iter().position(|d| d.unique).unwrap();
        assert_eq!(monster_race_desc(&gd, unique), gd.monsters[unique].name);

        // is_friend: pets/friends positive, neutral zero, hostile -1.
        let hostile = test_monster(sparrow, 10);
        assert_eq!(is_friend(&hostile), -1);
        let mut neutral = test_monster(sparrow, 10);
        neutral.neutral = true;
        assert_eq!(is_friend(&neutral), 0);
        let mut pet = test_monster(sparrow, 10);
        pet.companion = true;
        assert_eq!(is_friend(&pet), 1);

        // message_pain bands by glyph class and hp percentage.
        let urchin = gd.monster_by_name("Filthy street urchin").unwrap();
        let mut m = test_monster(urchin, 100);
        m.seen = true;
        let mut log = MessageLog::default();
        message_pain(&gd, &m, 0, &mut log);
        assert!(log.lines.back().unwrap().contains("is unharmed."));
        message_pain(&gd, &m, 1, &mut log);
        assert!(log.lines.back().unwrap().contains("ignores the attack."));
        let mut hurt = test_monster(urchin, 20);
        hurt.seen = true;
        hurt.hp = 10;
        message_pain(&gd, &hurt, 90, &mut log);
        assert!(log.lines.back().unwrap().contains("cries out feebly."));
    }

    fn multiply_system(
        mut commands: Commands,
        gd: Res<GameData>,
        tiles: Res<TileAssets>,
        mut q: Query<(&mut Monster, &GridPos)>,
        ps: Res<PlayerState>,
        mut log: ResMut<MessageLog>,
    ) {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let map = map::blank_pub(map::T_FLOOR);
        let mut rng = StdRng::seed_from_u64(5);
        for (mut m, pos) in &mut q {
            let mut occupied = HashSet::new();
            occupied.insert((pos.x, pos.y));
            for _ in 0..60 {
                if ai_multiply_monster(
                    &mut commands,
                    &gd,
                    &tiles,
                    &map,
                    &mut m,
                    pos,
                    &mut occupied,
                    (0, 0),
                    ps.depth,
                    false,
                    &mut rng,
                    &mut log,
                ) {
                    break;
                }
            }
        }
    }

