    fn kill_drop_system(
        mut commands: Commands,
        gd: Res<GameData>,
        tiles: Res<TileAssets>,
        mut stacks: Query<(Entity, &GridPos, &mut item::FloorItem)>,
        mut ps: ResMut<PlayerState>,
        mut plot: ResMut<PlotQuest>,
        mut map: ResMut<Map>,
        mut created: ResMut<item::CreatedArtifacts>,
        mut inv: ResMut<Inventory>,
        mut log: ResMut<MessageLog>,
        q: Query<(Entity, &Monster, &GridPos)>,
    ) {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let mut rng = StdRng::seed_from_u64(7);
        for (e, m, pos) in &q {
            let items = m.items.clone();
            let gold = m.gold;
            kill_monster(
                &mut commands,
                &gd,
                &tiles,
                &mut stacks,
                e,
                m.def,
                (pos.x, pos.y),
                None,
                None,
                items,
                gold,
                true,
                &mut ps,
                &mut plot,
                &mut map,
                0,
                0,
                &mut created.0,
                &mut inv,
                &mut log,
                &mut rng,
                false,
            );
        }
    }

