    #[test]
    fn monsters_learn_and_prune_resisted_spells() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let (idx, _def) = gd
            .monsters
            .iter()
            .enumerate()
            .find(|(_, d)| {
                d.spells.iter().any(|s| s == "BR_FIRE")
                    && d.spells.iter().any(|s| s == "BR_COLD")
                    && !d.has("STUPID")
            })
            .expect("a fire+ice breather");
        let def = &gd.monsters[idx];
        let mut m = test_monster(idx, 100);
        m.smart = SM_IMM_FIRE;
        let mut allowed: Vec<String> = def.spells.clone();
        let mut rng = StdRng::seed_from_u64(11);
        // Monsters only learn while the (base-off) smart_learn option is on.
        set_smart_learn(true);
        for _ in 0..400 {
            m.smart = SM_IMM_FIRE;
            remove_bad_spells(&mut m, def, &mut allowed, &mut rng);
            if !allowed.iter().any(|f| f == "BR_FIRE") {
                break;
            }
        }
        set_smart_learn(false);
        assert!(
            !allowed.iter().any(|f| f == "BR_FIRE"),
            "fire breath was never pruned"
        );
        assert!(allowed.iter().any(|f| f == "BR_COLD"));
    }

