    #[test]
    fn dungeon_spell_damage_matches_tables() {
        let mut rng = crate::rng::current();
        // Breaths are capped by the caster's hp.
        let (gf, raw) = monst_spell_damage("BR_FIRE", 30, 300, &mut rng).unwrap();
        assert_eq!(gf, "FIRE");
        assert_eq!(raw, 100);
        let (gf, raw) = monst_spell_damage("BR_FIRE", 30, 100000, &mut rng).unwrap();
        assert_eq!(gf, "FIRE");
        assert_eq!(raw, 1600);
        // Bolts scale with the caster's level.
        let (gf, raw) = monst_spell_damage("BO_ACID", 10, 500, &mut rng).unwrap();
        assert_eq!(gf, "ACID");
        assert!((7 + 3..=7 * 8 + 3).contains(&raw));
        assert!(monst_spell_damage("HEAL", 10, 500, &mut rng).is_none());
    }

