    #[test]
    fn one_ring_evil_path_saves_life_and_binds_sauron() {
        use crate::birth::make_player;
        use crate::data::load_game_data;
        let gd = load_game_data();
        let mut log = MessageLog::default();
        let mut rng = crate::rng::current();
        // The real artifact: a wearable ring of power (a_info 13).
        let ring = crate::item::specific_artifact_item(&gd, 13, &mut rng).expect("One Ring");
        assert_eq!(ring.artifact, 13);
        assert_eq!(gd.objects[ring.def].tval, crate::data::TV_RING);
        let flags = crate::item::item_flags(&gd, &ring);
        assert!(flags.iter().any(|f| *f == "PERMA_CURSE"));
        assert!(flags.iter().any(|f| *f == "CURSE_NO_DROP"));
        assert!(gd.artifacts.iter().find(|a| a.id == 13).unwrap().insta_art);
        // The Ring sustains a lethal blow at the price of max hit points.
        let mut ps = make_player(&gd, "T".into(), 0, 0);
        ps.ring_worn = true;
        ps.max_hp = 30;
        ps.hp = -5;
        assert!(!player_death_check(&mut ps, &gd, &mut log));
        assert_eq!(ps.ring_lives, 1);
        assert_eq!(ps.max_hp, 20);
        assert_eq!(ps.hp, 20);
        // Once only one hit point is left, the shadow world claims the soul.
        ps.max_hp = 1;
        ps.hp = -5;
        assert!(player_death_check(&mut ps, &gd, &mut log));
        // Wearing the Ring binds Sauron's spirit for good (q_one.cc).
        let sauron = gd.monster_by_name("Sauron, the Sorcerer").unwrap();
        let mut ps = make_player(&gd, "T".into(), 0, 0);
        ps.ring_worn = true;
        let mut plot = PlotQuest::default();
        plot.set(PLOT_SAURON, PLOT_TAKEN);
        check_main_quest_kill(&gd, sauron, &mut ps, &mut plot, &mut log, &mut rng);
        assert_eq!(plot.status(PLOT_SAURON), PLOT_COMPLETED);
        assert_eq!(plot.status(PLOT_MORGOTH), PLOT_TAKEN);
    }

