        assert_eq!(plot.status(PLOT_MORGOTH), PLOT_COMPLETED);
        assert_eq!(plot.status(PLOT_ULTRA_GOOD), PLOT_TAKEN);
        assert!(plot.ultra_good_unlocked);
        assert!(!plot.won, "the ultra-good path continues to Melkor");
        // Ultra evil: the Ring was kept; the player takes Morgoth's place.
        let mut ps2 = make_player(&gd, "T".into(), 0, 0);
