    #[test]
    fn god_boons_and_piety() {
        use crate::birth::make_player;
        use crate::data::load_game_data;
        let gd = load_game_data();
        let mut ps = make_player(&gd, "T".into(), 0, 0);
        let mut log = MessageLog::default();
        // Eru grants WIS at grace thresholds.
        ps.god = 1;
        ps.grace = 25000;
        assert_eq!(god_boons(&ps)[WIS], 2);
        // Melkor grants STR/CON/CHR and penalises INT/WIS.
        ps.god = 4;
        assert_eq!(god_boons(&ps)[STR], 2);
        assert_eq!(god_boons(&ps)[INT], -2);
        // Manwe: feather fall and free action blessings.
        ps.god = 2;
        ps.grace = 8000;
        assert!(god_feather(&ps));
        assert!(!god_free_act(&ps));
        ps.praying = true;
        assert!(god_free_act(&ps));
        assert_eq!(god_speed(&ps), 1);
        // Piety: Yavanna dislikes animal kills while praying, likes the
        // destruction of demons (xtra2.cc:3161-3170).
        ps.god = 5;
        ps.grace = 0;
        ps.praying = true;
        let animal = (0..gd.monster_base_count)
            .find(|&i| gd.monsters[i].has("ANIMAL") && gd.monsters[i].depth >= 3)
            .unwrap();
        god_piety_on_kill(&mut ps, &gd.monsters[animal], &mut log);
        assert!(ps.grace < 0, "grace: {}", ps.grace);
        ps.praying = false;
        let demon = (0..gd.monster_base_count)
            .find(|&i| gd.monsters[i].has("DEMON") && gd.monsters[i].depth >= 3)
            .unwrap();
        ps.grace = 0;
        god_piety_on_kill(&mut ps, &gd.monsters[demon], &mut log);
        assert!(ps.grace > 0, "grace: {}", ps.grace);
    }

    #[test]
    fn gods_cc_helpers_follow_the_original() {
        use crate::birth::make_player;
        use crate::data::load_game_data;
        let gd = load_game_data();
        let mut ps = make_player(&gd, "T".into(), 0, 0);
        // wisdom_scale = stat_ind[WIS] * max / 37 (gods.cc:155).
        ps.stats[WIS] = 3;
        assert_eq!(wisdom_scale(&ps, 4), 0);
        ps.stats[WIS] = 18;
        assert_eq!(wisdom_scale(&ps, 4), stat_index(18) as i32 * 4 / 37);
        ps.stats[WIS] = 40;
        assert_eq!(wisdom_scale(&ps, 4), 4);
        // praying_to (gods.cc:214) requires both the god and the toggle.
        ps.god = 2;
        ps.praying = false;
        assert!(!praying_to(&ps, 2));
        ps.praying = true;
        assert!(praying_to(&ps, 2));
        assert!(!praying_to(&ps, 4));
        assert!(god_fly(&ps) == (ps.grace >= 15000));
        // abandon_god (gods.cc:47) clears god, grace and prayer.
        ps.grace = 12345;
        abandon_god(&mut ps);
        assert_eq!((ps.god, ps.grace, ps.praying), (0, 0, false));
        // inc_piety (gods.cc:28): the overflow guard lands on the same
        // +-300000 rail as set_grace's clamp (the original force-sets the
        // rail value when an addition saturates).
        ps.grace = 299_000;
        ps.grace = (ps.grace + 6000).clamp(-300000, 300000);
        assert_eq!(ps.grace, 300000);
        ps.grace = -299_000;
        ps.grace = (ps.grace - 6000).clamp(-300000, 300000);
        assert_eq!(ps.grace, -300000);
    }

