    #[test]
    fn corruptions_follow_dependencies_and_apply_effects() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let mut ps = crate::birth::make_player(&gd, "Corrupt".into(), 0, 0);
        let mut log = MessageLog::default();
        assert!(!crate::corrupt::can_gain(
            &gd,
            &ps,
            crate::corrupt::CORRUPT_BALROG_FORM
        ));
        crate::corrupt::gain(&mut ps, crate::corrupt::CORRUPT_BALROG_AURA, &mut log);
        crate::corrupt::gain(&mut ps, crate::corrupt::CORRUPT_BALROG_WINGS, &mut log);
        crate::corrupt::gain(&mut ps, crate::corrupt::CORRUPT_BALROG_STRENGTH, &mut log);
        assert!(crate::corrupt::can_gain(
            &gd,
            &ps,
            crate::corrupt::CORRUPT_BALROG_FORM
        ));
        crate::corrupt::gain(&mut ps, crate::corrupt::CORRUPT_BALROG_FORM, &mut log);
        let t = crate::item::Inventory::default().totals_for(&gd, &ps);
        assert!(t.fly && t.sh_fire && t.lite >= 1);
        assert!(crate::corrupt::powers(&ps).contains(&crate::corrupt::PWR_BALROG));
        // Anti-teleportation freezes space outright.
        crate::corrupt::gain(&mut ps, crate::corrupt::CORRUPT_ANTI_TELEPORT, &mut log);
        let t = crate::item::Inventory::default().totals_for(&gd, &ps);
        assert!(t.no_tele);
        // The random pool never offers the vampire chain in this port.
        let troll = gd.races.iter().position(|r| r.name == "Troll").unwrap();
        let troll_ps = crate::birth::make_player(&gd, "Troll".into(), troll, 0);
        assert!(!crate::corrupt::can_gain(
            &gd,
            &troll_ps,
            crate::corrupt::CORRUPT_TROLL_BLOOD
        ));
        assert!(
            crate::corrupt::can_gain(&gd, &troll_ps, crate::corrupt::CORRUPT_VAMPIRE_TEETH)
                == false
        );
        let mut rng = StdRng::seed_from_u64(11);
        for _ in 0..50 {
            let mut fresh = crate::birth::make_player(&gd, "C".into(), 0, 0);
            if let Some(id) = crate::corrupt::gain_random(&gd, &mut fresh, &mut log, &mut rng) {
                assert!(id < crate::corrupt::CORRUPT_VAMPIRE_TEETH);
            }
        }
    }

