    #[test]
    fn fates_roll_and_describe() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let mut rng = StdRng::seed_from_u64(3);
        let mut log = MessageLog::default();
        let mut ps = crate::birth::make_player(&gd, "Fated".into(), 0, 0);
        ps.max_depth = 60;
        let mut saw_no_mortal = false;
        for _ in 0..5000 {
            if ps.fates.len() >= MAX_FATES {
                ps.fates.clear();
            }
            gain_fate(&gd, &mut ps, 0, &mut log, &mut rng);
            saw_no_mortal |= ps.no_mortal;
            if saw_no_mortal {
                break;
            }
        }
        assert!(ps.no_mortal, "the no-mortal fate never surfaced");
        for f in &ps.fates {
            assert!(f.fate > 0);
            if f.fate != FATE_NO_DIE_MORTAL {
                assert!((1..=98).contains(&f.level));
            }
            if f.fate == FATE_FIND_O {
                assert!(f.object > 0 && (f.object as usize) < gd.objects.len());
            }
            if f.fate == FATE_FIND_R {
                assert!((f.monster as usize) < gd.monster_base_count);
            }
            if f.fate == FATE_FIND_A && f.artifact != 0 {
                let a = gd.artifacts.iter().find(|a| a.id == f.artifact).unwrap();
                assert!(!a.flags.iter().any(|x| x == "SPECIAL_GENE"));
            }
            assert!(!fate_desc(&gd, f).is_empty());
        }
        // The artifact picker never hands out guardians' treasures.
        for _ in 0..500 {
            let id = choose_fate_artifact(&gd, 98, &mut rng);
            if id != 0 {
                let a = gd.artifacts.iter().find(|a| a.id == id).unwrap();
                assert!(!a.flags.iter().any(|x| x == "SPECIAL_GENE"));
            }
        }
    }

    #[test]
    fn spirits_stay_in_the_void() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let spirit = gd
            .monsters
            .iter()
            .position(|m| m.has("SPIRIT"))
            .expect("a SPIRIT monster in r_info");
        let mirkwood = gd.dungeon(1);
        let mut rng = StdRng::seed_from_u64(1);
        assert!(!monster_ok_in_dungeon(&gd, spirit, mirkwood, &mut rng));
        let void = gd.dungeon(11);
        // In the Void the SPIRIT gate no longer excludes it; the Void's
        // own R:/M: rules (an OR over SPIRIT/UNDEAD/...) allow it.
        let allowed = (0..20)
            .any(|s| monster_ok_in_dungeon(&gd, spirit, void, &mut StdRng::seed_from_u64(s)));
        assert!(allowed, "spirits must live in the Void");
    }

    #[test]
    fn calc_hitpoints_and_mana_boons_follow_xtra1() {
        let gd = load_game_data();
        let inv = crate::item::Inventory::default();
        let mut ps = test_player(&gd, "Hp");
        ps.level = 10;
        ps.hp_rolls = vec![5; 10];
        ps.stats[CON] = 18; // stat index 15 => adj_con_mhp bonus 3
        ps.max_hp = 0;
        recalc_max_hp(&mut ps, &inv, &gd);
        // 50 rolled + 3 * 10 / 2 CON bonus (xtra1.cc calc_hitpoints).
        assert_eq!(ps.max_hp, 65);
        // The LIFE equipment flag adds 20% per pval (`mhp += mhp *
        // to_l / 5`), not one percent.
        assert_eq!(equip_life_pct(&ps, 1), 13);
        assert_eq!(equip_life_pct(&ps, 0), 0);
        assert_eq!(equip_life_pct(&ps, -1), -13);
        // A disembodied spirit has a single hit point.
        ps.disembodied = true;
        recalc_max_hp(&mut ps, &inv, &gd);
        assert_eq!(ps.max_hp, 1);
        // Never fewer than level + 1 hp and current hp is clamped.
        ps = test_player(&gd, "Hp2");
        ps.hp = 500;
        ps.max_hp = 1;
        recalc_max_hp(&mut ps, &inv, &gd);
        assert!(ps.max_hp >= ps.level as i32 + 1);
        assert!(ps.hp <= ps.max_hp);
        // The MANA flag scales max mana the same 20% per pval.
        let mut ps = test_player(&gd, "Mana");
        ps.max_mana = 100;
        ps.god_mana_boon = 0;
        assert_eq!(equip_mana_pct(&ps, 1), 20);
        assert_eq!(equip_mana_pct(&ps, 5), 100);
        assert_eq!(equip_mana_pct(&ps, -2), -40);
    }

    /// rerate_hp (do_cmd_rerate): the reroll feeds calc_hitpoints, so the
    /// CON term is adj_con_mhp[stat_index(CON)] * level / 2 and the Life
    /// Rating uses the level-50 total.
    #[test]
    fn rerate_hp_rebuilds_max_hp_through_calc_hitpoints() {
        let gd = load_game_data();
        let mut ps = test_player(&gd, "Rerate");
        ps.level = 10;
        ps.stats[CON] = 18;
        ps.hitdie = 5;
        ps.max_hp = 1;
        let mut log = MessageLog::default();
        let mut rng = crate::rng::new_seeded_rng(11);
        rerate_hp(&mut ps, &gd, &mut log, &mut rng);
        let expected = ps.hp_rolls.iter().sum::<i32>()
            + ADJ_CON_MHP[stat_index(ps.stats[CON])] * ps.level as i32 / 2;
        assert_eq!(ps.max_hp, expected.max(ps.level as i32 + 1));
        assert!(ps.hp <= ps.max_hp);
        assert_eq!(ps.hp_planned.len(), 50, "full history kept");
        assert!(log
            .lines
            .iter()
            .any(|l| l.starts_with("Current Life Rating is ")));
        // A low-CON reroll pays less than the same rolls with high CON.
        let rolls_total: i32 = ps.hp_rolls.iter().sum();
        let mut high = ps.clone();
        high.stats[CON] = 40;
        recalc_max_hp(&mut high, &crate::item::Inventory::default(), &gd);
        assert!(high.max_hp > ps.max_hp, "CON must matter per level");
        let _ = rolls_total;
    }

    #[test]
    fn mana_base_and_cumber_gloves_follow_xtra1() {
        let gd = load_game_data();
        let mut inv = crate::item::Inventory::default();
        let idx = gd.classes.iter().position(|c| c.name == "Mage").unwrap();
        let mut ps = crate::birth::make_player(&gd, "Mage".into(), 0, idx);
        ps.stats[INT] = 25;
        ps.stats[WIS] = 10;
        let base = calc_mana(&ps, &gd, &inv);
        assert!(base > 0, "a mage has mana");
        // More levels -> more mana (adj_mag_mana * level / 4).
        ps.level = 20;
        let levelled = calc_mana(&ps, &gd, &inv);
        assert!(levelled > base);
        // Normal gloves sap a quarter of a mage's mana (calc_mana).
        let glove_def = gd
            .objects
            .iter()
            .position(|o| o.tval == crate::data::TV_GLOVES)
            .expect("a glove kind");
        let mut gloves = crate::item::Item::base(&gd, glove_def);
        gloves.pval = 0;
        inv.equip[crate::data::SLOT_HANDS] = Some(gloves);
        assert!(forbid_gloves(&ps));
        assert!(cumber_glove(&ps, &inv, &gd));
        assert_eq!(calc_mana(&ps, &gd, &inv), 3 * levelled / 4);
        // Armour encumbrance subtracts (weight - 200 - Combat)/10 mana.
        let penalty = cumber_armor_penalty(&ps, &inv, &gd);
        assert_eq!(penalty, 0);
        ps.max_mana = 50;
        assert_eq!(effective_max_mana(&ps, &inv, &gd), 50);
    }

    #[test]
    fn mana_school_calc_mana_boosts_high_mana_skill() {
        let gd = load_game_data();
        let inv = crate::item::Inventory::default();
        let idx = gd.classes.iter().position(|c| c.name == "Mage").unwrap();
        let mut ps = crate::birth::make_player(&gd, "Mana".into(), 0, idx);
        ps.stats[INT] = 30;
        let base = calc_mana(&ps, &gd, &inv);
        assert!(base > 0);
        // spells6.cc mana_school_calc_mana: below 35 nothing changes.
        ps.skills
            .insert(crate::skill::SK_MANA, 34 * crate::skill::SKILL_STEP);
        assert_eq!(calc_mana(&ps, &gd, &inv), base);
        // At 35+ the Mana skill adds (skill - 34) percent.
        ps.skills
            .insert(crate::skill::SK_MANA, 40 * crate::skill::SKILL_STEP);
        assert_eq!(calc_mana(&ps, &gd, &inv), base + base * 6 / 100);
    }

    #[test]
    fn calc_mana_applies_eru_and_equipment_before_school() {
        let gd = load_game_data();
        let inv = crate::item::Inventory::default();
        let idx = gd.classes.iter().position(|c| c.name == "Mage").unwrap();
        let mut ps = crate::birth::make_player(&gd, "Eru".into(), 0, idx);
        ps.stats[INT] = 30;
        ps.skills
            .insert(crate::skill::SK_MANA, 40 * crate::skill::SKILL_STEP);
        // Non-Eru baseline: school applies on the base.
        let school_only = calc_mana(&ps, &gd, &inv);
        // Eru's grace percentage is applied BEFORE the Mana-skill percent
        // (xtra1.cc:1568 then mana_school_calc_mana), so the school term
        // multiplies the god bonus as well.
        let base = {
            let mut p = ps.clone();
            p.god = 1;
            p.grace = 35000;
            calc_mana_without_school(&p, &gd, &inv)
        };
        ps.god = 1;
        ps.grace = 35000;
        assert_eq!(
            calc_mana(&ps, &gd, &inv),
            base + base * 6 / 100,
            "school percent includes the Eru bonus"
        );
        assert!(school_only > 0);
    }

    /// The pre-school part of calc_mana (test-only helper mirroring the
    /// original statement order up to mana_school_calc_mana).
    fn calc_mana_without_school(ps: &PlayerState, gd: &GameData, inv: &Inventory) -> i32 {
        let mut msp = ps.skill_scale(crate::skill::SK_MAGIC, 200)
            + adj_mag_mana(ps.stats[INT].max(ps.stats[WIS])) * ps.level.max(0) as i32 / 4;
        if msp != 0 {
            msp += 1;
        }
        msp = msp * ps.mana_mult / 100;
        if let Some(class) = ps.class(gd) {
            msp += msp * class.mana / 100;
        }
        if ps.god == 1 {
            let tmp = ps.grace.clamp(0, 35000) / 100;
            msp += msp * tmp / 1000;
        }
        if msp != 0 && cumber_glove(ps, inv, gd) {
            msp = 3 * msp / 4;
        }
        let mana_pct = inv.totals_for(gd, ps).mana_pct;
        if mana_pct != 0 {
            msp += msp * mana_pct / 5;
        }
        msp - cumber_armor_penalty(ps, inv, gd)
    }

    #[test]
    fn get_pos_player_finds_a_naked_floor_cell() {
        let gd = load_game_data();
        let map = crate::map::blank_pub(crate::map::T_FLOOR);
        let mut rng = crate::rng::new_seeded_rng(11);
        let occupied = HashSet::new();
        let (x, y) = get_pos_player(&gd, &map, (20, 20), &occupied, 5, &mut rng).expect("spot");
        let d = crate::map::pref_distance(20, 20, y, x);
        assert!((2..=5).contains(&d), "distance {d}");
        assert!(map.walkable(&gd, x, y));
        assert!(Map::in_bounds(x, y));
        // Occupied cells are avoided.
        let mut occupied = HashSet::new();
        occupied.insert((x, y));
        let (x2, y2) = get_pos_player(&gd, &map, (20, 20), &occupied, 5, &mut rng).expect("spot");
        assert_ne!((x2, y2), (x, y));
    }

