    #[test]
    fn teleport_to_player_drags_only_awake_tporters() {
        let gd = load_game_data();
        let map = crate::map::blank_pub(crate::map::T_FLOOR);
        let mut rng = crate::rng::new_seeded_rng(9);
        let mut world = bevy::prelude::World::new();
        let tporter = world.spawn(()).id();
        let resistant = world.spawn(()).id();
        let sleeper = world.spawn(()).id();
        let snap = vec![
            // teleport_to_player (spells1.cc:364): only awake SF_TPORT
            // monsters without RES_TELE are dragged.
            crate::item::TportSnap {
                entity: tporter,
                x: 11,
                y: 10,
                level: 100,
                tport: true,
                res_tele: false,
                awake: true,
            },
            crate::item::TportSnap {
                entity: resistant,
                x: 10,
                y: 11,
                level: 100,
                tport: true,
                res_tele: true,
                awake: true,
            },
            crate::item::TportSnap {
                entity: sleeper,
                x: 9,
                y: 10,
                level: 100,
                tport: true,
                res_tele: false,
                awake: false,
            },
        ];
        let occupied = HashSet::new();
        let out = crate::item::plan_tport_drags(
            &gd,
            &map,
            (10, 10),
            (20, 20),
            &snap,
            &occupied,
            &mut rng,
        );
        assert_eq!(out.len(), 1, "{out:?}");
        assert_eq!(out[0].0, tporter);
    }

