    #[test]
    fn poly_monster_at_never_picks_uniques() {
        let gd = load_game_data();
        let mut rng = crate::rng::new_seeded_rng(21);
        // poly_r_idx: a unique caster keeps its race.
        let unique = gd.monsters.iter().position(|m| m.unique).unwrap();
        let mut m = test_monster(unique, 50);
        m.max_hp = 50;
        assert!(poly_monster_at(&gd, &mut m, 10, &mut rng).is_none());
        // A normal monster becomes a non-unique race from the weighted
        // roll, with its hp clamped to the new maximum.
        let normal = gd
            .monsters
            .iter()
            .position(|d| !d.unique && d.depth >= 1)
            .unwrap();
        let mut m = test_monster(normal, 50);
        m.max_hp = 50;
        if poly_monster_at(&gd, &mut m, 40, &mut rng).is_some() {
            assert!(!gd.monsters[m.def].unique);
            assert!(m.hp <= m.max_hp);
            assert!(m.max_hp >= 1);
        }
    }

