    #[test]
    fn earthquake_shakes_the_area() {
        let gd = load_game_data();
        let mut map = crate::map::blank_pub(crate::map::T_FLOOR);
        // A ring of tunnelable rock to collapse.
        for dy in -4..=4 {
            for dx in -4..=4 {
                if dx * dx + dy * dy <= 16 && (dx, dy) != (0, 0) {
                    map.set_terrain(20 + dx, 20 + dy, crate::map::T_GRANITE);
                }
            }
        }
        let mut log = MessageLog::default();
        let mut rng = crate::rng::new_seeded_rng(2);
        earthquake(&mut map, &gd, 20, 20, 4, &mut log, &mut rng);
        let floors = (-4..=4)
            .flat_map(|dy| (-4..=4).map(move |dx| (dx, dy)))
            .filter(|(dx, dy)| *dx * dx + *dy * *dy <= 16 && (*dx, *dy) != (0, 0))
            .filter(|(dx, dy)| map.terrain_at(20 + dx, 20 + dy) == crate::map::T_FLOOR)
            .count();
        assert!(floors > 0, "the quake opened some rock");
        assert!(log.lines.iter().any(|l| l.contains("dungeon shakes")));
    }

