    #[test]
    fn lite_radius_matches_calc_torch() {
        let gd = load_game_data();
        let mut inv = crate::item::Inventory::default();
        let mut ps = test_player(&gd, "Lite");
        assert_eq!(player_lite(&ps, &inv, &gd), 0);
        // A permanent LITE3 (Feanorian Lamp) contributes 3.
        let lamp_def = gd
            .objects
            .iter()
            .position(|o| {
                o.tval == crate::data::TV_LITE
                    && o.flags.iter().any(|f| f == "LITE3")
                    && !o.flags.iter().any(|f| f == "FUEL_LITE")
            })
            .expect("a permanent LITE3");
        inv.equip[crate::data::SLOT_LITE] = Some(crate::item::Item::base(&gd, lamp_def));
        assert_eq!(player_lite(&ps, &inv, &gd), 3);
        // A fueled torch adds its LITE1; a burnt-out FUEL_LITE stops
        // glowing (xtra1.cc:1856).
        let torch_def = gd
            .objects
            .iter()
            .position(|o| {
                o.tval == crate::data::TV_LITE
                    && o.flags.iter().any(|f| f == "LITE1")
                    && o.flags.iter().any(|f| f == "FUEL_LITE")
            })
            .expect("a torch");
        let mut torch = crate::item::Item::base(&gd, torch_def);
        torch.fuel = 100;
        inv.equip[crate::data::SLOT_LITE] = Some(torch);
        assert_eq!(player_lite(&ps, &inv, &gd), 1);
        inv.equip[crate::data::SLOT_LITE].as_mut().unwrap().fuel = 0;
        assert_eq!(player_lite(&ps, &inv, &gd), 0);
        inv.equip[crate::data::SLOT_LITE] = None;
        // Temporary light adds 2, a holy aura 1, and the total caps at 5
        // *before* Varda's +1 (calc_torch then calc_torch_gods).
        ps.tim_lite = 10;
        assert_eq!(player_lite(&ps, &inv, &gd), 2);
        ps.holy = 10;
        assert_eq!(player_lite(&ps, &inv, &gd), 3);
        // The cap (5) is applied before Varda's +1.
        inv.equip[crate::data::SLOT_LITE] = Some(crate::item::Item::base(&gd, lamp_def));
        ps.tim_lite = 10;
        ps.holy = 10;
        ps.god = 7; // Varda
        assert_eq!(player_lite(&ps, &inv, &gd), 6);
        // The wilderness overview caps the radius at 3.
        ps.wild_mode = true;
        assert_eq!(player_lite(&ps, &inv, &gd), 3);
        // Running with view_reduce_lite caps it at 1.
        assert_eq!(player_lite_ex(&ps, &inv, &gd, true, true), 1);
        // A corruption's own glow (Balrog aura TR_LITE1) lights the dark
        // without any worn source: the intrinsic minimum is 1.
        inv.equip[crate::data::SLOT_LITE] = None;
        ps.wild_mode = false;
        ps.tim_lite = 0;
        ps.holy = 0;
        ps.god = 0;
        let mut log = MessageLog::default();
        crate::corrupt::gain(&mut ps, crate::corrupt::CORRUPT_BALROG_AURA, &mut log);
        assert_eq!(player_lite(&ps, &inv, &gd), 1);
    }

    #[test]
    fn blow_archery_and_style_branches_follow_xtra1() {
        let gd = load_game_data();
        let mut inv = crate::item::Inventory::default();
        let mage = gd.classes.iter().position(|c| c.name == "Mage").unwrap();
        let mut ps = crate::birth::make_player(&gd, "Blows".into(), 0, mage);
        // A Mage has no AB_MAX_BLOW abilities (a Warrior starts with both).
        assert_eq!(extra_blows_ability(&ps), 0);
        ps.abilities.push(crate::skill::AB_EXTRA_BLOW1);
        assert_eq!(extra_blows_ability(&ps), 1);
        ps.abilities.push(crate::skill::AB_EXTRA_BLOW2);
        assert_eq!(extra_blows_ability(&ps), 2);
        // Monk empty hands: 1 + ability + one blow per skill cutoff.
        ps.melee_style = crate::skill::SK_HAND;
        ps.skills.insert(crate::skill::SK_HAND, 30_000);
        assert!(monk_empty_hands(&inv));
        assert!(!monk_heavy_armor(&ps, &inv, &gd));
        assert_eq!(num_blows(&ps, &inv, &gd), 1 + 2 + 3);
        // Bear form ignores AB_MAX_BLOW (xtra1.cc:3663) and caps at 6.
        ps.melee_style = crate::skill::SK_BEAR;
        ps.skills.insert(crate::skill::SK_BEAR, 0);
        assert_eq!(num_blows(&ps, &inv, &gd), 2);
        ps.skills.insert(crate::skill::SK_BEAR, 25_000);
        assert_eq!(num_blows(&ps, &inv, &gd), 6);
        // Weapon mastery requires every wielded weapon to share a type.
        let sword = gd.objects.iter().position(|o| o.tval == crate::data::TV_SWORD).unwrap();
        let axe = gd.objects.iter().position(|o| o.tval == crate::data::TV_AXE).unwrap();
        inv.equip[crate::data::SLOT_WEAPON] = Some(crate::item::Item::base(&gd, sword));
        assert_eq!(weaponmastery_skill(&ps, &inv, &gd), Some(crate::skill::SK_SWORD));
        inv.equip[crate::data::SLOT_WEAPON2] = Some(crate::item::Item::base(&gd, axe));
        assert_eq!(weaponmastery_skill(&ps, &inv, &gd), None);
        // Archery picks the skill of the wielded launcher (xtra1.cc
        // get_archery_skill): the sval/10 group selects the bow skill.
        let bow = gd
            .objects
            .iter()
            .position(|o| o.tval == crate::data::TV_BOW && o.sval / 10 == 1)
            .expect("a long/short bow");
        inv.equip[crate::data::SLOT_BOW] = Some(crate::item::Item::base(&gd, bow));
        assert_eq!(archery_skill(&inv, &gd), Some(crate::skill::SK_BOW));
        // Stun lowers the raw to-hit, which BTH_PLUS_ADJ triples.
        ps.melee_style = crate::skill::SK_MASTERY;
        ps.stun = 0;
        let fresh = player_hit_chance(&ps, &inv, &gd);
        ps.stun = 10;
        assert_eq!(player_hit_chance(&ps, &inv, &gd), fresh - 5 * 3);
        ps.stun = 60;
        assert_eq!(player_hit_chance(&ps, &inv, &gd), fresh - 20 * 3);
    }

