    #[test]
    fn fate_roll_respects_luck_and_dump_lists_them() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let mut message_log = MessageLog::default();
        let mut rng = StdRng::seed_from_u64(11);
        for _ in 0..300 {
            let mut ps = crate::birth::make_player(&gd, "Lucky".into(), 0, 0);
            gain_fate(&gd, &mut ps, 1, &mut message_log, &mut rng);
            assert!(!ps.fates.is_empty());
            // luck > 0 rules out the death fate (xtra1.cc gain_fate's
            // rand_int(17) branch).
            for f in &ps.fates {
                assert_ne!(f.fate, FATE_DIE, "lucky fates never die");
            }
        }
        let mut ps = crate::birth::make_player(&gd, "Fate".into(), 0, 0);
        message_log.lines.clear();
        gain_fate(&gd, &mut ps, 1, &mut message_log, &mut rng);
        assert!(message_log.lines.iter().any(|l| l.contains("prophecy")));
        // Unknown fates are hidden behind the warning line (dump_fates).
        let dump = dump_fates(&gd, &ps);
        assert!(dump.contains("You do not know all of your fate."));
        for f in ps.fates.iter_mut() {
            f.know = true;
        }
        let dump = dump_fates(&gd, &ps);
        assert!(!dump.contains("do not know"));
        assert!(dump.contains("fated") || dump.contains("may") || dump.contains("may "));
    }

    #[test]
    fn status_setters_follow_xtra2() {
        let gd = load_game_data();
        let mut ps = test_player(&gd, "Status");
        let mut log = MessageLog::default();
        macro_rules! check {
            ($set:expr, $field:ident, $act:expr, $deact:expr) => {{
                let before = log.lines.len();
                assert!($set(&mut ps, 7, &mut log));
                assert_eq!(ps.$field, 7);
                assert!(log.lines.iter().skip(before).any(|l| l == $act), "{}", $act);
                let before = log.lines.len();
                assert!($set(&mut ps, 0, &mut log));
                assert_eq!(ps.$field, 0);
                assert!(log.lines.iter().skip(before).any(|l| l == $deact), "{}", $deact);
            }};
        }
        check!(set_blind, blind, "You are blind!", "You can see again.");
        check!(set_lite, tim_lite, "You suddenly seem brighter!", "You are no longer bright.");
        check!(set_confused, confuse, "You are confused!", "You feel less confused now.");
        check!(set_poisoned, poison, "You are poisoned!", "You are no longer poisoned.");
        check!(set_afraid, fear, "You are terrified!", "You feel bolder now.");
        check!(set_paralyzed_aux, paralyze, "You are paralyzed!", "You can move again.");
        check!(set_image, image, "Oh, wow! Everything looks so cosmic now!", "You can see clearly again.");
        check!(set_light_speed, lightspeed, "You feel as if time has stopped!", "You feel time returning to its normal rate.");
        check!(set_slow, slow, "You feel yourself moving slower!", "You feel yourself speed up.");
        check!(set_hero, hero, "You feel like a hero!", "The heroism wears off.");
        check!(set_shero, shero, "You feel like a killing machine!", "You feel less berserk.");
        check!(set_protevil, protevil, "You feel safe from evil!", "You no longer feel safe from evil.");
        check!(set_shadow, tim_wraith, "You leave the physical world and turn into a wraith-being!", "You feel opaque.");
        check!(set_invuln, invuln, "Invulnerability!", "The invulnerability wears off.");
        check!(set_tim_esp, esp_timer, "You feel your consciousness expand!", "Your consciousness contracts again.");
        check!(set_tim_invis, tim_invis, "Your eyes feel very sensitive!", "Your eyes feel less sensitive.");
        check!(set_tim_infra, tim_infra, "Your eyes begin to tingle!", "Your eyes stop tingling.");
        check!(set_oppose_acid, oppose_acid, "You feel resistant to acid!", "You feel less resistant to acid.");
        check!(set_oppose_elec, oppose_elec, "You feel resistant to electricity!", "You feel less resistant to electricity.");
        check!(set_oppose_fire, oppose_fire, "You feel resistant to fire!", "You feel less resistant to fire.");
        check!(set_oppose_cold, oppose_cold, "You feel resistant to cold!", "You feel less resistant to cold.");
        check!(set_oppose_pois, oppose_pois, "You feel resistant to poison!", "You feel less resistant to poison.");
        check!(set_strike, strike, "You feel very accurate.", "You are no longer very accurate.");
        check!(set_oppose_cc, oppose_cc, "You feel protected against raw chaos.", "You are no longer protected against chaos.");
        check!(set_tim_precognition, precog_timer, "You feel able to predict the future.", "You feel less able to predict the future.");
        check!(set_absorb_soul, absorb_soul, "You start absorbing the souls of your foes.", "You stop absorbing the souls of dead foes.");
        check!(set_disrupt_shield, disrupt_shield, "You feel invulnerable.", "You are more vulnerable.");
        check!(set_prob_travel, prob_travel, "You feel instable.", "You are more stable.");
        check!(set_no_breeders, no_breeders, "You feel an anti-sexual aura.", "You no longer feel an anti-sexual aura.");
        check!(set_tim_ffall, tim_ffall, "You feel very light.", "You are suddenly heavier.");
        check!(set_tim_fly, tim_fly, "You feel able to reach the clouds.", "You are suddenly a lot heavier.");
        check!(set_tim_reflect, tim_reflect, "You start reflecting the world around you.", "You stop reflecting.");
        // Parameter-carrying setters.
        assert!(set_shield(&mut ps, 5, 20, &mut log));
        assert_eq!((ps.shield, ps.shield_power), (5, 20));
        assert!(set_shield(&mut ps, 0, 20, &mut log));
        assert_eq!((ps.shield, ps.shield_power), (0, 0));
        assert!(set_project(&mut ps, 5, "FIRE", 20, 2, &mut log));
        assert_eq!(
            (ps.tim_project, ps.tim_project_gf.as_str(), ps.tim_project_dam, ps.tim_project_rad),
            (5, "FIRE", 20, 2)
        );
        assert!(set_project(&mut ps, 0, "FIRE", 20, 2, &mut log));
        assert_eq!(ps.tim_project, 0);
        assert!(set_invis(&mut ps, 5, 30, &mut log));
        assert_eq!((ps.invis_turns, ps.invis_power), (5, 30));
        assert!(set_invis(&mut ps, 0, 30, &mut log));
        assert_eq!(ps.invis_power, 0);
        assert!(set_tim_regen(&mut ps, 5, 12, &mut log));
        assert_eq!((ps.tim_regen, ps.tim_regen_pow), (5, 12));
        assert!(set_tim_regen(&mut ps, 0, 12, &mut log));
        assert_eq!((ps.tim_regen, ps.tim_regen_pow), (0, 0));
        assert!(set_fast(&mut ps, 5, 10, &mut log));
        assert_eq!((ps.fast, ps.speed_factor), (5, 10));
        assert!(set_fast(&mut ps, 0, 10, &mut log));
        assert_eq!((ps.fast, ps.speed_factor), (0, 0));
        assert!(set_tim_thunder(&mut ps, 5, 3, 4, &mut log));
        assert_eq!((ps.tim_thunder, ps.thunder_dd, ps.thunder_ds), (5, 3, 4));
        assert!(set_tim_thunder(&mut ps, 0, 3, 4, &mut log));
        assert_eq!((ps.tim_thunder, ps.thunder_dd, ps.thunder_ds), (0, 0, 0));
        set_grace(&mut ps, 400000);
        assert_eq!(ps.grace, 300000);
        set_grace(&mut ps, -400000);
        assert_eq!(ps.grace, -300000);
        assert!(set_parasite(&mut ps, 5, 3, &mut log));
        assert_eq!(ps.parasite, Some((3, 5)));
        assert!(set_parasite(&mut ps, 0, 3, &mut log));
        assert_eq!(ps.parasite, None);
        // Paralysis does not accumulate and decays through dec_paralyzed.
        assert!(set_paralyzed(&mut ps, 7, &mut log));
        assert!(!set_paralyzed(&mut ps, 20, &mut log));
        assert_eq!(ps.paralyze, 7);
        assert!(!dec_paralyzed(&mut ps, &mut log));
        assert_eq!(ps.paralyze, 6);
        // Roots, poison, thunder and the tiered cut/stun setters.
        assert!(set_roots(&mut ps, 5, 12, 30, &mut log));
        assert_eq!((ps.tim_roots, ps.tim_roots_ac, ps.tim_roots_dam), (5, 12, 30));
        assert!(set_roots(&mut ps, 0, 12, 30, &mut log));
        assert_eq!(ps.tim_roots, 0);
        assert!(set_tim_poison(&mut ps, 5, &mut log));
        assert_eq!(ps.tim_poison, 5);
        assert!(set_tim_poison(&mut ps, 0, &mut log));
        assert_eq!(ps.tim_poison, 0);
        let mut rng = crate::rng::current();
        set_stun_full(&gd, &mut ps, 10, None, &mut log, &mut rng);
        assert_eq!(ps.stun, 10);
        assert!(log.lines.iter().any(|l| l == "You have been stunned."));
        set_stun_full(&gd, &mut ps, 0, None, &mut log, &mut rng);
        assert_eq!(ps.stun, 0);
        assert!(log.lines.iter().any(|l| l == "You are no longer stunned."));
        set_cut_full(&gd, &mut ps, 15, None, &mut log, &mut rng);
        assert_eq!(ps.cut, 15);
        assert!(log.lines.iter().any(|l| l == "You have been given a light cut."));
        set_cut_full(&gd, &mut ps, 0, None, &mut log, &mut rng);
        assert_eq!(ps.cut, 0);
        assert!(log.lines.iter().any(|l| l == "You are no longer bleeding."));
        // Clamping to [0, 10000] like set_simple_field.
        assert!(set_image(&mut ps, 20000, &mut log));
        assert_eq!(ps.image, 10000);
        set_image(&mut ps, 0, &mut log);
        ps.blessed = 1;
        set_blessed(&mut ps, 0, &mut log);
        assert_eq!(ps.blessed, 0);
        ps.tim_deadly = 1;
        set_tim_deadly(&mut ps, 0, &mut log);
        assert_eq!(ps.tim_deadly, 0);
        ps.tim_poison = 1;
        set_tim_poison(&mut ps, 0, &mut log);
        assert_eq!(ps.tim_poison, 0);
    }

    #[test]
    fn kill_experience_follows_mon_take_hit() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let def = gd
            .monsters
            .iter()
            .find(|m| m.exp > 0 && m.depth > 0)
            .expect("a monster with experience");
        let mut ps = test_player(&gd, "Exp");
        ps.level = 10;
        ps.max_plv = 10;
        ps.exp_frac = 0;
        let total = def.exp.max(0) as u64 * def.depth.max(1) as u64;
        let (exp, frac) = kill_experience(def, &ps);
        assert_eq!(exp, total / 10);
        assert_eq!(u64::from(frac), (total % 10) * 0x10000 / 10);
        // The fraction always stays inside its 16 bits.
        ps.exp_frac = 0xFFFF;
        let (exp2, frac2) = kill_experience(def, &ps);
        assert!(exp2 == exp || exp2 == exp + 1);
        assert!(frac2 < 0x10000);
        // gain_exp adds the full amount (check_experience may level us).
        let mut log = MessageLog::default();
        let mut rng = StdRng::seed_from_u64(5);
        let before = ps.exp;
        gain_exp(&mut ps, 1000, &mut log, &mut rng);
        assert_eq!(ps.exp, before + 1000);
        assert!(ps.level >= 10);
    }

