    #[test]
    fn weight_limit_and_luck_follow_xtra1() {
        let gd = load_game_data();
        let mut ps = test_player(&gd, "Weight");
        // The carrying capacity is ten times adj_str_wgt[STR].
        ps.stats[STR] = 10; // stat index 7 => 12
        assert_eq!(weight_limit(&ps), 1200);
        ps.stats[STR] = 18; // stat index 15 => 20
        assert_eq!(weight_limit(&ps), 2000);
        // luck() maps luck_cur (clamped to +-30) onto [min, max];
        // luck 0 is the midpoint of the range.
        assert_eq!(luck_range(0, -10, 10), 0);
        assert_eq!(luck_range(30, -10, 10), 10);
        assert_eq!(luck_range(60, -10, 10), 10);
        assert_eq!(luck_range(-60, -10, 10), -10);
        assert_eq!(luck_range(0, 0, 100), 50);
        assert_eq!(luck_range(-30, 0, 100), 0);
    }

    #[test]
    fn race_flags_union_follows_xtra1() {
        let gd = load_game_data();
        // A race's own player flags are part of the union.
        let (race, flag) = gd
            .races
            .iter()
            .find_map(|r| {
                r.player_flags
                    .first()
                    .map(|f| (r.name.clone(), f.clone()))
            })
            .expect("a race with player flags");
        let mut ps = test_player(&gd, "Flags");
        ps.race_name = race;
        assert!(player_has_flag(&gd, &ps, &flag));
        // A class's player flags too (Rogue has EASE_STEAL).
        let mut ps = crate::birth::make_player(
            &gd,
            "Rogue".into(),
            0,
            gd.classes.iter().position(|c| c.name == "Rogue").unwrap(),
        );
        assert!(player_has_flag(&gd, &ps, "EASE_STEAL"));
        // The vampire corruption adds its flags on top.
        ps.race_name = "Human".to_string();
        ps.subrace = 0;
        crate::corrupt::gain(
            &mut ps,
            crate::corrupt::CORRUPT_VAMPIRE_TEETH,
            &mut MessageLog::default(),
        );
        assert!(player_has_flag(&gd, &ps, "UNDEAD"));
    }

    #[test]
    fn drop_from_wild_leaves_the_overview() {
        let gd = load_game_data();
        let mut ps = test_player(&gd, "Wild");
        let mut turn = TurnState::default();
        ps.wild_mode = true;
        ps.depth = 0;
        drop_from_wild(&mut ps, &mut turn, (7, 9));
        assert!(!ps.wild_mode);
        assert_eq!((ps.wild_x, ps.wild_y), (7, 9));
        assert!(matches!(turn.pending, Some(Goto::Wild(7, 9))));
        // Already off the overview: nothing happens.
        let mut turn = TurnState::default();
        drop_from_wild(&mut ps, &mut turn, (1, 1));
        assert!(turn.pending.is_none());
    }

    #[test]
    fn wish_resolution_follows_xtra2() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let mut rng = StdRng::seed_from_u64(9);
        let ps = test_player(&gd, "Wish");
        let mut created = HashSet::new();
        assert_eq!(clean_wish_name("  A   Long   Sword "), "a long sword");
        assert!(matches!(
            make_wish(&gd, &ps, "  Long   Sword ", &mut created, &mut rng),
            Wish::Object(_)
        ));
        // Wishing for a wish is refused (xtra2.cc:5217).
        assert!(matches!(
            make_wish(&gd, &ps, "wish", &mut created, &mut rng),
            Wish::Refused
        ));
        // Monster wishes carry a status prefix; uniques are never granted.
        let base = gd
            .monsters
            .iter()
            .position(|m| {
                !m.name.is_empty()
                    && !m.unique
                    && !m.has("SPECIAL_GENE")
                    && !m.has("NEVER_GENE")
            })
            .unwrap();
        let name = gd.monsters[base].name.to_lowercase();
        match make_wish(&gd, &ps, &format!("friendly {}", name), &mut created, &mut rng) {
            Wish::Monster { def, status, .. } => {
                assert_eq!(def, base);
                assert_eq!(status, WISH_FRIEND);
            }
            _ => panic!("expected a monster"),
        }
        // A made-up name finds nothing.
        assert!(matches!(
            make_wish(&gd, &ps, "glaurung's rubber duck", &mut created, &mut rng),
            Wish::Refused
        ));
    }
