    #[test]
    fn gf_side_effects_chaos_nuke_disintegrate_force() {
        let gd = load_game_data();
        let mut rng = crate::rng::current();
        let dog = gd
            .monsters
            .iter()
            .find(|m| m.name == "Blink dog")
            .expect("blink dog");
        // CHAOS polymorphs (unique/quest immune handled by callers).
        let mut poly_seen = false;
        for _ in 0..40 {
            let e = gf_monster_effect(dog, "CHAOS", 10, 10, true, &mut rng);
            poly_seen |= e.poly;
        }
        assert!(poly_seen);
        // NUKE polymorphs roughly one in three.
        let mut nuke_poly = 0;
        for _ in 0..60 {
            if gf_monster_effect(dog, "NUKE", 10, 10, true, &mut rng).poly {
                nuke_poly += 1;
            }
        }
        assert!(nuke_poly > 0);
        // Player-cast FORCE pushes instead of stunning; monster-cast stuns.
        let pf = gf_monster_effect(dog, "FORCE", 10, 10, true, &mut rng);
        assert_eq!(pf.push, 2);
        assert_eq!(pf.stun, 0);
        let mf = gf_monster_effect(dog, "FORCE", 10, 10, false, &mut rng);
        assert_eq!(mf.push, 0);
        assert!(mf.stun > 0);
        // DISINTEGRATE doubles against rock-creation monsters.
        let uruk = gd
            .monsters
            .iter()
            .find(|m| m.has("HURT_ROCK"))
            .expect("rock monster");
        let d = gf_monster_effect(uruk, "DISINTEGRATE", 100, 50, true, &mut rng);
        assert_eq!(d.dam, 200);
    }

