    #[test]
    fn force_maxhp_monsters_take_the_maximum_roll() {
        let gd = load_game_data();
        let def = gd
            .monsters
            .iter()
            .find(|m| m.has("FORCE_MAXHP"))
            .expect("FORCE_MAXHP monster");
        let d = crate::data::Dice::parse(&def.hp).expect("hdice");
        let expected = d.count * d.sides + d.bonus;
        let mut rng = crate::rng::current();
        for _ in 0..50 {
            assert_eq!(roll_monster_hp(def, &mut rng), expected);
        }
        // A random-HP monster varies (almost surely within 50 rolls).
        let plain = gd
            .monsters
            .iter()
            .find(|m| {
                !m.has("FORCE_MAXHP")
                    && crate::data::Dice::parse(&m.hp)
                        .map(|d| d.count * d.sides > 1)
                        .unwrap_or(false)
            })
            .expect("random-hp monster");
        let mut seen = std::collections::HashSet::new();
        for _ in 0..200 {
            seen.insert(roll_monster_hp(plain, &mut rng));
        }
        assert!(seen.len() > 1, "plain hp never varied: {seen:?}");
    }

    #[test]
    fn no_recall_out_cancels_the_recall_when_it_fires() {
        let gd = load_game_data();
        let d = gd
            .dungeons
            .iter()
            .find(|d| d.has("NO_RECALL_OUT"))
            .expect("NO_RECALL_OUT dungeon")
            .clone();
        let class = gd.classes.iter().position(|c| c.name == "Warrior").unwrap();
        let race = gd.races.iter().position(|r| r.name == "Human").unwrap();
        let mut ps = make_player(&gd, "T".into(), race, class);
        ps.dungeon = d.id;
        ps.depth = d.mindepth.max(1);
        ps.word_recall = 1;
        let mut turn = TurnState::default();
        let mut log = MessageLog::default();
        assert!(!tick_word_recall(&gd, &mut ps, &mut turn, &mut log));
        assert!(
            log.lines.iter().any(|m| m.contains("cannot recall")),
            "no recall message: {:?}",
            log.lines
        );
        assert!(turn.pending.is_none());
        // The Void and the Nether Realm also refuse recall (q_ultrag.cc
        // recall hook: "The portal to Arda is closed.").
        let race = gd.races.iter().position(|r| r.name == "Human").unwrap();
        let mut void_ps = make_player(&gd, "T".into(), race, class);
        void_ps.dungeon = 11; // DUNGEON_VOID
        void_ps.depth = 128;
        let mut vlog = MessageLog::default();
        assert!(recall_blocked(&gd, &void_ps, &mut vlog));
        assert!(vlog
            .lines
            .iter()
            .any(|m| m.contains("portal to Arda is closed")));
    }

