    #[test]
    fn levels_artifacts_gain_realms_and_flags() {
        let gd = load_game_data();
        assert_eq!(FLAGS_GROUPS.len(), 12);
        // A LEVELS artifact gets its base level and one realm point when
        // created (object2.cc:3907).
        let mut rng = crate::rng::current();
        let narthanc = gd
            .artifacts
            .iter()
            .find(|a| a.name == "'Narthanc'")
            .expect("Narthanc");
        let def = gd.object_by_tval_sval(narthanc.tval, narthanc.sval).unwrap();
        let mut it = Item::base(&gd, def);
        it.artifact = narthanc.id;
        init_levels_artifact(&gd, &gd.objects[def], &mut it);
        assert!(item::item_flags(&gd, &it).iter().any(|f| *f == "LEVELS"));
        assert!(it.elevel >= 1 && it.pval2 >= 1, "elevel {} pval2 {}", it.elevel, it.pval2);

        // With points, gain_flag_group buys a realm and sets its bit.
        it.pval2 = 100;
        let known = std::collections::HashSet::new();
        let mut log = MessageLog::default();
        let before = it.pval3;
        gain_flag_group(&gd, &mut it, &known, &mut rng, &mut log);
        assert_ne!(it.pval3, before, "no group gained");
        assert!(it.pval2 < 100, "points not spent");
        assert!(
            log.lines.iter().any(|m| m.contains("realm")),
            "no realm message: {:?}",
            log.lines
        );

        // gain_flag_group_flag adds a member flag of an owned realm.
        let mut got = false;
        for _ in 0..50 {
            if gain_flag_group_flag(&gd, &mut it, &known, &mut rng, &mut log) {
                got = true;
                break;
            }
        }
        assert!(got, "no realm power gained");
        assert!(
            log.lines.iter().any(|m| m.contains("new power")),
            "no power message: {:?}",
            log.lines
        );
    }
    #[test]
    fn dungeon_adjust_level_ranges_match_d_info() {
        let gd = load_game_data();
        // Angband (id 3): ADJUST_LEVEL_1 + ADJUST_LEVEL_1_2 => [d/2, d].
        assert_eq!(dungeon_adjust_level(gd.dungeon(3), 100), Some((50, 100)));
        // Nether Realm (id 6) and the Void (id 11) double the level.
        assert_eq!(dungeon_adjust_level(gd.dungeon(6), 10), Some((20, 20)));
        assert_eq!(dungeon_adjust_level(gd.dungeon(11), 90), Some((45, 90)));
        // A plain dungeon never adjusts.
        assert_eq!(dungeon_adjust_level(gd.dungeon(0), 10), None);
    }

    #[test]
    fn monster_desc_handles_uniques_gender_and_pets() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let ps = crate::birth::make_player(&gd, "Test".into(), 0, 0);
        let mut rng = StdRng::seed_from_u64(7);
        let sauron = gd
            .monster_by_name("Sauron, the Sorcerer")
            .expect("Sauron");
        let m = test_monster(sauron, 100);
        // A visible unique is named without an article.
        assert_eq!(
            monster_desc(&gd, &ps, sauron, Some(&m), true, 0, &mut rng),
            "Sauron, the Sorcerer"
        );
        // A non-unique visible monster gets "the".
        let urias = gd.monster_by_name("Filthy street urchin").expect("urchin");
        let m = test_monster(urias, 100);
        let desc = monster_desc(&gd, &ps, urias, Some(&m), true, 0, &mut rng);
        assert!(desc.starts_with("the ") || desc.starts_with("a "), "{desc}");
        // The unseen pronoun mode yields a pronoun.
        let m = test_monster(urias, 100);
        let pron = monster_desc(&gd, &ps, urias, Some(&m), false, 0x20, &mut rng);
        assert!(matches!(pron.as_str(), "he" | "she" | "it"), "{pron}");
        assert_eq!(cap_first("orc hits you."), "Orc hits you.");
    }

    #[test]
    fn deincarnate_restores_the_possessor_race() {
        use rand::rngs::StdRng;
        use rand::SeedableRng;
        let gd = load_game_data();
        let soul = gd
            .monster_by_name("Novice possessor (soul)")
            .expect("soul");
        let body = gd.monster_by_name("Filthy street urchin").expect("body");
        let mut m = test_monster(body, 100);
        m.possessor = Some(soul);
        let mut extra = MonsterExtra::default();
        let mut log = MessageLog::default();
        let mut rng = StdRng::seed_from_u64(3);
        assert!(deincarnate_monster(
            &gd,
            &mut m,
            Some(&mut extra),
            &mut log,
            &mut rng
        ));
        assert_eq!(m.def, soul);
        assert!(m.possessor.is_none());
        assert_eq!(m.hp, m.max_hp);
        // A normal monster is not deincarnated.
        let mut plain = test_monster(body, 100);
        assert!(!deincarnate_monster(
            &gd,
            &mut plain,
            None,
            &mut log,
            &mut rng
        ));
    }

    #[test]
    fn level_persists_only_save_extension_depths() {
        let gd = load_game_data();
        use crate::save::LevelKey;
        // Only Mount Doom 99 carries the "@:14:S:mdm" save extension.
        assert!(level_persists(
            &gd,
            LevelKey::Dungeon {
                dungeon: 5,
                depth: 99
            }
        ));
        assert!(!level_persists(
            &gd,
            LevelKey::Dungeon {
                dungeon: 5,
                depth: 14
            }
        ));
        assert!(!level_persists(
            &gd,
            LevelKey::Dungeon {
                dungeon: 4,
                depth: 10
            }
        ));
        // Quest, wilderness and overview snapshots (old saves may carry
        // them) are always regenerated: a stale store entry must never be
        // restored.
        assert!(!level_persists(&gd, LevelKey::Quest(3)));
        assert!(!level_persists(&gd, LevelKey::Wild(10, 10)));
        assert!(!level_persists(&gd, LevelKey::Overview));
    }

    #[test]
    fn decay_object_pval_follows_dungeon_cc() {
        let gd = load_game_data();
        let meat = gd.object_by_name("raw meat").expect("raw meat");
        let mut rng = crate::rng::new_seeded_rng(3);
        let mut it = crate::item::Item::base(&gd, meat);
        it.pval = 3;
        it.timeout = 5;
        // Normal: one point per turn; timeout counts down while below the
        // item weight (10), stopping at zero.
        assert!(!decay_object_pval(&gd, &mut it, false, false, &mut rng));
        assert_eq!(it.pval, 2);
        assert_eq!(it.timeout, 4);
        // Hot: two points, and the last point destroys the meat.
        assert!(decay_object_pval(&gd, &mut it, true, false, &mut rng));
        assert_eq!(it.pval, 0);
        assert_eq!(it.timeout, 3);
        // A cold climate decays at most one point per turn and never
        // touches the timeout while it is above the item weight.
        let mut it = crate::item::Item::base(&gd, meat);
        it.pval = 1;
        it.timeout = 20; // not below the weight: no timeout change
        let before = it.pval;
        let destroyed = decay_object_pval(&gd, &mut it, false, true, &mut rng);
        assert!(it.pval == before || it.pval == before - 1);
        assert_eq!(destroyed, it.pval <= 0);
        assert_eq!(it.timeout, 20);
        // Without the DECAY flag nothing happens.
        let potion = gd.object_by_name("potion of healing").unwrap_or_else(|| {
            gd.objects
                .iter()
                .position(|o| o.tval == crate::data::TV_POTION)
                .expect("a potion")
        });
        let mut pot = crate::item::Item::base(&gd, potion);
        pot.pval = 1;
        pot.timeout = 5;
        assert!(!decay_object_pval(&gd, &mut pot, true, false, &mut rng));
        assert_eq!(pot.pval, 1);
    }

    #[test]
    fn wizard_and_debug_entry_follow_dungeon_cc() {
        let gd = load_game_data();
        let mut log = MessageLog::default();
        let mut ps = test_player(&gd, "Wiz");
        // First wizard entry asks; refusal leaves noscore untouched.
        assert!(!toggle_wizard(&mut ps, false, &mut log));
        assert!(!ps.wizard);
        assert_eq!(ps.noscore, 0);
        // Acceptance marks noscore 0x0002 and turns wizard mode on.
        assert!(toggle_wizard(&mut ps, true, &mut log));
        assert!(ps.wizard);
        assert_eq!(ps.noscore, 0x0002);
        // Ctrl-W toggles back off without a prompt.
        assert!(!toggle_wizard(&mut ps, false, &mut log));
        assert_eq!(ps.noscore, 0x0002);
        // Debug commands ask once for noscore 0x0008 and never once
        // wizard mode is on.
        let mut ps = test_player(&gd, "Dbg");
        assert!(!enter_debug_mode_cmd(&mut ps, false, &mut log));
        assert_eq!(ps.noscore, 0);
        assert!(enter_debug_mode_cmd(&mut ps, true, &mut log));
        assert_eq!(ps.noscore, 0x0008);
        ps.wizard = true;
        let mut fresh = test_player(&gd, "Dbg2");
        fresh.wizard = true;
        assert!(enter_debug_mode_cmd(&mut fresh, false, &mut log));
        assert_eq!(fresh.noscore, 0);
    }

    #[test]
    fn god_temple_attributes_follow_q_god() {
        let gd = load_game_data();
        let mut ps = test_player(&gd, "Temple");
        ps.god = 1; // Eru
        ps.god_temple_mindepth = 10;
        ps.god_min_plev = 7;
        let eru = god_temple_def(&gd, &ps);
        assert_eq!((eru.mindepth, eru.maxdepth, eru.min_plev), (10, 14, 7));
        assert_eq!(eru.floors[0].feat, 88);
        assert!(eru.flags.iter().any(|f| f == "EMPTY"));
        assert!(eru.rules.iter().any(|r| r.mflags.contains(&"EVIL".to_string())));
        assert_eq!(eru.rule_percents.len(), 100);
        assert!(eru.rule_percents.iter().any(|&r| r == 1));
        // Melkor: glass outer wall, three floor kinds, SMALL/LAVA_RIVERS.
        ps.god = 4;
        let mel = god_temple_def(&gd, &ps);
        assert_eq!(mel.outer_wall, 188);
        assert_eq!(mel.floors.len(), 3);
        assert!(mel.flags.iter().any(|f| f == "LAVA_RIVERS"));
        assert!(!mel.flags.iter().any(|f| f == "NO_DESTROY"));
        // Tulkas and Mandos share the granite base but differ in monsters.
        ps.god = 3;
        let tul = god_temple_def(&gd, &ps);
        ps.god = 9;
        let man = god_temple_def(&gd, &ps);
        assert_eq!(tul.outer_wall, man.outer_wall);
        assert!(tul.rules[0].mflags.contains(&"DEMON".to_string()));
        assert!(man.rules[0].mflags.contains(&"UNDEAD".to_string()));
        // The five-level range is applied for every god.
        assert_eq!(tul.maxdepth, tul.mindepth + 4);
        assert_eq!(man.maxdepth, man.mindepth + 4);
        // The level generator consumes the override's tables: Melkor's
        // temple uses his three floor kinds and the glass fill.
        let (floors, fills) = crate::map::init_feat_info(&mel, mel.mindepth);
        assert!(floors.contains(&88) && floors.contains(&94) && floors.contains(&102));
        assert!(fills.contains(&188));
    }

