    #[test]
    fn thieves_gen_hook_never_loses_items() {
        use bevy::ecs::system::RunSystemOnce;
        use bevy::prelude::*;
        let gd = load_game_data();
        let mut world = World::new();
        world.insert_resource(load_game_data());
        world.insert_resource(crate::render::TileAssets {
            font: Default::default(),
            bg_image: Default::default(),
            bg_layout: Default::default(),
            fg_image: Default::default(),
            fg_layout: Default::default(),
        });
        world.insert_resource(crate::map::blank_pub(crate::map::T_GRANITE));
        world.insert_resource(crate::item::Inventory::default());
        world.insert_resource(test_player(&gd, "Thief"));
        world.insert_resource(MessageLog::default());
        world
            .run_system_once(
                |mut commands: Commands,
                 gd: Res<GameData>,
                 tiles: Res<TileAssets>,
                 map: Res<Map>,
                 mut inv: ResMut<Inventory>,
                 mut ps: ResMut<PlayerState>,
                 mut log: ResMut<MessageLog>| {
                    let mut rng = crate::rng::new_seeded_rng(9);
                    let sword = gd
                        .objects
                        .iter()
                        .position(|o| o.tval == crate::data::TV_SWORD)
                        .expect("a sword");
                    inv.pack.push(crate::item::Item::base(&gd, sword));
                    inv.pack.push(crate::item::Item::base(&gd, sword));
                    inv.equip[crate::data::SLOT_WEAPON] =
                        Some(crate::item::Item::base(&gd, sword));
                    quest_thieves_gen_hook(
                        &mut commands,
                        &gd,
                        &tiles,
                        &map,
                        &mut inv,
                        &mut ps,
                        &mut rng,
                        &mut log,
                    );
                },
            )
            .unwrap();
        world.flush();
        // Every stolen item lands in the great hall even when no walkable
        // grid is found near the anchor (the shared setup/transition hook).
        let mut q = world.query::<&crate::item::FloorItem>();
        let total: usize = q.iter(&world).map(|f| f.stack.len()).sum();
        assert_eq!(total, 3, "no item may be destroyed by the ambush");
    }

    #[test]
    fn critical_norm_skill_consumes_deadly_and_has_no_level_term() {
        let gd = load_game_data();
        let mut ps = test_player(&gd, "Crit");
        ps.tim_deadly = 2;
        let mut rng = crate::rng::new_seeded_rng(4);
        let mut log = MessageLog::default();
        // Divine Aim forces a *GREAT* hit and consumes exactly one charge
        // (cmd1.cc:189-195).
        assert_eq!(
            critical_norm_skill_mut(&mut ps, 30, 0, 0, false, 10, &mut rng, &mut log),
            3 * 10 + 20
        );
        assert_eq!(ps.tim_deadly, 1);
        assert!(log.lines.iter().any(|l| l.contains("*GREAT*")));
        assert_eq!(
            critical_norm_skill_mut(&mut ps, 30, 0, 0, false, 10, &mut rng, &mut log),
            3 * 10 + 20
        );
        assert_eq!(ps.tim_deadly, 0);
        assert!(log.lines.iter().any(|l| l.contains("less accurate")));
        // cmd1.cc critical_norm has no player-level term: with no weapon,
        // no plusses and no skills the chance is zero even at level 50.
        ps.skills.clear();
        ps.skill_mods.clear();
        ps.level = 50;
        let mut crits = 0;
        for _ in 0..2000 {
            if critical_norm_skill(&ps, 0, 0, 0, false, 10, &mut rng, &mut log) > 10 {
                crits += 1;
            }
        }
        assert_eq!(crits, 0, "no hidden level bonus");
    }

